  // spellchecker: ignore-next-line
  moderator discussion_board_moderators @relation("discussion_board_account_actions_of_discussion_board_m_8e40e126", fields: [discussion_board_moderator_id], references: [id], onDelete: Cascade, map: "discussion_board_account_actions_discussion_board_mode_a7c2a922")
  reverser discussion_board_moderators? @relation("discussion_board_account_actions_of_reversed_by_moderator_id", fields: [reversed_by_moderator_id], references: [id], onDelete: Cascade)

  @@index([reversed_by_moderator_id])

  // spellchecker: ignore-next-line
