  last_login_at DateTime? @db.Timestamptz

  /// Timestamp when the moderator account was created by system administrator.
  created_at DateTime @db.Timestamptz

  /// Timestamp when the moderator account was last updated.
  updated_at DateTime @db.Timestamptz

  /// Timestamp when moderator privileges were revoked and account deleted.
  /// Supports soft deletion for audit trail.
  deleted_at DateTime? @db.Timestamptz

  //----
  // RELATIONS
  //----
  discussion_board_moderator_sessions                             discussion_board_moderator_sessions[]
  discussion_board_password_reset_of_moderators                   discussion_board_password_reset_of_moderators[]
