  discussion_board_moderation_logs                                discussion_board_moderation_logs[]
  discussion_board_account_actions_of_discussion_board_m_8e40e126 discussion_board_account_actions[]              @relation("discussion_board_account_actions_of_discussion_board_m_8e40e126")
  discussion_board_account_actions_of_reversed_by_moderator_id    discussion_board_account_actions[]              @relation("discussion_board_account_actions_of_reversed_by_moderator_id")

  @@unique([email])
  @@unique([username])
  @@index([is_active])
  @@index([created_at])
  @@index([deleted_at])
}

/// Active authentication sessions for registered members enabling secure
