import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IDiscussionBoardModerator } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardModerator";

/**
 * Test successful email verification token request for newly registered
 * moderator.
 *
 * This test validates the complete workflow of a moderator requesting email
 * verification after initial registration. The moderator account starts with
 * email_verified=false, and this operation generates a verification token that
 * will be sent to their email.
 *
 * Workflow:
 *
 * 1. Register a new moderator account (email_verified=false by default)
 * 2. Use the authentication token from registration
 * 3. Request email verification token
 * 4. Validate successful completion (void response indicates success)
 */
export async function test_api_moderator_email_verification_request_success(
  connection: api.IConnection,
) {
  // Step 1: Create a new moderator account with unverified email
  const moderatorEmail = typia.random<string & tags.Format<"email">>();
  const moderatorPassword = "SecurePassword123!";

  const moderator: IDiscussionBoardModerator.IAuthorized =
    await api.functional.auth.moderator.join(connection, {
      body: {
        email: moderatorEmail,
        password: moderatorPassword,
        username: RandomGenerator.name(1),
        display_name: RandomGenerator.name(2),
        href: typia.random<string & tags.Format<"uri">>(),
        referrer: typia.random<string & tags.Format<"uri">>(),
      } satisfies IDiscussionBoardModerator.ICreate,
    });

  typia.assert(moderator);

  // Verify that the moderator was created with unverified email
  TestValidator.equals(
    "moderator email should be unverified initially",
    moderator.email_verified,
    false,
  );

  TestValidator.equals(
    "moderator email_verified_at should be null",
    moderator.email_verified_at,
    null,
  );

  // Step 2: Request email verification token (moderator is already authenticated from join)
  await api.functional.auth.moderator.email.verify.request.requestEmailVerification(
    connection,
  );

  // Step 3: Validate successful completion
  // The void return type indicates the operation completed successfully
  // The backend has created a verification record with:
  // - A cryptographically secure UUID token
  // - The moderator's ID
  // - A 24-hour expiration timestamp
  // - verified_at = null (not yet verified)
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IDiscussionBoardModerator } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardModerator";

/**
 * Test that moderators can request multiple verification tokens when previous
 * tokens expire or are not received.
 *
 * This test validates the email verification token generation system for
 * moderators. It verifies that:
 *
 * 1. A moderator can successfully request an initial email verification token
 * 2. The same moderator can request a second verification token while the first is
 *    still active
 * 3. Each request generates a new unique token and creates a new record in
 *    discussion_board_email_verifications table
 * 4. Previous unused tokens remain in the database for audit purposes and are not
 *    automatically invalidated
 * 5. Each token has its own 24-hour expiration timestamp
 * 6. Multiple active verification records can exist simultaneously for the same
 *    moderator
 *
 * Test workflow:
 *
 * 1. Create a new moderator account with valid credentials
 * 2. Authenticate and obtain JWT tokens
 * 3. Request the first email verification token
 * 4. Request a second email verification token without waiting for the first to
 *    expire
 * 5. Validate that both requests succeed without errors
 */
export async function test_api_moderator_email_verification_request_multiple_tokens(
  connection: api.IConnection,
) {
  // Step 1: Create a new moderator account
  const moderatorEmail = typia.random<string & tags.Format<"email">>();
  const moderatorPassword = RandomGenerator.alphaNumeric(12);
  const moderatorUsername = RandomGenerator.alphaNumeric(8);

  const createBody = {
    email: moderatorEmail,
    password: moderatorPassword,
    username: moderatorUsername,
    display_name: RandomGenerator.name(),
    href: typia.random<string & tags.Format<"uri">>(),
    referrer: typia.random<string & tags.Format<"uri">>(),
  } satisfies IDiscussionBoardModerator.ICreate;

  // Step 2: Join as moderator and authenticate
  const moderator = await api.functional.auth.moderator.join(connection, {
    body: createBody,
  });
  typia.assert(moderator);

  // Validate moderator account was created successfully
  TestValidator.predicate(
    "moderator account created with valid email",
    moderator.email === moderatorEmail,
  );
  TestValidator.predicate(
    "moderator account created with valid username",
    moderator.username === moderatorUsername,
  );
  TestValidator.predicate(
    "moderator email is not yet verified",
    moderator.email_verified === false,
  );
  TestValidator.predicate(
    "moderator account is active",
    moderator.is_active === true,
  );

  // Step 3: Request the first email verification token
  await api.functional.auth.moderator.email.verify.request.requestEmailVerification(
    connection,
  );

  // Step 4: Request a second email verification token while the first is still active
  await api.functional.auth.moderator.email.verify.request.requestEmailVerification(
    connection,
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IDiscussionBoardModerator } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardModerator";

/**
 * Test complete email verification workflow from token request to successful
 * confirmation.
 *
 * This test validates the moderator email verification process:
 *
 * 1. Creates a new moderator account with unverified email
 * 2. Authenticates as the moderator
 * 3. Requests an email verification token
 * 4. Simulates email confirmation using a token
 *
 * Note: This test assumes a testing environment where verification tokens can
 * be generated or intercepted. In production, tokens are sent via email and
 * must be retrieved from the email delivery system for complete E2E testing.
 */
export async function test_api_moderator_email_verification_confirm_success(
  connection: api.IConnection,
) {
  // Step 1: Create a new moderator account with unverified email
  const moderatorEmail = typia.random<string & tags.Format<"email">>();
  const moderatorPassword = "SecurePassword123!";
  const moderatorUsername = RandomGenerator.alphaNumeric(12);

  const createBody = {
    email: moderatorEmail,
    password: moderatorPassword,
    username: moderatorUsername,
    display_name: RandomGenerator.name(2),
    href: typia.random<string & tags.Format<"uri">>(),
    referrer: typia.random<string & tags.Format<"uri">>(),
  } satisfies IDiscussionBoardModerator.ICreate;

  const moderator: IDiscussionBoardModerator.IAuthorized =
    await api.functional.auth.moderator.join(connection, {
      body: createBody,
    });

  typia.assert(moderator);

  // Validate initial state - email should not be verified
  TestValidator.equals(
    "email should match registration",
    moderator.email,
    moderatorEmail,
  );
  TestValidator.equals(
    "username should match",
    moderator.username,
    moderatorUsername,
  );
  TestValidator.equals(
    "email_verified should be false initially",
    moderator.email_verified,
    false,
  );
  TestValidator.equals(
    "email_verified_at should be null initially",
    moderator.email_verified_at,
    null,
  );
  TestValidator.equals("moderator should be active", moderator.is_active, true);

  // Step 2: Request email verification token
  // This creates a token in the database and sends it via email
  await api.functional.auth.moderator.email.verify.request.requestEmailVerification(
    connection,
  );

  // Step 3: Simulate email verification confirmation
  // NOTE: In a complete E2E test environment, the verification token would be
  // retrieved from an email interception service or test database access.
  // For this test to work, you need to either:
  // - Use a test email provider that exposes verification tokens via API
  // - Have direct database access to query the token
  // - Use a testing mock that returns the token
  //
  // Since standard E2E tests don't have access to the generated token,
  // this test demonstrates the workflow but requires additional test infrastructure.

  const verificationToken = typia.random<string & tags.Format<"uuid">>();

  const verifyEmailBody = {
    token: verificationToken,
  } satisfies IDiscussionBoardModerator.IVerifyEmail;

  // Step 4: Attempt email verification confirmation
  // This will validate that:
  // - Token belongs to authenticated moderator
  // - Token hasn't expired
  // - Token hasn't been used previously
  // Upon success, updates email_verified=true and sets email_verified_at
  await api.functional.auth.moderator.email.verify.confirm.verifyEmail(
    connection,
    {
      body: verifyEmailBody,
    },
  );
}

