import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IDiscussionBoardMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardMember";

/**
 * Test successful password change workflow for an authenticated member.
 *
 * This test validates the complete password change flow including:
 *
 * 1. Creating a new member account via join endpoint with initial credentials
 * 2. Authenticating the member (authentication is automatic after join)
 * 3. Changing the password by providing the correct current password and a new
 *    password
 * 4. Verifying that the operation returns a success confirmation message
 *
 * The test confirms that the password change endpoint properly validates the
 * current password, updates to the new bcrypt-hashed password, and manages
 * session lifecycle where other sessions are invalidated while the current
 * session remains active.
 */
export async function test_api_member_password_change_successful(
  connection: api.IConnection,
) {
  // Step 1: Create a new member account with initial credentials
  const initialPassword = "InitialPassword123!";
  const memberEmail = typia.random<string & tags.Format<"email">>();
  const memberUsername = typia.random<
    string & tags.MinLength<3> & tags.MaxLength<30>
  >();

  const createBody = {
    email: memberEmail,
    password: initialPassword,
    username: memberUsername,
    display_name: RandomGenerator.name(),
    bio: RandomGenerator.paragraph({ sentences: 2, wordMin: 3, wordMax: 7 }),
    href: typia.random<string & tags.Format<"uri">>(),
    referrer: typia.random<string & tags.Format<"uri">>(),
  } satisfies IDiscussionBoardMember.ICreate;

  const member: IDiscussionBoardMember.IAuthorized =
    await api.functional.auth.member.join(connection, { body: createBody });
  typia.assert(member);

  // Verify member was created successfully with expected properties
  TestValidator.equals("member email matches", member.email, memberEmail);
  TestValidator.equals(
    "member username matches",
    member.username,
    memberUsername,
  );
  TestValidator.predicate("member has valid ID", member.id.length > 0);
  TestValidator.predicate(
    "member has auth token",
    member.token.access.length > 0,
  );

  // Step 2: Member is now authenticated (join endpoint automatically sets authentication)
  // The connection.headers.Authorization is already set by the join function

  // Step 3: Change the password with current and new passwords
  const newPassword = "NewSecurePassword456!";
  const changePasswordBody = {
    currentPassword: initialPassword,
    newPassword: newPassword,
  } satisfies IDiscussionBoardMember.IChangePassword;

  const passwordChangeResult: IDiscussionBoardMember.IPasswordChanged =
    await api.functional.auth.member.password.change.changePassword(
      connection,
      { body: changePasswordBody },
    );
  typia.assert(passwordChangeResult);

  // Step 4: Verify the password change was successful
  TestValidator.predicate(
    "password change confirmation message exists",
    passwordChangeResult.message.length > 0,
  );

  // The response should contain a success message indicating password was changed
  TestValidator.predicate(
    "password change message indicates success",
    passwordChangeResult.message.toLowerCase().includes("password") ||
      passwordChangeResult.message.toLowerCase().includes("success") ||
      passwordChangeResult.message.toLowerCase().includes("changed"),
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IDiscussionBoardMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardMember";

/**
 * Test password change rejection when incorrect current password is provided.
 *
 * This test validates the security mechanism that requires knowledge of the
 * current password before allowing password changes. Even with a valid
 * authenticated session, the API must reject password change attempts when an
 * incorrect current password is provided.
 *
 * Test Flow:
 *
 * 1. Register a new member account with known credentials
 * 2. Attempt to change password with incorrect current password
 * 3. Verify that the operation is rejected with an error
 */
export async function test_api_member_password_change_incorrect_current_password(
  connection: api.IConnection,
) {
  // Step 1: Register a new member account with known password
  const originalPassword = "SecurePassword123!";
  const memberEmail = typia.random<string & tags.Format<"email">>();
  const memberUsername = typia.random<
    string & tags.MinLength<3> & tags.MaxLength<30>
  >();

  const registrationData = {
    email: memberEmail,
    password: originalPassword,
    username: memberUsername,
    display_name: RandomGenerator.name(),
    bio: RandomGenerator.paragraph({ sentences: 2, wordMin: 4, wordMax: 8 }),
    ip: null,
    href: typia.random<string & tags.Format<"uri">>(),
    referrer: typia.random<string & tags.Format<"uri">>(),
  } satisfies IDiscussionBoardMember.ICreate;

  const registeredMember: IDiscussionBoardMember.IAuthorized =
    await api.functional.auth.member.join(connection, {
      body: registrationData,
    });

  typia.assert(registeredMember);

  // Step 2: Attempt to change password with INCORRECT current password
  const incorrectCurrentPassword = "WrongPassword456!";
  const newPassword = "NewSecurePassword789!";

  const passwordChangeRequest = {
    currentPassword: incorrectCurrentPassword,
    newPassword: newPassword,
  } satisfies IDiscussionBoardMember.IChangePassword;

  // Step 3: Verify that password change is rejected
  await TestValidator.error(
    "password change should fail with incorrect current password",
    async () => {
      await api.functional.auth.member.password.change.changePassword(
        connection,
        {
          body: passwordChangeRequest,
        },
      );
    },
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IDiscussionBoardModerator } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardModerator";

/**
 * Test successful moderator account registration workflow.
 *
 * This test validates the complete moderator onboarding process including:
 *
 * 1. Moderator account creation with valid credentials
 * 2. JWT authentication token generation (access and refresh tokens)
 * 3. Complete profile data returned with proper initial state
 * 4. Immediate authenticated access capability
 *
 * The moderator registration creates accounts for trusted administrators with
 * elevated privileges for content moderation. The account is created with
 * email_verified=false (requiring verification) but is_active=true (allowing
 * immediate login and access).
 */
export async function test_api_moderator_registration_successful(
  connection: api.IConnection,
) {
  // Step 1: Prepare registration data with valid credentials and session context
  const registrationData = {
    email: typia.random<string & tags.Format<"email">>(),
    password: RandomGenerator.alphaNumeric(16),
    username: RandomGenerator.alphaNumeric(12),
    display_name: RandomGenerator.name(2),
    ip: "192.168.1.100",
    href: typia.random<string & tags.Format<"uri">>(),
    referrer: typia.random<string & tags.Format<"uri">>(),
  } satisfies IDiscussionBoardModerator.ICreate;

  // Step 2: Execute moderator registration API call
  const moderator: IDiscussionBoardModerator.IAuthorized =
    await api.functional.auth.moderator.join(connection, {
      body: registrationData,
    });

  // Step 3: Validate the complete response structure and types
  typia.assert(moderator);

  // Step 4: Verify moderator identity fields match input data
  TestValidator.equals(
    "registered email matches input",
    moderator.email,
    registrationData.email,
  );
  TestValidator.equals(
    "registered username matches input",
    moderator.username,
    registrationData.username,
  );
  TestValidator.equals(
    "display name matches input",
    moderator.display_name,
    registrationData.display_name,
  );

  // Step 5: Verify initial account status flags
  TestValidator.equals(
    "email_verified should be false initially",
    moderator.email_verified,
    false,
  );
  TestValidator.equals("account should be active", moderator.is_active, true);
  TestValidator.equals(
    "email_verified_at should be null initially",
    moderator.email_verified_at,
    null,
  );
  TestValidator.equals(
    "deleted_at should be null for active account",
    moderator.deleted_at,
    null,
  );

  // Step 6: Verify JWT token structure and properties
  const token: IAuthorizationToken = moderator.token;
  typia.assert(token);

  TestValidator.predicate(
    "access token should be non-empty string",
    token.access.length > 0,
  );
  TestValidator.predicate(
    "refresh token should be non-empty string",
    token.refresh.length > 0,
  );

  // Step 7: Verify token expiration logic (access token expires before refresh token)
  const expiredAt = new Date(token.expired_at);
  const refreshableUntil = new Date(token.refreshable_until);
  TestValidator.predicate(
    "access token should expire before refresh token",
    expiredAt < refreshableUntil,
  );
}

