import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IDiscussionBoardAccountAction } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardAccountAction";
import type { IDiscussionBoardMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardMember";
import type { IDiscussionBoardModerator } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardModerator";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IPageIDiscussionBoardMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIDiscussionBoardMember";

/**
 * Test member search filtering by account suspension status.
 *
 * This test validates that moderators can effectively filter member search
 * results based on suspension status. The test creates multiple member
 * accounts, suspends some of them using account action operations, and then
 * verifies that search filtering works correctly for:
 *
 * 1. Finding only suspended members (isSuspended=true)
 * 2. Finding only active non-suspended members (isSuspended=false)
 * 3. Finding all members regardless of status (filter omitted)
 *
 * This ensures moderators can identify suspended accounts for review or
 * unsuspension actions, and can distinguish between active and suspended member
 * populations.
 */
export async function test_api_member_search_suspension_status_filter(
  connection: api.IConnection,
) {
  // Step 1: Create and authenticate moderator account
  const moderator = await api.functional.auth.moderator.join(connection, {
    body: {
      email: typia.random<string & tags.Format<"email">>(),
      password: "moderator123!",
      username: RandomGenerator.alphaNumeric(8),
      display_name: RandomGenerator.name(2),
      href: "https://example.com/moderator/join",
      referrer: "https://example.com/login",
    } satisfies IDiscussionBoardModerator.ICreate,
  });
  typia.assert(moderator);

  // Step 2: Create multiple member accounts for testing
  const memberCount = 5;
  const createdMembers: IDiscussionBoardMember.IAuthorized[] = [];

  for (let i = 0; i < memberCount; i++) {
    const member = await api.functional.auth.member.join(connection, {
      body: {
        email: typia.random<string & tags.Format<"email">>(),
        password: "member123!",
        username: RandomGenerator.alphaNumeric(10),
        display_name: RandomGenerator.name(2),
        href: "https://example.com/member/join",
        referrer: "https://example.com/home",
      } satisfies IDiscussionBoardMember.ICreate,
    });
    typia.assert(member);
    createdMembers.push(member);
  }

  TestValidator.equals(
    "created expected number of members",
    createdMembers.length,
    memberCount,
  );

  // Step 3: Suspend some members (suspend first 2 members)
  const suspendCount = 2;
  const suspendedMemberIds: string[] = [];

  for (let i = 0; i < suspendCount; i++) {
    const accountAction =
      await api.functional.discussionBoard.moderator.accountActions.create(
        connection,
        {
          body: {
            discussion_board_member_id: createdMembers[i].id,
            action_type: "suspension",
            reason: `Test suspension ${i + 1} - policy violation`,
            duration_days: 7,
          } satisfies IDiscussionBoardAccountAction.ICreate,
        },
      );
    typia.assert(accountAction);
    suspendedMemberIds.push(createdMembers[i].id);
  }

  TestValidator.equals(
    "suspended expected number of members",
    suspendedMemberIds.length,
    suspendCount,
  );

  // Step 4: Search with isSuspended=true filter (should return only suspended members)
  const suspendedSearch =
    await api.functional.discussionBoard.moderator.members.index(connection, {
      body: {
        isSuspended: true,
        page: 1,
        limit: 50,
      } satisfies IDiscussionBoardMember.IRequest,
    });
  typia.assert(suspendedSearch);

  TestValidator.predicate(
    "suspended search returns at least the suspended members",
    suspendedSearch.data.length >= suspendCount,
  );

  const foundSuspendedIds = suspendedSearch.data
    .filter((member) => suspendedMemberIds.includes(member.id))
    .map((member) => member.id);

  TestValidator.equals(
    "all suspended members found in suspended search",
    foundSuspendedIds.sort(),
    suspendedMemberIds.sort(),
  );

  // Step 5: Search with isSuspended=false filter (should return only non-suspended members)
  const activeSearch =
    await api.functional.discussionBoard.moderator.members.index(connection, {
      body: {
        isSuspended: false,
        page: 1,
        limit: 50,
      } satisfies IDiscussionBoardMember.IRequest,
    });
  typia.assert(activeSearch);

  const activeMemberIds = createdMembers
    .filter((member) => !suspendedMemberIds.includes(member.id))
    .map((member) => member.id);

  const foundActiveIds = activeSearch.data
    .filter((member) => activeMemberIds.includes(member.id))
    .map((member) => member.id);

  TestValidator.equals(
    "all active members found in active search",
    foundActiveIds.sort(),
    activeMemberIds.sort(),
  );

  // Verify no suspended members in active search
  const suspendedInActiveSearch = activeSearch.data.filter((member) =>
    suspendedMemberIds.includes(member.id),
  );

  TestValidator.equals(
    "no suspended members in active search results",
    suspendedInActiveSearch.length,
    0,
  );

  // Step 6: Search without isSuspended filter (should return all members)
  const allMembersSearch =
    await api.functional.discussionBoard.moderator.members.index(connection, {
      body: {
        page: 1,
        limit: 50,
      } satisfies IDiscussionBoardMember.IRequest,
    });
  typia.assert(allMembersSearch);

  const allCreatedMemberIds = createdMembers.map((member) => member.id);
  const foundAllIds = allMembersSearch.data
    .filter((member) => allCreatedMemberIds.includes(member.id))
    .map((member) => member.id);

  TestValidator.equals(
    "all created members found when no filter applied",
    foundAllIds.sort(),
    allCreatedMemberIds.sort(),
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IDiscussionBoardMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardMember";
import type { IDiscussionBoardModerator } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardModerator";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IPageIDiscussionBoardMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIDiscussionBoardMember";

/**
 * Test member search filtering by registration date range using createdAfter
 * and createdBefore parameters.
 *
 * This test validates temporal filtering capabilities for member search:
 *
 * 1. Moderator authenticates to access member search functionality
 * 2. Multiple members are registered to create a test dataset
 * 3. Search with date range filters encompassing current time is executed
 * 4. Results are validated to contain members within the specified date range
 * 5. ISO 8601 date-time format parsing is verified
 * 6. Single-sided filters are tested for independent operation
 */
export async function test_api_member_search_date_range_registration_filter(
  connection: api.IConnection,
) {
  // Step 1: Create and authenticate moderator account
  const moderatorData = {
    email: typia.random<string & tags.Format<"email">>(),
    password: "SecureMod123!",
    username: RandomGenerator.alphaNumeric(10),
    display_name: RandomGenerator.name(),
    href: "https://example.com/moderator/join" satisfies string &
      tags.Format<"uri">,
    referrer: "https://example.com/admin" satisfies string & tags.Format<"uri">,
  } satisfies IDiscussionBoardModerator.ICreate;

  const moderator: IDiscussionBoardModerator.IAuthorized =
    await api.functional.auth.moderator.join(connection, {
      body: moderatorData,
    });
  typia.assert(moderator);

  // Step 2: Define date range boundaries around current time
  const now = new Date();
  const oneHourAgo = new Date(now.getTime() - 60 * 60 * 1000);
  const oneHourLater = new Date(now.getTime() + 60 * 60 * 1000);
  const twoDaysAgo = new Date(now.getTime() - 2 * 24 * 60 * 60 * 1000);
  const twoDaysLater = new Date(now.getTime() + 2 * 24 * 60 * 60 * 1000);

  // Step 3: Create members that will have current timestamps
  const testMembers = await ArrayUtil.asyncRepeat(5, async (index) => {
    const memberData = {
      email: typia.random<string & tags.Format<"email">>(),
      password: "MemberPass123!",
      username: `test_member_${index}_${RandomGenerator.alphaNumeric(6)}`,
      display_name: RandomGenerator.name(),
      href: "https://example.com/member/join" satisfies string &
        tags.Format<"uri">,
      referrer: "https://example.com/home" satisfies string &
        tags.Format<"uri">,
    } satisfies IDiscussionBoardMember.ICreate;

    const member: IDiscussionBoardMember.IAuthorized =
      await api.functional.auth.member.join(connection, {
        body: memberData,
      });
    typia.assert(member);
    return member;
  });

  // Step 4: Search with date range that encompasses current time (should include all test members)
  const currentRangeRequest = {
    page: 1 satisfies number & tags.Type<"int32"> & tags.Minimum<1>,
    limit: 50 satisfies number &
      tags.Type<"int32"> &
      tags.Minimum<1> &
      tags.Maximum<100>,
    createdAfter: oneHourAgo.toISOString() satisfies string &
      tags.Format<"date-time">,
    createdBefore: oneHourLater.toISOString() satisfies string &
      tags.Format<"date-time">,
  } satisfies IDiscussionBoardMember.IRequest;

  const rangeResults: IPageIDiscussionBoardMember.ISummary =
    await api.functional.discussionBoard.moderator.members.index(connection, {
      body: currentRangeRequest,
    });
  typia.assert(rangeResults);

  // Step 5: Validate results contain the test members
  TestValidator.predicate(
    "Date range search should return results",
    rangeResults.data.length > 0,
  );

  const testMemberIds = testMembers.map((m) => m.id);
  const returnedIds = rangeResults.data.map((r) => r.id);

  TestValidator.predicate(
    "Date range results should include test members created within the range",
    testMemberIds.some((id) => returnedIds.includes(id)),
  );

  // Step 6: Test single-sided filter - only createdAfter (members from 2 days ago onwards)
  const afterOnlyRequest = {
    page: 1 satisfies number & tags.Type<"int32"> & tags.Minimum<1>,
    limit: 50 satisfies number &
      tags.Type<"int32"> &
      tags.Minimum<1> &
      tags.Maximum<100>,
    createdAfter: twoDaysAgo.toISOString() satisfies string &
      tags.Format<"date-time">,
  } satisfies IDiscussionBoardMember.IRequest;

  const afterOnlyResults: IPageIDiscussionBoardMember.ISummary =
    await api.functional.discussionBoard.moderator.members.index(connection, {
      body: afterOnlyRequest,
    });
  typia.assert(afterOnlyResults);

  TestValidator.predicate(
    "createdAfter filter should return members including recently created ones",
    afterOnlyResults.data.length >= testMembers.length,
  );

  // Step 7: Test single-sided filter - only createdBefore (members before 2 days from now)
  const beforeOnlyRequest = {
    page: 1 satisfies number & tags.Type<"int32"> & tags.Minimum<1>,
    limit: 50 satisfies number &
      tags.Type<"int32"> &
      tags.Minimum<1> &
      tags.Maximum<100>,
    createdBefore: twoDaysLater.toISOString() satisfies string &
      tags.Format<"date-time">,
  } satisfies IDiscussionBoardMember.IRequest;

  const beforeOnlyResults: IPageIDiscussionBoardMember.ISummary =
    await api.functional.discussionBoard.moderator.members.index(connection, {
      body: beforeOnlyRequest,
    });
  typia.assert(beforeOnlyResults);

  TestValidator.predicate(
    "createdBefore filter should return members including test members",
    beforeOnlyResults.data.length >= testMembers.length,
  );

  // Step 8: Validate pagination structure
  TestValidator.predicate(
    "Pagination data should be valid",
    rangeResults.pagination.current >= 0 &&
      rangeResults.pagination.limit > 0 &&
      rangeResults.pagination.records >= 0 &&
      rangeResults.pagination.pages >= 0,
  );

  // Step 9: Test ISO 8601 format with narrow range to verify precise filtering
  const veryRecentTime = new Date(now.getTime() - 5000);
  const veryFutureTime = new Date(now.getTime() + 5000);

  const preciseRangeRequest = {
    page: 1 satisfies number & tags.Type<"int32"> & tags.Minimum<1>,
    limit: 100 satisfies number &
      tags.Type<"int32"> &
      tags.Minimum<1> &
      tags.Maximum<100>,
    createdAfter: veryRecentTime.toISOString() satisfies string &
      tags.Format<"date-time">,
    createdBefore: veryFutureTime.toISOString() satisfies string &
      tags.Format<"date-time">,
  } satisfies IDiscussionBoardMember.IRequest;

  const preciseResults: IPageIDiscussionBoardMember.ISummary =
    await api.functional.discussionBoard.moderator.members.index(connection, {
      body: preciseRangeRequest,
    });
  typia.assert(preciseResults);

  TestValidator.predicate(
    "ISO 8601 date-time format should be correctly parsed and applied",
    preciseResults.pagination.records >= 0,
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IDiscussionBoardMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardMember";
import type { IDiscussionBoardModerator } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardModerator";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IPageIDiscussionBoardMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIDiscussionBoardMember";

/**
 * Test member search filtering by last login activity using lastLoginAfter
 * parameter.
 *
 * This test validates activity-based filtering of members through the moderator
 * search API. The workflow includes:
 *
 * 1. Moderator authenticates to gain search privileges
 * 2. Multiple member accounts are created (some will login, some won't)
 * 3. Selected members perform login operations to update last_login_at timestamps
 * 4. Moderator searches with lastLoginAfter parameter set to recent timestamp (7
 *    days ago)
 * 5. System filters members by last_login_at field
 * 6. Results include only members who logged in after the specified timestamp
 *
 * This helps moderators identify recently active members versus inactive
 * accounts. Members who never logged in (last_login_at is null) are properly
 * handled and excluded.
 */
export async function test_api_member_search_last_login_activity_filter(
  connection: api.IConnection,
) {
  // Step 1: Create and authenticate moderator account
  const moderatorEmail = typia.random<string & tags.Format<"email">>();
  const moderatorPassword = "moderator_pass_123";

  const moderator = await api.functional.auth.moderator.join(connection, {
    body: {
      email: moderatorEmail,
      password: moderatorPassword,
      username: RandomGenerator.alphaNumeric(10),
      display_name: RandomGenerator.name(2),
      href: typia.random<string & tags.Format<"uri">>(),
      referrer: typia.random<string & tags.Format<"uri">>(),
    } satisfies IDiscussionBoardModerator.ICreate,
  });
  typia.assert(moderator);

  // Step 2: Create multiple member accounts (will create 6 members total)
  const memberCount = 6;
  const memberCredentials: Array<{ email: string; password: string }> = [];

  const members = await ArrayUtil.asyncRepeat(memberCount, async (index) => {
    const email = typia.random<string & tags.Format<"email">>();
    const password = `member_pass_${index}`;
    memberCredentials.push({ email, password });

    const member = await api.functional.auth.member.join(connection, {
      body: {
        email,
        password,
        username: RandomGenerator.alphaNumeric(12),
        display_name: RandomGenerator.name(),
        bio: RandomGenerator.paragraph({ sentences: 2 }),
        href: typia.random<string & tags.Format<"uri">>(),
        referrer: typia.random<string & tags.Format<"uri">>(),
      } satisfies IDiscussionBoardMember.ICreate,
    });
    typia.assert(member);
    return member;
  });

  // Step 3: Some members perform login to update last_login_at (first 3 members)
  const loginCount = 3;
  const loggedInMembers: IDiscussionBoardMember.IAuthorized[] = [];

  for (let i = 0; i < loginCount; i++) {
    const credential = memberCredentials[i];

    const loggedInMember = await api.functional.auth.member.login(connection, {
      body: {
        email: credential.email,
        password: credential.password,
        href: typia.random<string & tags.Format<"uri">>(),
        referrer: typia.random<string & tags.Format<"uri">>(),
      } satisfies IDiscussionBoardMember.ILogin,
    });
    typia.assert(loggedInMember);
    loggedInMembers.push(loggedInMember);
  }

  // Step 4: Set lastLoginAfter to 7 days ago (members who logged in just now should be included)
  const sevenDaysAgo = new Date(Date.now() - 7 * 24 * 60 * 60 * 1000);
  const lastLoginAfter = sevenDaysAgo.toISOString();

  // Step 5: Moderator searches with lastLoginAfter parameter
  const searchResult =
    await api.functional.discussionBoard.moderator.members.index(connection, {
      body: {
        page: 1,
        limit: 20,
        lastLoginAfter,
      } satisfies IDiscussionBoardMember.IRequest,
    });
  typia.assert(searchResult);

  // Step 6: Validate search results structure
  TestValidator.predicate(
    "search result should have pagination structure",
    searchResult.pagination !== null && searchResult.pagination !== undefined,
  );

  TestValidator.predicate(
    "search result should have data array",
    Array.isArray(searchResult.data),
  );

  // Step 7: Verify that members who logged in are present in the results
  const returnedMemberIds = searchResult.data.map((m) => m.id);
  const loggedInMemberIds = loggedInMembers.map((m) => m.id);

  for (const loggedInId of loggedInMemberIds) {
    TestValidator.predicate(
      "logged-in member should appear in search results",
      returnedMemberIds.includes(loggedInId),
    );
  }

  // Step 8: Validate pagination metadata
  TestValidator.predicate(
    "pagination current page should be 1",
    searchResult.pagination.current === 1,
  );

  TestValidator.predicate(
    "pagination limit should match request",
    searchResult.pagination.limit === 20,
  );

  TestValidator.predicate(
    "search results should not be empty",
    searchResult.data.length > 0,
  );
}

