  // Step 4: Test sorting by created_at ascending
  const createdAtAsc =
    await api.functional.discussionBoard.moderator.members.index(connection, {
      body: {
        page: 1,
        limit: 100,
        orderBy: "created_at",
        orderDirection: "asc",
      } satisfies IDiscussionBoardMember.IRequest,
