import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IDiscussionBoardAccountAction } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardAccountAction";
import type { IDiscussionBoardMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardMember";
import type { IDiscussionBoardModerator } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardModerator";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IPageIDiscussionBoardMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIDiscussionBoardMember";

/**
 * Test member search with multiple filter criteria including text search,
 * pagination, and ordering.
 *
 * This test validates the member search API's ability to handle complex queries
 * by combining text search filters with ordering and pagination parameters. It
 * creates a diverse member dataset with varied usernames and performs searches
 * to validate that filtering, ordering, and pagination work correctly
 * together.
 *
 * Note: This test focuses on validating observable behavior from the ISummary
 * response (username, display_name). Advanced filters like emailVerified and
 * isSuspended are included in the request to test API acceptance but cannot be
 * validated from the response since ISummary doesn't expose these fields.
 *
 * Test Steps:
 *
 * 1. Create and authenticate moderator account
 * 2. Create 25 test members with varied username patterns
 * 3. Create some members with verification and suspension states
 * 4. Execute complex search combining text query, filters, ordering, and
 *    pagination
 * 5. Validate text search matches username patterns
 * 6. Verify ordering is applied correctly
 * 7. Validate pagination metadata
 */
export async function test_api_member_search_multi_criteria_complex_query(
  connection: api.IConnection,
) {
  // Step 1: Create and authenticate moderator
  const moderatorEmail = typia.random<string & tags.Format<"email">>();
  const moderator = await api.functional.auth.moderator.join(connection, {
    body: {
      email: moderatorEmail,
      password: "moderator123",
      username: typia.random<string & tags.MinLength<3> & tags.MaxLength<30>>(),
      display_name: RandomGenerator.name(2),
      href: typia.random<string & tags.Format<"uri">>(),
      referrer: typia.random<string & tags.Format<"uri">>(),
    } satisfies IDiscussionBoardModerator.ICreate,
  });
  typia.assert(moderator);

  // Step 2: Create diverse member dataset with varied username patterns
  const memberIds: string[] = [];

  // Create 10 members with "john" in username for search testing
  const johnMembers = await ArrayUtil.asyncRepeat(10, async (index) => {
    const username = `john_user_${index}_${RandomGenerator.alphabets(3)}`;
    const memberEmail = typia.random<string & tags.Format<"email">>();

    const member = await api.functional.auth.member.join(connection, {
      body: {
        email: memberEmail,
        password: "password123",
        username: username,
        display_name: index % 2 === 0 ? RandomGenerator.name(2) : null,
        bio: RandomGenerator.paragraph({ sentences: 2 }),
        href: typia.random<string & tags.Format<"uri">>(),
        referrer: typia.random<string & tags.Format<"uri">>(),
      } satisfies IDiscussionBoardMember.ICreate,
    });
    typia.assert(member);
    memberIds.push(member.id);

    return member;
  });

  // Create 15 members without "john" in username for contrast
  const otherMembers = await ArrayUtil.asyncRepeat(15, async (index) => {
    const username = `member_${RandomGenerator.alphabets(8)}_${index}`;
    const memberEmail = typia.random<string & tags.Format<"email">>();

    const member = await api.functional.auth.member.join(connection, {
      body: {
        email: memberEmail,
        password: "password123",
        username: username,
        display_name: RandomGenerator.name(2),
        bio:
          index % 3 === 0 ? RandomGenerator.paragraph({ sentences: 1 }) : null,
        href: typia.random<string & tags.Format<"uri">>(),
        referrer: typia.random<string & tags.Format<"uri">>(),
      } satisfies IDiscussionBoardMember.ICreate,
    });
    typia.assert(member);
    memberIds.push(member.id);

    return member;
  });

  // Step 3: Create some suspensions for testing filter acceptance
  const suspensionCount = Math.min(5, memberIds.length);
  for (let i = 0; i < suspensionCount; i++) {
    const memberId = memberIds[i];

    const suspension =
      await api.functional.discussionBoard.moderator.accountActions.create(
        connection,
        {
          body: {
            discussion_board_member_id: memberId,
            action_type: "suspension",
            reason: "Test suspension for complex query validation",
            duration_days: 7,
          } satisfies IDiscussionBoardAccountAction.ICreate,
        },
      );
    typia.assert(suspension);
  }

  // Step 4: Execute complex search with multiple combined filters
  const searchText = "john";
  const currentTime = new Date();
  const thirtyDaysAgo = new Date(
    currentTime.getTime() - 30 * 24 * 60 * 60 * 1000,
  );

  const searchResults =
    await api.functional.discussionBoard.moderator.members.index(connection, {
      body: {
        page: 1,
        limit: 20,
        search: searchText,
        emailVerified: false,
        isSuspended: false,
        createdAfter: thirtyDaysAgo.toISOString(),
        createdBefore: currentTime.toISOString(),
        orderBy: "username",
        orderDirection: "asc",
      } satisfies IDiscussionBoardMember.IRequest,
    });
  typia.assert(searchResults);

  // Step 5: Validate text search matches username patterns
  TestValidator.predicate(
    "search results should contain members",
    searchResults.data.length > 0,
  );

  for (const result of searchResults.data) {
    TestValidator.predicate(
      `username "${result.username}" should contain search text "${searchText}"`,
      result.username.toLowerCase().includes(searchText.toLowerCase()),
    );
  }

  // Step 6: Verify ordering is applied correctly (ascending by username)
  if (searchResults.data.length > 1) {
    for (let i = 0; i < searchResults.data.length - 1; i++) {
      const currentUsername = searchResults.data[i].username;
      const nextUsername = searchResults.data[i + 1].username;

      TestValidator.predicate(
        `username ordering: "${currentUsername}" should be <= "${nextUsername}"`,
        currentUsername.localeCompare(nextUsername) <= 0,
      );
    }
  }

  // Step 7: Validate pagination metadata
  TestValidator.equals(
    "pagination current page",
    searchResults.pagination.current,
    1,
  );

  TestValidator.equals("pagination limit", searchResults.pagination.limit, 20);

  TestValidator.predicate(
    "pagination records should be at least the data length",
    searchResults.pagination.records >= searchResults.data.length,
  );

  TestValidator.equals(
    "pagination pages calculation",
    searchResults.pagination.pages,
    Math.ceil(
      searchResults.pagination.records / searchResults.pagination.limit,
    ),
  );

  // Additional validation: Test pagination with page 2 if enough results
  if (searchResults.pagination.pages > 1) {
    const page2Results =
      await api.functional.discussionBoard.moderator.members.index(connection, {
        body: {
          page: 2,
          limit: 20,
          search: searchText,
          orderBy: "username",
          orderDirection: "asc",
        } satisfies IDiscussionBoardMember.IRequest,
      });
    typia.assert(page2Results);

    TestValidator.equals(
      "second page current page",
      page2Results.pagination.current,
      2,
    );

    // Validate no overlap between page 1 and page 2
    if (searchResults.data.length > 0 && page2Results.data.length > 0) {
      const page1Usernames = searchResults.data.map((m) => m.username);
      const page2Usernames = page2Results.data.map((m) => m.username);

      const hasOverlap = page1Usernames.some((username) =>
        page2Usernames.includes(username),
      );

      TestValidator.predicate(
        "page 1 and page 2 should have no overlapping members",
        !hasOverlap,
      );
    }
  }
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IDiscussionBoardMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardMember";
import type { IDiscussionBoardModerator } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardModerator";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IPageIDiscussionBoardMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIDiscussionBoardMember";

/**
 * Test member search pagination with boundary conditions and edge cases.
 *
 * This test validates that the member search pagination API handles edge cases
 * correctly:
 *
 * 1. Moderator authenticates to gain search access
 * 2. Creates exactly 25 members for controlled testing
 * 3. Tests various boundary scenarios:
 *
 *    - Requesting pages beyond total available pages
 *    - Requesting limits exceeding total record count
 *    - Testing maximum limit (100) and minimum limit (1)
 *    - Verifying last page with partial results
 * 4. Validates pagination metadata accuracy (current, limit, records, pages)
 * 5. Ensures empty results for out-of-range pages don't cause errors
 * 6. Verifies limit parameter is capped at maximum 100 and minimum 1
 */
export async function test_api_member_search_pagination_boundary_conditions(
  connection: api.IConnection,
) {
  // Step 1: Authenticate as moderator
  const moderatorPassword = "moderatorPassword123";
  const moderator = await api.functional.auth.moderator.join(connection, {
    body: {
      email: typia.random<string & tags.Format<"email">>(),
      password: moderatorPassword,
      username: typia.random<string & tags.MinLength<3> & tags.MaxLength<30>>(),
      display_name: RandomGenerator.name(),
      href: typia.random<string & tags.Format<"uri">>(),
      referrer: typia.random<string & tags.Format<"uri">>(),
    } satisfies IDiscussionBoardModerator.ICreate,
  });
  typia.assert(moderator);

  // Store moderator token for restoration
  const moderatorToken = moderator.token.access;

  // Step 2: Create exactly 25 members for controlled pagination testing
  const memberCount = 25;
  const members = await ArrayUtil.asyncRepeat(memberCount, async (index) => {
    const member = await api.functional.auth.member.join(connection, {
      body: {
        email:
          `test_member_${index}_${typia.random<string & tags.Format<"uuid">>()}@example.com` satisfies string &
            tags.Format<"email">,
        password: "testPassword123",
        username: `testuser${index}${typia.random<number & tags.Type<"uint32"> & tags.Maximum<999999>>()}`,
        display_name: RandomGenerator.name(),
        href: typia.random<string & tags.Format<"uri">>(),
        referrer: typia.random<string & tags.Format<"uri">>(),
      } satisfies IDiscussionBoardMember.ICreate,
    });
    typia.assert(member);
    return member;
  });

  // Restore moderator authentication by setting the token back
  connection.headers = connection.headers ?? {};
  connection.headers.Authorization = moderatorToken;

  // Step 3: Test boundary condition - Page beyond total pages
  const beyondPageResult =
    await api.functional.discussionBoard.moderator.members.index(connection, {
      body: {
        page: 100,
        limit: 10,
      } satisfies IDiscussionBoardMember.IRequest,
    });
  typia.assert(beyondPageResult);
  TestValidator.equals(
    "beyond page returns empty data",
    beyondPageResult.data,
    [],
  );
  TestValidator.predicate(
    "beyond page has correct total records",
    beyondPageResult.pagination.records >= memberCount,
  );
  TestValidator.equals(
    "beyond page current matches request",
    beyondPageResult.pagination.current,
    100,
  );
  TestValidator.equals(
    "beyond page limit matches request",
    beyondPageResult.pagination.limit,
    10,
  );

  // Step 4: Test boundary condition - Limit exceeding total records
  const exceedLimitResult =
    await api.functional.discussionBoard.moderator.members.index(connection, {
      body: {
        page: 1,
        limit: 1000,
      } satisfies IDiscussionBoardMember.IRequest,
    });
  typia.assert(exceedLimitResult);
  TestValidator.predicate(
    "exceed limit returns all available members",
    exceedLimitResult.data.length >= memberCount,
  );
  TestValidator.equals(
    "exceed limit current page is 1",
    exceedLimitResult.pagination.current,
    1,
  );
  TestValidator.predicate(
    "exceed limit is capped at 100",
    exceedLimitResult.pagination.limit === 100,
  );

  // Step 5: Test maximum limit boundary (100)
  const maxLimitResult =
    await api.functional.discussionBoard.moderator.members.index(connection, {
      body: {
        page: 1,
        limit: 100,
      } satisfies IDiscussionBoardMember.IRequest,
    });
  typia.assert(maxLimitResult);
  TestValidator.equals(
    "max limit is accepted",
    maxLimitResult.pagination.limit,
    100,
  );
  TestValidator.predicate(
    "max limit records count is correct",
    maxLimitResult.pagination.records >= memberCount,
  );
  TestValidator.equals(
    "max limit pages calculation",
    maxLimitResult.pagination.pages,
    Math.ceil(maxLimitResult.pagination.records / 100),
  );

  // Step 6: Test minimum limit boundary (1)
  const minLimitResult =
    await api.functional.discussionBoard.moderator.members.index(connection, {
      body: {
        page: 1,
        limit: 1,
      } satisfies IDiscussionBoardMember.IRequest,
    });
  typia.assert(minLimitResult);
  TestValidator.equals(
    "min limit is accepted",
    minLimitResult.pagination.limit,
    1,
  );
  TestValidator.equals(
    "min limit returns 1 item",
    minLimitResult.data.length,
    1,
  );
  TestValidator.predicate(
    "min limit total records is correct",
    minLimitResult.pagination.records >= memberCount,
  );
  TestValidator.equals(
    "min limit pages calculation",
    minLimitResult.pagination.pages,
    Math.ceil(minLimitResult.pagination.records / 1),
  );

  // Step 7: Test last page with partial results
  const limit = 10;
  const totalPages = Math.ceil(memberCount / limit);
  const lastPageResult =
    await api.functional.discussionBoard.moderator.members.index(connection, {
      body: {
        page: totalPages,
        limit: limit,
      } satisfies IDiscussionBoardMember.IRequest,
    });
  typia.assert(lastPageResult);
  TestValidator.equals(
    "last page current matches request",
    lastPageResult.pagination.current,
    totalPages,
  );
  TestValidator.equals(
    "last page limit matches request",
    lastPageResult.pagination.limit,
    limit,
  );
  TestValidator.predicate(
    "last page has correct number of items",
    lastPageResult.data.length <= limit,
  );

  // Step 8: Verify pagination metadata accuracy with standard pagination
  const standardResult =
    await api.functional.discussionBoard.moderator.members.index(connection, {
      body: {
        page: 2,
        limit: 10,
      } satisfies IDiscussionBoardMember.IRequest,
    });
  typia.assert(standardResult);
  TestValidator.equals(
    "standard pagination current page",
    standardResult.pagination.current,
    2,
  );
  TestValidator.equals(
    "standard pagination limit",
    standardResult.pagination.limit,
    10,
  );
  TestValidator.predicate(
    "standard pagination records count",
    standardResult.pagination.records >= memberCount,
  );
  TestValidator.equals(
    "standard pagination pages calculation",
    standardResult.pagination.pages,
    Math.ceil(standardResult.pagination.records / 10),
  );
  TestValidator.predicate(
    "standard pagination data length",
    standardResult.data.length <= 10,
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IDiscussionBoardEmailVerification } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardEmailVerification";
import type { IDiscussionBoardModerator } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardModerator";

/**
 * Test moderator email verification retrieval functionality.
 *
 * This test validates the complete workflow of creating a verification record
 * and then retrieving it with full details including token, expiration status,
 * and member information. The test ensures moderators can inspect verification
 * records for troubleshooting member registration issues.
 *
 * Workflow:
 *
 * 1. Register moderator account with authentication
 * 2. Create email verification record for a member
 * 3. Retrieve the verification record by ID as moderator
 * 4. Validate all required fields are present and match original data
 */
export async function test_api_email_verification_retrieval_by_moderator(
  connection: api.IConnection,
) {
  // Step 1: Register moderator account with authentication
  const moderatorData = {
    email: typia.random<string & tags.Format<"email">>(),
    password: typia.random<string & tags.MinLength<8>>(),
    username: typia.random<string & tags.MinLength<3>>(),
    display_name: RandomGenerator.name(),
    href: typia.random<string & tags.Format<"uri">>(),
    referrer: typia.random<string & tags.Format<"uri">>(),
  } satisfies IDiscussionBoardModerator.ICreate;

  const moderator: IDiscussionBoardModerator.IAuthorized =
    await api.functional.auth.moderator.join(connection, {
      body: moderatorData,
    });
  typia.assert(moderator);

  // Step 2: Create email verification record
  const verificationData = {
    discussion_board_member_id: typia.random<string & tags.Format<"uuid">>(),
    email: typia.random<string & tags.Format<"email">>(),
  } satisfies IDiscussionBoardEmailVerification.ICreate;

  const createdVerification: IDiscussionBoardEmailVerification =
    await api.functional.discussionBoard.emailVerifications.create(connection, {
      body: verificationData,
    });
  typia.assert(createdVerification);

  // Step 3: Retrieve the verification record by ID as moderator
  const retrievedVerification: IDiscussionBoardEmailVerification =
    await api.functional.discussionBoard.moderator.emailVerifications.at(
      connection,
      {
        verificationId: createdVerification.id,
      },
    );
  typia.assert(retrievedVerification);

  // Step 4: Validate retrieved record matches created data
  TestValidator.equals(
    "verification ID matches",
    retrievedVerification.id,
    createdVerification.id,
  );

  TestValidator.equals(
    "member ID matches",
    retrievedVerification.discussion_board_member_id,
    createdVerification.discussion_board_member_id,
  );

  TestValidator.equals(
    "email matches",
    retrievedVerification.email,
    createdVerification.email,
  );

  TestValidator.equals(
    "token matches",
    retrievedVerification.token,
    createdVerification.token,
  );

  TestValidator.equals(
    "expires_at matches",
    retrievedVerification.expires_at,
    createdVerification.expires_at,
  );

  TestValidator.equals(
    "verified_at matches",
    retrievedVerification.verified_at,
    createdVerification.verified_at,
  );

  TestValidator.equals(
    "created_at matches",
    retrievedVerification.created_at,
    createdVerification.created_at,
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IDiscussionBoardEmailVerification } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardEmailVerification";
import type { IDiscussionBoardModerator } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardModerator";

/**
 * Test retrieval of email verification records with pending status.
 *
 * This test validates that moderators can retrieve email verification records
 * that are still pending (not yet verified). It creates a verification record
 * without completing the verification process, then retrieves it to confirm
 * that the verified_at field is null, the expires_at timestamp is properly set
 * to 24 hours from creation, and the token is present.
 *
 * This functionality is essential for moderators to troubleshoot member account
 * activation issues and distinguish between pending and completed
