  // Step 3: Initiate password reset for the member account
  const passwordReset =
    await api.functional.discussionBoard.passwordResets.create(
      unauthConnection,
      {
        body: {
          actor_type: "member",
          email: memberEmail,
        } satisfies IDiscussionBoardPasswordReset.ICreate,
      },
