    loginLowerResult.id,
    registeredMember.id,
  );
  TestValidator.equals(
    "lowercase login username matches",
    loginLowerResult.username,
    registeredMember.username,
  );

  // Step 3: Login with all uppercase email
  const uppercaseEmail = originalEmail.toUpperCase();

