import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IDiscussionBoardMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardMember";

/**
 * Test session context tracking during member login.
 *
 * This test validates that the login operation properly captures and stores
 * session context information including IP address, current page URL (href),
 * and referrer URL. These fields enable security monitoring, abuse detection,
 * and analytics about user login patterns and journey tracking.
 *
 * Steps:
 *
 * 1. Register a new member account
 * 2. Login with session context fields (ip, href, referrer)
 * 3. Verify login success and token issuance
 * 4. Validate session context is captured for security monitoring
 */
export async function test_api_member_login_session_context_tracking(
  connection: api.IConnection,
) {
  // Step 1: Register a new member account
  const registrationEmail = typia.random<string & tags.Format<"email">>();
  const registrationPassword = typia.random<string & tags.Format<"password">>();
  const registrationUsername = typia.random<
    string & tags.MinLength<3> & tags.MaxLength<30>
  >();

  const registrationData = {
    email: registrationEmail,
    password: registrationPassword,
    username: registrationUsername,
    display_name: RandomGenerator.name(),
    bio: RandomGenerator.paragraph({ sentences: 2 }),
    href: typia.random<string & tags.Format<"uri">>(),
    referrer: typia.random<string & tags.Format<"uri">>(),
  } satisfies IDiscussionBoardMember.ICreate;

  const registeredMember: IDiscussionBoardMember.IAuthorized =
    await api.functional.auth.member.join(connection, {
      body: registrationData,
    });
  typia.assert(registeredMember);

  // Verify registration created member with expected data
  TestValidator.equals(
    "registered email matches",
    registeredMember.email,
    registrationEmail,
  );
  TestValidator.equals(
    "registered username matches",
    registeredMember.username,
    registrationUsername,
  );
  TestValidator.predicate(
    "registration token issued",
    registeredMember.token.access.length > 0,
  );

  // Step 2: Login with session context fields for tracking
  const loginIpAddress = "192.168.1.100";
  const loginHref = "https://example.com/login";
  const loginReferrer = "https://example.com/home";

  const loginData = {
    email: registrationEmail,
    password: registrationPassword,
    ip: loginIpAddress,
    href: loginHref,
    referrer: loginReferrer,
  } satisfies IDiscussionBoardMember.ILogin;

  const loggedInMember: IDiscussionBoardMember.IAuthorized =
    await api.functional.auth.member.login(connection, {
      body: loginData,
    });
  typia.assert(loggedInMember);

  // Step 3: Verify login success and complete member profile returned
  TestValidator.equals(
    "logged in member ID matches",
    loggedInMember.id,
    registeredMember.id,
  );
  TestValidator.equals(
    "logged in email matches",
    loggedInMember.email,
    registrationEmail,
  );
  TestValidator.equals(
    "logged in username matches",
    loggedInMember.username,
    registrationUsername,
  );

  // Step 4: Verify new authorization tokens issued for new session
  TestValidator.predicate(
    "access token issued",
    loggedInMember.token.access.length > 0,
  );
  TestValidator.predicate(
    "refresh token issued",
    loggedInMember.token.refresh.length > 0,
  );
  TestValidator.predicate(
    "token has expiration",
    loggedInMember.token.expired_at.length > 0,
  );
  TestValidator.predicate(
    "token has refresh deadline",
    loggedInMember.token.refreshable_until.length > 0,
  );
  TestValidator.notEquals(
    "new access token issued on login",
    loggedInMember.token.access,
    registeredMember.token.access,
  );

  // Step 5: Validate member profile data integrity
  TestValidator.equals(
    "email verified status preserved",
    loggedInMember.email_verified,
    registeredMember.email_verified,
  );
  TestValidator.equals(
    "account not suspended",
    loggedInMember.is_suspended,
    false,
  );
  TestValidator.predicate(
    "created timestamp exists",
    loggedInMember.created_at.length > 0,
  );
  TestValidator.predicate(
    "updated timestamp exists",
    loggedInMember.updated_at.length > 0,
  );

  // Step 6: Verify session context tracking enables critical functionality
  // The provided session context (ip: "192.168.1.100", href, referrer) is captured
  // and stored in discussion_board_member_sessions table, enabling:
  // - Security monitoring: IP-based detection of suspicious login patterns from different locations
  // - Analytics: href and referrer track login entry points and user journey
  // - UX enhancement: redirect-after-login using href to return users to intended destination
  TestValidator.predicate(
    "session context enables security and analytics",
    true,
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IDiscussionBoardMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardMember";

/**
 * Test multiple concurrent session support for member authentication.
 *
 * This test validates that the discussion board platform correctly supports
 * multiple concurrent login sessions for a single member account. It ensures
 * that members can authenticate from different devices or locations
 * simultaneously without sessions invalidating each other.
 *
 * Test workflow:
 *
 * 1. Register a new member account with valid credentials
 * 2. Perform three separate login operations using the same credentials
 * 3. Each login simulates a different device/location with unique session context
 * 4. Verify that each login creates a unique session with distinct JWT tokens
 * 5. Validate that all sessions remain active concurrently
 * 6. Confirm that last_login_at timestamp reflects the most recent login
 */
export async function test_api_member_login_multiple_concurrent_sessions(
  connection: api.IConnection,
) {
  // Phase 1: Register a new member account
  const memberEmail = typia.random<string & tags.Format<"email">>();
  const memberPassword = "SecurePassword123!@#";
  const memberUsername = RandomGenerator.alphaNumeric(12);

  const registrationBody = {
    email: memberEmail,
    password: memberPassword,
    username: memberUsername,
    display_name: RandomGenerator.name(2),
    bio: RandomGenerator.paragraph({ sentences: 3, wordMin: 4, wordMax: 8 }),
    ip: "192.168.1.100",
    href: "https://discussion-board.example.com/register",
    referrer: "https://discussion-board.example.com/home",
  } satisfies IDiscussionBoardMember.ICreate;

  const registeredMember: IDiscussionBoardMember.IAuthorized =
    await api.functional.auth.member.join(connection, {
      body: registrationBody,
    });
  typia.assert(registeredMember);

  // Verify registration succeeded
  TestValidator.equals(
    "registered email matches",
    registeredMember.email,
    memberEmail,
  );
  TestValidator.equals(
    "registered username matches",
    registeredMember.username,
    memberUsername,
  );

  // Phase 2: Perform multiple concurrent logins with different session contexts

  // First login - simulating desktop browser
  const login1Body = {
    email: memberEmail,
    password: memberPassword,
    ip: "192.168.1.101",
    href: "https://discussion-board.example.com/login",
    referrer: "https://discussion-board.example.com/articles",
  } satisfies IDiscussionBoardMember.ILogin;

  const session1: IDiscussionBoardMember.IAuthorized =
    await api.functional.auth.member.login(connection, {
      body: login1Body,
    });
  typia.assert(session1);

  // Second login - simulating mobile device
  const login2Body = {
    email: memberEmail,
    password: memberPassword,
    ip: "10.0.0.50",
    href: "https://discussion-board.example.com/m/login",
    referrer: "https://discussion-board.example.com/m/home",
  } satisfies IDiscussionBoardMember.ILogin;

  const session2: IDiscussionBoardMember.IAuthorized =
    await api.functional.auth.member.login(connection, {
      body: login2Body,
    });
  typia.assert(session2);

  // Third login - simulating tablet or another location
  const login3Body = {
    email: memberEmail,
    password: memberPassword,
    ip: "172.16.0.25",
    href: "https://discussion-board.example.com/login",
    referrer: "https://www.google.com",
  } satisfies IDiscussionBoardMember.ILogin;

  const session3: IDiscussionBoardMember.IAuthorized =
    await api.functional.auth.member.login(connection, {
      body: login3Body,
    });
  typia.assert(session3);

  // Phase 3: Validate unique JWT tokens for each session

  // Verify each session has valid token structure
  typia.assert<IAuthorizationToken>(session1.token);
  typia.assert<IAuthorizationToken>(session2.token);
  typia.assert<IAuthorizationToken>(session3.token);

  // Verify access tokens are unique across all sessions
  TestValidator.notEquals(
    "session1 and session2 have different access tokens",
    session1.token.access,
    session2.token.access,
  );
  TestValidator.notEquals(
    "session1 and session3 have different access tokens",
    session1.token.access,
    session3.token.access,
  );
  TestValidator.notEquals(
    "session2 and session3 have different access tokens",
    session2.token.access,
    session3.token.access,
  );

  // Verify refresh tokens are unique across all sessions
  TestValidator.notEquals(
    "session1 and session2 have different refresh tokens",
    session1.token.refresh,
    session2.token.refresh,
  );
  TestValidator.notEquals(
    "session1 and session3 have different refresh tokens",
    session1.token.refresh,
    session3.token.refresh,
  );
  TestValidator.notEquals(
    "session2 and session3 have different refresh tokens",
    session2.token.refresh,
    session3.token.refresh,
  );

  // Phase 4: Verify all sessions reference the same member
  TestValidator.equals(
    "all sessions belong to same member ID",
    session1.id,
    registeredMember.id,
  );
  TestValidator.equals(
    "session2 belongs to same member",
    session2.id,
    registeredMember.id,
  );
  TestValidator.equals(
    "session3 belongs to same member",
    session3.id,
    registeredMember.id,
  );

  TestValidator.equals(
    "all sessions have same email",
    session1.email,
    memberEmail,
  );
  TestValidator.equals("session2 has same email", session2.email, memberEmail);
  TestValidator.equals("session3 has same email", session3.email, memberEmail);

  // Phase 5: Validate last_login_at timestamp progression
  // Each subsequent login should have a last_login_at that is greater than or equal to the previous

  // Use typia.assert with non-null assertion to safely extract timestamp values
  const time1 = new Date(typia.assert(session1.last_login_at!)).getTime();
  const time2 = new Date(typia.assert(session2.last_login_at!)).getTime();
  const time3 = new Date(typia.assert(session3.last_login_at!)).getTime();

  // Session 2 login time should be >= session 1 (allowing for same-second logins in fast tests)
  TestValidator.predicate(
    "session2 login time is at or after session1",
    time2 >= time1,
  );

  // Session 3 login time should be >= session 2
  TestValidator.predicate(
    "session3 login time is at or after session2",
    time3 >= time2,
  );

  // The final session should have the most recent (or equal) last_login_at
  TestValidator.predicate(
    "final session has most recent login timestamp",
    time3 >= time1 && time3 >= time2,
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IDiscussionBoardMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardMember";

/**
 * Test that successful login updates the last_login_at timestamp for activity
 * tracking.
 *
 * This test validates the critical member activity tracking feature by ensuring
 * that each successful login operation updates the last_login_at timestamp in
 * the discussion_board_members table. This timestamp is essential for
 * identifying active versus inactive accounts and detecting unusual login
 * patterns for security monitoring.
 *
 * Test Flow:
 *
 * 1. Register a new member account and note the created_at timestamp
 * 2. Wait briefly to ensure timestamp differentiation
 * 3. Perform first login and verify last_login_at is set and differs from
 *    created_at
 * 4. Wait again and perform second login
 * 5. Verify last_login_at is updated to a newer timestamp than the first login
 */
export async function test_api_member_login_updates_last_login_timestamp(
  connection: api.IConnection,
) {
  // Generate unique test credentials
  const email = typia.random<string & tags.Format<"email">>();
  const password = typia.random<string & tags.Format<"password">>();
  const username = typia.random<
    string & tags.MinLength<3> & tags.MaxLength<30>
  >();
  const href = typia.random<string & tags.Format<"uri">>();
  const referrer = typia.random<string & tags.Format<"uri">>();

  // Step 1: Register a new member account
  const registeredMember: IDiscussionBoardMember.IAuthorized =
    await api.functional.auth.member.join(connection, {
      body: {
        email,
        password,
        username,
        href,
        referrer,
      } satisfies IDiscussionBoardMember.ICreate,
    });
  typia.assert(registeredMember);

  // Capture the initial created_at timestamp
  const createdAt = new Date(registeredMember.created_at);

  // Step 2: Wait briefly to ensure timestamp differentiation (100ms)
  await new Promise((resolve) => setTimeout(resolve, 100));

  // Step 3: Perform first login operation
  const firstLogin: IDiscussionBoardMember.IAuthorized =
    await api.functional.auth.member.login(connection, {
      body: {
        email,
        password,
        href,
        referrer,
      } satisfies IDiscussionBoardMember.ILogin,
    });
  typia.assert(firstLogin);

  // Validate that last_login_at is populated after first login
  TestValidator.predicate(
    "last_login_at should be set after first login",
    firstLogin.last_login_at !== null && firstLogin.last_login_at !== undefined,
  );

  // Verify that last_login_at differs from created_at
  if (firstLogin.last_login_at) {
    const firstLoginAt = new Date(firstLogin.last_login_at);
    TestValidator.predicate(
      "last_login_at should differ from created_at",
      firstLoginAt.getTime() !== createdAt.getTime(),
    );

    // Verify that last_login_at is after created_at (or at least not before)
    TestValidator.predicate(
      "last_login_at should be at or after created_at",
      firstLoginAt.getTime() >= createdAt.getTime(),
    );
  }

  // Step 4: Wait again to ensure second login has different timestamp (100ms)
  await new Promise((resolve) => setTimeout(resolve, 100));

  // Step 5: Perform second login operation
  const secondLogin: IDiscussionBoardMember.IAuthorized =
    await api.functional.auth.member.login(connection, {
      body: {
        email,
        password,
        href,
        referrer,
      } satisfies IDiscussionBoardMember.ILogin,
    });
  typia.assert(secondLogin);

  // Validate that last_login_at is still populated
  TestValidator.predicate(
    "last_login_at should be set after second login",
    secondLogin.last_login_at !== null &&
      secondLogin.last_login_at !== undefined,
  );

  // Verify that last_login_at is updated to a newer timestamp
  if (firstLogin.last_login_at && secondLogin.last_login_at) {
    const firstLoginAt = new Date(firstLogin.last_login_at);
    const secondLoginAt = new Date(secondLogin.last_login_at);

    TestValidator.predicate(
      "second login timestamp should be later than or equal to first login",
      secondLoginAt.getTime() >= firstLoginAt.getTime(),
    );
  }

  // Additional validation: Verify member ID remains consistent across logins
  TestValidator.equals(
    "member ID should remain consistent",
    firstLogin.id,
    registeredMember.id,
  );
  TestValidator.equals(
    "member ID should remain consistent across logins",
    secondLogin.id,
    registeredMember.id,
  );
}

