    category1.id,
  );

  TestValidator.equals(
    "second category should have sort_order 2",
    ascendingCategories[1].id,
    category2.id,
  );

  TestValidator.equals(
    "third category should have sort_order 3",
    ascendingCategories[2].id,
    category3.id,
