import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IDiscussionBoardAccountAction } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardAccountAction";
import type { IDiscussionBoardMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardMember";
import type { IDiscussionBoardModerator } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardModerator";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IPageIDiscussionBoardAccountAction } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIDiscussionBoardAccountAction";

/**
 * Test filtering account actions by the moderator who applied them to review
 * specific moderator's enforcement activity.
 *
 * This test validates that the moderator_id filter enables auditing of
 * individual moderator decision patterns and enforcement consistency. Multiple
 * moderators authenticate, each creates enforcement actions, then search is
 * performed with moderator_id filter to retrieve only actions performed by a
 * specific moderator.
 *
 * Workflow:
 *
 * 1. Create first moderator account
 * 2. Create member target for first moderator's action
 * 3. First moderator creates enforcement action
 * 4. Create second moderator account
 * 5. Create member target for second moderator's action
 * 6. Second moderator creates enforcement action
 * 7. Search account actions filtering by first moderator's ID
 * 8. Validate only first moderator's actions are returned
 */
export async function test_api_account_action_filter_by_moderator(
  connection: api.IConnection,
) {
  // Step 1: Create first moderator
  const moderator1 = await api.functional.auth.moderator.join(connection, {
    body: {
      email: typia.random<string & tags.Format<"email">>(),
      password: typia.random<string>(),
      username: typia.random<string>(),
      href: typia.random<string & tags.Format<"uri">>(),
      referrer: typia.random<string & tags.Format<"uri">>(),
    } satisfies IDiscussionBoardModerator.ICreate,
  });
  typia.assert(moderator1);

  // Step 2: Create member for first moderator's action
  const member1 = await api.functional.auth.member.join(connection, {
    body: {
      email: typia.random<string & tags.Format<"email">>(),
      password: typia.random<string & tags.Format<"password">>(),
      username: typia.random<string & tags.MinLength<3> & tags.MaxLength<30>>(),
      href: typia.random<string & tags.Format<"uri">>(),
      referrer: typia.random<string & tags.Format<"uri">>(),
    } satisfies IDiscussionBoardMember.ICreate,
  });
  typia.assert(member1);

  // Step 3: First moderator creates enforcement action
  const action1 =
    await api.functional.discussionBoard.moderator.accountActions.create(
      connection,
      {
        body: {
          discussion_board_member_id: member1.id,
          action_type: "suspension",
          reason: RandomGenerator.paragraph({
            sentences: 5,
            wordMin: 4,
            wordMax: 8,
          }),
          duration_days: 7,
        } satisfies IDiscussionBoardAccountAction.ICreate,
      },
    );
  typia.assert(action1);

  // Step 4: Create second moderator
  const moderator2 = await api.functional.auth.moderator.join(connection, {
    body: {
      email: typia.random<string & tags.Format<"email">>(),
      password: typia.random<string>(),
      username: typia.random<string>(),
      href: typia.random<string & tags.Format<"uri">>(),
      referrer: typia.random<string & tags.Format<"uri">>(),
    } satisfies IDiscussionBoardModerator.ICreate,
  });
  typia.assert(moderator2);

  // Step 5: Create member for second moderator's action
  const member2 = await api.functional.auth.member.join(connection, {
    body: {
      email: typia.random<string & tags.Format<"email">>(),
      password: typia.random<string & tags.Format<"password">>(),
      username: typia.random<string & tags.MinLength<3> & tags.MaxLength<30>>(),
      href: typia.random<string & tags.Format<"uri">>(),
      referrer: typia.random<string & tags.Format<"uri">>(),
    } satisfies IDiscussionBoardMember.ICreate,
  });
  typia.assert(member2);

  // Step 6: Second moderator creates enforcement action
  const action2 =
    await api.functional.discussionBoard.moderator.accountActions.create(
      connection,
      {
        body: {
          discussion_board_member_id: member2.id,
          action_type: "ban",
          reason: RandomGenerator.paragraph({
            sentences: 5,
            wordMin: 4,
            wordMax: 8,
          }),
        } satisfies IDiscussionBoardAccountAction.ICreate,
      },
    );
  typia.assert(action2);

  // Step 7: Search account actions filtering by first moderator's ID
  const filteredResults =
    await api.functional.discussionBoard.moderator.accountActions.index(
      connection,
      {
        body: {
          moderator_id: moderator1.id,
          page: 1,
          limit: 20,
        } satisfies IDiscussionBoardAccountAction.IRequest,
      },
    );
  typia.assert(filteredResults);

  // Step 8: Validate results contain only first moderator's actions
  TestValidator.predicate(
    "search results should not be empty",
    filteredResults.data.length > 0,
  );

  TestValidator.predicate(
    "first moderator's action should be in filtered results",
    filteredResults.data.some((action) => action.id === action1.id),
  );

  TestValidator.predicate(
    "second moderator's action should not be in filtered results",
    !filteredResults.data.some((action) => action.id === action2.id),
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IDiscussionBoardAccountAction } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardAccountAction";
import type { IDiscussionBoardMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardMember";
import type { IDiscussionBoardModerator } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardModerator";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IPageIDiscussionBoardAccountAction } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIDiscussionBoardAccountAction";

/**
 * Test filtering account actions by creation date range using created_after and
 * created_before parameters.
 *
 * This test validates the temporal filtering capabilities of the account action
 * search API. Moderators authenticate, create enforcement actions at different
 * times, then use date range filters to retrieve only actions created within
 * specific time periods. Validates that created_after returns actions on or
 * after the specified timestamp, created_before returns actions on or before
 * the timestamp, and combining both parameters correctly implements date range
 * filtering for moderation activity reports.
 *
 * Test Flow:
 *
 * 1. Authenticate as moderator
 * 2. Create multiple members as enforcement targets
 * 3. Create first account action and capture timestamp
 * 4. Wait briefly to ensure temporal separation
 * 5. Create second account action with later timestamp
 * 6. Wait again for temporal separation
 * 7. Create third account action with even later timestamp
 * 8. Test created_after filter (retrieve actions after first timestamp)
 * 9. Test created_before filter (retrieve actions before last timestamp)
 * 10. Test combined date range filter (between two timestamps)
 * 11. Validate all results match expected temporal criteria
 */
export async function test_api_account_action_filter_by_date_range(
  connection: api.IConnection,
) {
  // Step 1: Authenticate as moderator
  const moderator = await api.functional.auth.moderator.join(connection, {
    body: {
      email: typia.random<string & tags.Format<"email">>(),
      password: "SecurePassword123!",
      username: RandomGenerator.alphaNumeric(8),
      href: "https://test.example.com/moderator/join",
      referrer: "https://test.example.com/home",
    } satisfies IDiscussionBoardModerator.ICreate,
  });
  typia.assert(moderator);

  // Step 2: Create multiple members as enforcement targets
  const member1 = await api.functional.auth.member.join(connection, {
    body: {
      email: typia.random<string & tags.Format<"email">>(),
      password: "MemberPass123!",
      username: RandomGenerator.alphaNumeric(8),
      href: "https://test.example.com/member/join",
      referrer: "https://test.example.com/home",
    } satisfies IDiscussionBoardMember.ICreate,
  });
  typia.assert(member1);

  const member2 = await api.functional.auth.member.join(connection, {
    body: {
      email: typia.random<string & tags.Format<"email">>(),
      password: "MemberPass123!",
      username: RandomGenerator.alphaNumeric(8),
      href: "https://test.example.com/member/join",
      referrer: "https://test.example.com/home",
    } satisfies IDiscussionBoardMember.ICreate,
  });
  typia.assert(member2);

  const member3 = await api.functional.auth.member.join(connection, {
    body: {
      email: typia.random<string & tags.Format<"email">>(),
      password: "MemberPass123!",
      username: RandomGenerator.alphaNumeric(8),
      href: "https://test.example.com/member/join",
      referrer: "https://test.example.com/home",
    } satisfies IDiscussionBoardMember.ICreate,
  });
  typia.assert(member3);

  // Step 3: Create first account action and capture timestamp
  await new Promise((resolve) => setTimeout(resolve, 200)); // Delay for temporal separation

  const action1 =
    await api.functional.discussionBoard.moderator.accountActions.create(
      connection,
      {
        body: {
          discussion_board_member_id: member1.id,
          action_type: "suspension",
          reason: "First test suspension for date filtering",
          duration_days: 7,
        } satisfies IDiscussionBoardAccountAction.ICreate,
      },
    );
  typia.assert(action1);
  const timestamp1 = action1.created_at;

  // Step 4: Wait for temporal separation
  await new Promise((resolve) => setTimeout(resolve, 200));

  // Step 5: Create second account action with later timestamp
  const action2 =
    await api.functional.discussionBoard.moderator.accountActions.create(
      connection,
      {
        body: {
          discussion_board_member_id: member2.id,
          action_type: "ban",
          reason: "Second test ban for date filtering",
        } satisfies IDiscussionBoardAccountAction.ICreate,
      },
    );
  typia.assert(action2);
  const timestamp2 = action2.created_at;

  // Step 6: Wait again for temporal separation
  await new Promise((resolve) => setTimeout(resolve, 200));

  // Step 7: Create third account action with even later timestamp
  const action3 =
    await api.functional.discussionBoard.moderator.accountActions.create(
      connection,
      {
        body: {
          discussion_board_member_id: member3.id,
          action_type: "suspension",
          reason: "Third test suspension for date filtering",
          duration_days: 14,
        } satisfies IDiscussionBoardAccountAction.ICreate,
      },
    );
  typia.assert(action3);
  const timestamp3 = action3.created_at;

  // Step 8: Test created_after filter - should return actions on or after timestamp1
  const afterFilter =
    await api.functional.discussionBoard.moderator.accountActions.index(
      connection,
      {
        body: {
          created_after: timestamp1,
        } satisfies IDiscussionBoardAccountAction.IRequest,
      },
    );
  typia.assert(afterFilter);

  TestValidator.predicate(
    "created_after filter returns at least the 3 created actions",
    afterFilter.data.length >= 3,
  );

  // Validate all returned actions have created_at >= timestamp1
  for (const action of afterFilter.data) {
    TestValidator.predicate(
      "action created_at is on or after timestamp1",
      new Date(action.created_at).getTime() >= new Date(timestamp1).getTime(),
    );
  }

  // Step 9: Test created_before filter - should return actions on or before timestamp3
  const beforeFilter =
    await api.functional.discussionBoard.moderator.accountActions.index(
      connection,
      {
        body: {
          created_before: timestamp3,
        } satisfies IDiscussionBoardAccountAction.IRequest,
      },
    );
  typia.assert(beforeFilter);

  TestValidator.predicate(
    "created_before filter returns at least the 3 created actions",
    beforeFilter.data.length >= 3,
  );

  // Validate all returned actions have created_at <= timestamp3
  for (const action of beforeFilter.data) {
    TestValidator.predicate(
      "action created_at is on or before timestamp3",
      new Date(action.created_at).getTime() <= new Date(timestamp3).getTime(),
    );
  }

  // Step 10: Test combined date range filter - should return actions between timestamp1 and timestamp3
  const rangeFilter =
    await api.functional.discussionBoard.moderator.accountActions.index(
      connection,
      {
        body: {
          created_after: timestamp1,
          created_before: timestamp3,
        } satisfies IDiscussionBoardAccountAction.IRequest,
      },
    );
  typia.assert(rangeFilter);

  TestValidator.predicate(
    "date range filter returns at least the 3 created actions",
    rangeFilter.data.length >= 3,
  );

  // Validate all returned actions are within the date range
  for (const action of rangeFilter.data) {
    const actionTime = new Date(action.created_at).getTime();
    const afterTime = new Date(timestamp1).getTime();
    const beforeTime = new Date(timestamp3).getTime();

    TestValidator.predicate(
      "action created_at is within date range",
      actionTime >= afterTime && actionTime <= beforeTime,
    );
  }

  // Step 11: Verify specific actions are present in range results
  const actionIds = rangeFilter.data.map((a) => a.id);
  TestValidator.predicate(
    "range filter includes action1",
    actionIds.includes(action1.id),
  );
  TestValidator.predicate(
    "range filter includes action2",
    actionIds.includes(action2.id),
  );
  TestValidator.predicate(
    "range filter includes action3",
    actionIds.includes(action3.id),
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IDiscussionBoardAccountAction } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardAccountAction";
import type { IDiscussionBoardMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardMember";
import type { IDiscussionBoardModerator } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardModerator";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IPageIDiscussionBoardAccountAction } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIDiscussionBoardAccountAction";

/**
 * Test pagination controls for account action search endpoint.
 *
 * Validates that the pagination system correctly handles page number and limit
 * parameters when searching account actions. This test creates multiple account
 * actions and verifies that:
 *
 * 1. The limit parameter controls the number of results per page
 * 2. The page parameter navigates between result pages correctly
 * 3. Pagination metadata includes accurate current page, total pages, and total
 *    records
 * 4. Results are properly segmented across pages without duplication or omission
 *
 * The test authenticates as a moderator, creates test data (members and account
 * actions), then performs various pagination requests to validate the
 * pagination behavior.
 */
export async function test_api_account_action_pagination(
  connection: api.IConnection,
) {
  // Step 1: Authenticate as moderator
  const moderator: IDiscussionBoardModerator.IAuthorized =
    await api.functional.auth.moderator.join(connection, {
      body: {
        email: typia.random<string & tags.Format<"email">>(),
        password: RandomGenerator.alphaNumeric(12),
        username: RandomGenerator.alphaNumeric(8),
        display_name: RandomGenerator.name(),
        href: typia.random<string & tags.Format<"uri">>(),
        referrer: typia.random<string & tags.Format<"uri">>(),
      } satisfies IDiscussionBoardModerator.ICreate,
    });
  typia.assert(moderator);

  // Step 2: Create multiple members for account actions (3 members)
  const members: IDiscussionBoardMember.IAuthorized[] =
    await ArrayUtil.asyncRepeat(3, async () => {
      const member = await api.functional.auth.member.join(connection, {
        body: {
          email: typia.random<string & tags.Format<"email">>(),
          password: RandomGenerator.alphaNumeric(12),
          username: RandomGenerator.alphaNumeric(8),
          display_name: RandomGenerator.name(),
          href: typia.random<string & tags.Format<"uri">>(),
          referrer: typia.random<string & tags.Format<"uri">>(),
        } satisfies IDiscussionBoardMember.ICreate,
      });
      typia.assert(member);
      return member;
    });

  // Step 3: Create account actions for each member (moderator already authenticated)
  const createdActions: IDiscussionBoardAccountAction[] =
    await ArrayUtil.asyncRepeat(3, async (index) => {
      const action =
        await api.functional.discussionBoard.moderator.accountActions.create(
          connection,
          {
            body: {
              discussion_board_member_id: members[index].id,
              action_type: "suspension",
              reason: `Test suspension ${index + 1} - ${RandomGenerator.paragraph({ sentences: 2 })}`,
              duration_days: RandomGenerator.pick([1, 7, 14, 30] as const),
            } satisfies IDiscussionBoardAccountAction.ICreate,
          },
        );
      typia.assert(action);
      return action;
    });

  // Step 4: Test pagination with limit = 2, page = 1
  const page1Result: IPageIDiscussionBoardAccountAction.ISummary =
    await api.functional.discussionBoard.moderator.accountActions.index(
      connection,
      {
        body: {
          page: 1,
          limit: 2,
        } satisfies IDiscussionBoardAccountAction.IRequest,
      },
    );
  typia.assert(page1Result);

  // Validate page 1 pagination metadata
  TestValidator.equals(
    "page 1 current page",
    page1Result.pagination.current,
    1,
  );
  TestValidator.equals("page 1 limit", page1Result.pagination.limit, 2);
  TestValidator.equals(
    "page 1 total records",
    page1Result.pagination.records,
    3,
  );
  TestValidator.equals("page 1 total pages", page1Result.pagination.pages, 2);
  TestValidator.equals("page 1 data length", page1Result.data.length, 2);

  // Step 5: Test pagination with limit = 2, page = 2
  const page2Result: IPageIDiscussionBoardAccountAction.ISummary =
    await api.functional.discussionBoard.moderator.accountActions.index(
      connection,
      {
        body: {
          page: 2,
          limit: 2,
        } satisfies IDiscussionBoardAccountAction.IRequest,
      },
    );
  typia.assert(page2Result);

  // Validate page 2 pagination metadata
  TestValidator.equals(
    "page 2 current page",
    page2Result.pagination.current,
    2,
  );
  TestValidator.equals("page 2 limit", page2Result.pagination.limit, 2);
  TestValidator.equals(
    "page 2 total records",
    page2Result.pagination.records,
    3,
  );
  TestValidator.equals("page 2 total pages", page2Result.pagination.pages, 2);
  TestValidator.equals("page 2 data length", page2Result.data.length, 1);

  // Step 6: Verify no duplication between pages
  const page1Ids = page1Result.data.map((action) => action.id);
  const page2Ids = page2Result.data.map((action) => action.id);

  const allIds = [...page1Ids, ...page2Ids];
  const uniqueIds = [...new Set(allIds)];

  TestValidator.equals(
    "no duplicate IDs across pages",
    allIds.length,
    uniqueIds.length,
  );
  TestValidator.equals("total retrieved records", allIds.length, 3);

  // Step 7: Test different limit value (limit = 1)
  const smallLimitResult: IPageIDiscussionBoardAccountAction.ISummary =
    await api.functional.discussionBoard.moderator.accountActions.index(
      connection,
      {
        body: {
          page: 1,
          limit: 1,
        } satisfies IDiscussionBoardAccountAction.IRequest,
      },
    );
  typia.assert(smallLimitResult);

  TestValidator.equals(
    "small limit page 1 data length",
    smallLimitResult.data.length,
    1,
  );
  TestValidator.equals(
    "small limit total pages",
    smallLimitResult.pagination.pages,
    3,
  );

  // Step 8: Test all records on single page (limit = 100, maximum allowed)
  const allRecordsResult: IPageIDiscussionBoardAccountAction.ISummary =
    await api.functional.discussionBoard.moderator.accountActions.index(
      connection,
      {
        body: {
          page: 1,
          limit: 100,
        } satisfies IDiscussionBoardAccountAction.IRequest,
      },
    );
  typia.assert(allRecordsResult);

  TestValidator.equals(
    "all records data length",
    allRecordsResult.data.length,
    3,
  );
  TestValidator.equals(
    "all records total pages",
    allRecordsResult.pagination.pages,
    1,
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IDiscussionBoardAccountAction } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardAccountAction";
import type { IDiscussionBoardMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardMember";
import type { IDiscussionBoardModerator } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardModerator";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IPageIDiscussionBoardAccountAction } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIDiscussionBoardAccountAction";

/**
 * Test complex search scenarios combining multiple filter parameters
 * simultaneously.
 *
 * This test validates that the account action search API correctly applies
 * multiple filters with AND logic, returning only records that match ALL
 * specified criteria.
 *
 * The test creates a diverse set of account actions with different attributes
 * and performs searches combining action_type, status, member_id, and date
 * range filters to ensure precise query results.
 *
 * Steps:
 *
 * 1. Create and authenticate as moderator
 * 2. Create two members for member_id filtering
 * 3. Create diverse account actions with different attribute combinations
 * 4. Perform combined filter search and validate AND logic
 * 5. Test multiple filter combinations to ensure precision
 */
export async function test_api_account_action_combined_filters(
  connection: api.IConnection,
) {
  // Step 1: Create and authenticate as moderator
  const moderator: IDiscussionBoardModerator.IAuthorized =
    await api.functional.auth.moderator.join(connection, {
      body: {
        email: typia.random<string & tags.Format<"email">>(),
        password: RandomGenerator.alphaNumeric(12),
        username: RandomGenerator.alphaNumeric(8),
        display_name: RandomGenerator.name(),
        href: typia.random<string & tags.Format<"uri">>(),
        referrer: typia.random<string & tags.Format<"uri">>(),
      } satisfies IDiscussionBoardModerator.ICreate,
    });
  typia.assert(moderator);

  // Step 2: Create two members for member_id filtering
  const member1: IDiscussionBoardMember.IAuthorized =
    await api.functional.auth.member.join(connection, {
      body: {
        email: typia.random<string & tags.Format<"email">>(),
        password: RandomGenerator.alphaNumeric(12),
        username: RandomGenerator.alphaNumeric(8),
        display_name: RandomGenerator.name(),
        href: typia.random<string & tags.Format<"uri">>(),
        referrer: typia.random<string & tags.Format<"uri">>(),
      } satisfies IDiscussionBoardMember.ICreate,
    });
  typia.assert(member1);

  const member2: IDiscussionBoardMember.IAuthorized =
    await api.functional.auth.member.join(connection, {
      body: {
        email: typia.random<string & tags.Format<"email">>(),
        password: RandomGenerator.alphaNumeric(12),
        username: RandomGenerator.alphaNumeric(8),
        display_name: RandomGenerator.name(),
        href: typia.random<string & tags.Format<"uri">>(),
        referrer: typia.random<string & tags.Format<"uri">>(),
      } satisfies IDiscussionBoardMember.ICreate,
    });
  typia.assert(member2);

  // Step 3: Create target action (suspension, active, member1) - this is our main target
  const targetAction: IDiscussionBoardAccountAction =
    await api.functional.discussionBoard.moderator.accountActions.create(
      connection,
      {
        body: {
          discussion_board_member_id: member1.id,
          action_type: "suspension" as const,
          reason: RandomGenerator.paragraph({ sentences: 3 }),
          duration_days: 7 as const,
        } satisfies IDiscussionBoardAccountAction.ICreate,
      },
    );
  typia.assert(targetAction);

  // Step 4: Create control actions with different attributes
  // Action for member2 (different member, same type)
  const action2: IDiscussionBoardAccountAction =
    await api.functional.discussionBoard.moderator.accountActions.create(
      connection,
      {
        body: {
          discussion_board_member_id: member2.id,
          action_type: "suspension" as const,
          reason: RandomGenerator.paragraph({ sentences: 3 }),
          duration_days: 14 as const,
        } satisfies IDiscussionBoardAccountAction.ICreate,
      },
    );
  typia.assert(action2);

  // Action for member1 but different type (ban instead of suspension)
  const action3: IDiscussionBoardAccountAction =
    await api.functional.discussionBoard.moderator.accountActions.create(
      connection,
      {
        body: {
          discussion_board_member_id: member1.id,
          action_type: "ban" as const,
          reason: RandomGenerator.paragraph({ sentences: 3 }),
        } satisfies IDiscussionBoardAccountAction.ICreate,
      },
    );
  typia.assert(action3);

  // Action for member2 with ban type
  const action4: IDiscussionBoardAccountAction =
    await api.functional.discussionBoard.moderator.accountActions.create(
      connection,
      {
        body: {
          discussion_board_member_id: member2.id,
          action_type: "ban" as const,
          reason: RandomGenerator.paragraph({ sentences: 3 }),
        } satisfies IDiscussionBoardAccountAction.ICreate,
      },
    );
  typia.assert(action4);

