import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IDiscussionBoardArticle } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardArticle";
import type { IDiscussionBoardArticleCategory } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardArticleCategory";
import type { IDiscussionBoardContentReport } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardContentReport";
import type { IDiscussionBoardMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardMember";
import type { IDiscussionBoardModerator } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardModerator";

/**
 * Test content report retrieval with resolution status tracking.
 *
 * This test validates that the GET endpoint correctly returns content reports
 * with their current resolution status (pending, reviewed_no_action,
 * reviewed_edited, reviewed_removed) along with associated metadata like
 * resolution_notes and resolved_at.
 *
 * The test creates a complete reporting workflow:
 *
 * 1. Set up moderator and member accounts
 * 2. Create article category and article infrastructure
 * 3. Submit a content report as a member
 * 4. Retrieve the report and verify status tracking fields
 *
 * This ensures transparency in the moderation lifecycle for both moderators and
 * reporting members.
 */
export async function test_api_content_report_with_resolution_status_tracking(
  connection: api.IConnection,
) {
  // Step 1: Create moderator account for category creation
  const moderatorEmail = typia.random<string & tags.Format<"email">>();
  const moderator = await api.functional.auth.moderator.join(connection, {
    body: {
      email: moderatorEmail,
      password: "moderator123",
      username: RandomGenerator.alphaNumeric(8),
      display_name: RandomGenerator.name(),
      ip: "127.0.0.1",
      href: "https://example.com/moderator/join",
      referrer: "https://example.com/home",
    } satisfies IDiscussionBoardModerator.ICreate,
  });
  typia.assert(moderator);

  // Step 2: Create article category (requires moderator authentication)
  const category =
    await api.functional.discussionBoard.moderator.categories.create(
      connection,
      {
        body: {
          name: "Economic Discussion",
          slug: "economic-discussion",
          description: "Discussions about economic policies and markets",
          sort_order: 1,
        } satisfies IDiscussionBoardArticleCategory.ICreate,
      },
    );
  typia.assert(category);

  // Step 3: Create member account to submit reports
  const memberEmail = typia.random<string & tags.Format<"email">>();
  const member = await api.functional.auth.member.join(connection, {
    body: {
      email: memberEmail,
      password: "member123",
      username: RandomGenerator.alphaNumeric(8),
      display_name: RandomGenerator.name(),
      bio: RandomGenerator.paragraph({ sentences: 2 }),
      ip: "127.0.0.1",
      href: "https://example.com/member/join",
      referrer: "https://example.com/home",
    } satisfies IDiscussionBoardMember.ICreate,
  });
  typia.assert(member);

  // Step 4: Create an article to be reported
  const article = await api.functional.discussionBoard.member.articles.create(
    connection,
    {
      body: {
        title: RandomGenerator.paragraph({
          sentences: 1,
          wordMin: 5,
          wordMax: 10,
        }),
        body: RandomGenerator.content({
          paragraphs: 3,
          sentenceMin: 10,
          sentenceMax: 20,
        }),
        discussion_board_article_category_id: category.id,
        status: "published",
      } satisfies IDiscussionBoardArticle.ICreate,
    },
  );
  typia.assert(article);

  // Step 5: Submit content report with pending status
  const reportCategory = RandomGenerator.pick([
    "Spam",
    "Offensive Content",
    "Misinformation",
    "Off-Topic",
    "Other",
  ] as const);
  const reportDetails = RandomGenerator.paragraph({
    sentences: 5,
    wordMin: 5,
    wordMax: 10,
  });

  const submittedReport =
    await api.functional.discussionBoard.member.contentReports.create(
      connection,
      {
        body: {
          discussion_board_article_id: article.id,
          report_category: reportCategory,
          report_details: reportDetails,
        } satisfies IDiscussionBoardContentReport.ICreate,
      },
    );
  typia.assert(submittedReport);

  // Step 6: Switch to moderator to retrieve the report
  await api.functional.auth.moderator.login(connection, {
    body: {
      email: moderatorEmail,
      password: "moderator123",
      ip: "127.0.0.1",
      href: "https://example.com/moderator/dashboard",
      referrer: "https://example.com/moderator/login",
    } satisfies IDiscussionBoardModerator.ILogin,
  });

  // Step 7: Retrieve the report and verify status tracking
  const retrievedReport =
    await api.functional.discussionBoard.moderator.contentReports.at(
      connection,
      {
        reportId: submittedReport.id,
      },
    );
  typia.assert(retrievedReport);

  // Step 8: Verify pending status and null resolution fields
  TestValidator.equals(
    "report ID matches",
    retrievedReport.id,
    submittedReport.id,
  );
  TestValidator.equals(
    "report status is pending",
    retrievedReport.status,
    "pending",
  );
  TestValidator.equals(
    "article ID matches",
    retrievedReport.discussion_board_article_id,
    article.id,
  );
  TestValidator.equals(
    "member ID matches",
    retrievedReport.discussion_board_member_id,
    member.id,
  );
  TestValidator.equals(
    "report category matches",
    retrievedReport.report_category,
    reportCategory,
  );

  // Verify resolution fields are null or undefined for pending status
  TestValidator.predicate(
    "resolved_by_moderator_id is null or undefined for pending",
    retrievedReport.resolved_by_moderator_id === null ||
      retrievedReport.resolved_by_moderator_id === undefined,
  );
  TestValidator.predicate(
    "resolution_notes is null or undefined for pending",
    retrievedReport.resolution_notes === null ||
      retrievedReport.resolution_notes === undefined,
  );
  TestValidator.predicate(
    "resolved_at is null or undefined for pending",
    retrievedReport.resolved_at === null ||
      retrievedReport.resolved_at === undefined,
  );

  // Verify created_at timestamp exists
  TestValidator.predicate(
    "created_at timestamp exists",
    retrievedReport.created_at !== null &&
      retrievedReport.created_at !== undefined,
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IDiscussionBoardAccountAction } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardAccountAction";
import type { IDiscussionBoardModerator } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardModerator";

/**
 * Test the complete workflow of a moderator creating a temporary suspension
 * against a member account.
 *
 * This test validates that moderators can successfully apply disciplinary
 * actions for policy violations with proper documentation. The workflow creates
 * a moderator account, creates a second account to act as the target member,
 * then applies a 7-day suspension with documented reason.
 *
 * Verification includes:
 *
 * 1. Suspension is created with status 'active'
 * 2. Duration is correctly set to 7 days
 * 3. The expires_at timestamp is calculated as created_at + 7 days
 * 4. All required fields (moderator_id, member_id, action_type, reason) are
 *    populated
 * 5. Complete account action record with UUID and timestamps is returned
 */
export async function test_api_account_action_suspension_creation(
  connection: api.IConnection,
) {
  // Step 1: Create first moderator account (who will apply the suspension)
  const moderatorEmail = typia.random<string & tags.Format<"email">>();
  const moderator = await api.functional.auth.moderator.join(connection, {
    body: {
      email: moderatorEmail,
      password: "SecurePassword123!",
      username: RandomGenerator.alphaNumeric(8),
      display_name: RandomGenerator.name(),
      href: "https://example.com/moderator/join" satisfies string &
        tags.Format<"uri">,
      referrer: "https://example.com/login" satisfies string &
        tags.Format<"uri">,
    } satisfies IDiscussionBoardModerator.ICreate,
  });
  typia.assert(moderator);

  // Step 2: Create second moderator account (to act as the "member" being suspended)
  const targetEmail = typia.random<string & tags.Format<"email">>();
  const targetModerator = await api.functional.auth.moderator.join(connection, {
    body: {
      email: targetEmail,
      password: "TargetPassword123!",
      username: RandomGenerator.alphaNumeric(8),
      display_name: RandomGenerator.name(),
      href: "https://example.com/moderator/join" satisfies string &
        tags.Format<"uri">,
      referrer: "https://example.com/home" satisfies string &
        tags.Format<"uri">,
    } satisfies IDiscussionBoardModerator.ICreate,
  });
  typia.assert(targetModerator);

  // Step 3: Create a 7-day suspension against the target member
  const suspensionReason =
    "Repeated violations of community guidelines: posting spam content in multiple discussion threads after two prior warnings.";
  const accountAction =
    await api.functional.discussionBoard.moderator.accountActions.create(
      connection,
      {
        body: {
          discussion_board_member_id: targetModerator.id,
          action_type: "suspension" satisfies "suspension" | "ban",
          reason: suspensionReason,
          duration_days: 7,
        } satisfies IDiscussionBoardAccountAction.ICreate,
      },
    );
  typia.assert(accountAction);

  // Step 4: Validate the suspension record
  TestValidator.equals(
    "action type is suspension",
    accountAction.action_type,
    "suspension",
  );
  TestValidator.equals("status is active", accountAction.status, "active");
  TestValidator.equals("duration is 7 days", accountAction.duration_days, 7);
  TestValidator.equals(
    "reason matches",
    accountAction.reason,
    suspensionReason,
  );
  TestValidator.equals(
    "member ID matches",
    accountAction.discussion_board_member_id,
    targetModerator.id,
  );
  TestValidator.equals(
    "moderator ID matches",
    accountAction.discussion_board_moderator_id,
    moderator.id,
  );

  // Step 5: Verify expires_at is correctly calculated as created_at + 7 days
  typia.assertGuard(accountAction.expires_at!);
  const createdDate = new Date(accountAction.created_at);
  const expiresDate = new Date(accountAction.expires_at);
  const expectedExpiresDate = new Date(createdDate);
  expectedExpiresDate.setDate(expectedExpiresDate.getDate() + 7);

  // Allow 1 second tolerance for timestamp comparison
  const timeDifference = Math.abs(
    expiresDate.getTime() - expectedExpiresDate.getTime(),
  );
  TestValidator.predicate(
    "expires_at is created_at + 7 days",
    timeDifference < 1000,
  );
}

