        tags.Format<"uri">,
      referrer: "https://example.com" satisfies string & tags.Format<"uri">,
    } satisfies IDiscussionBoardModerator.ILogin,
  });

  // Step 7: Moderator deletes member's attachment
  await api.functional.discussionBoard.member.articles.attachments.erase(
    connection,
    {
      articleId: article.id,
      attachmentId: attachment.id,
    },
  );

  // Deletion succeeds if no error is thrown (void return type)
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IDiscussionBoardArticle } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardArticle";
import type { IDiscussionBoardArticleAttachment } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardArticleAttachment";
import type { IDiscussionBoardArticleCategory } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardArticleCategory";
import type { IDiscussionBoardMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardMember";
import type { IDiscussionBoardModerator } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardModerator";

/**
 * Test attachment deletion when an article has multiple attachments.
 *
 * This test validates that deleting a specific attachment from an article
 * containing multiple attachments removes only the targeted attachment while
 * leaving all other attachments intact and accessible.
 *
 * Test workflow:
 *
 * 1. Register and authenticate as a member
 * 2. Create a moderator and article category (prerequisites)
 * 3. Create an article as the authenticated member
 * 4. Upload multiple attachments (mix of images and documents)
 * 5. Delete one specific attachment by its ID
 * 6. Verify only the targeted attachment is removed
 * 7. Verify all other attachments remain accessible and unchanged
 */
export async function test_api_attachment_deletion_multiple_attachments(
  connection: api.IConnection,
) {
  // Step 1: Register and login as member
  const memberEmail = typia.random<string & tags.Format<"email">>();
  const memberPassword = "testPassword123!";

  const member = await api.functional.auth.member.join(connection, {
    body: {
      email: memberEmail,
      password: memberPassword,
      username: RandomGenerator.alphaNumeric(10),
      display_name: RandomGenerator.name(),
      bio: RandomGenerator.paragraph({ sentences: 5 }),
      href: "https://test.example.com/register",
      referrer: "https://test.example.com/home",
    } satisfies IDiscussionBoardMember.ICreate,
  });
  typia.assert(member);

  // Step 2: Create moderator and category
  const moderatorEmail = typia.random<string & tags.Format<"email">>();
  const moderator = await api.functional.auth.moderator.join(connection, {
    body: {
      email: moderatorEmail,
      password: "modPassword123!",
      username: RandomGenerator.alphaNumeric(10),
      display_name: RandomGenerator.name(),
      href: "https://test.example.com/mod-register",
      referrer: "https://test.example.com/home",
    } satisfies IDiscussionBoardModerator.ICreate,
  });
  typia.assert(moderator);

  const category =
    await api.functional.discussionBoard.moderator.categories.create(
      connection,
      {
        body: {
          name: "Test Category",
          slug: "test-category",
          description: "Category for testing attachments",
          sort_order: 1,
        } satisfies IDiscussionBoardArticleCategory.ICreate,
      },
    );
  typia.assert(category);

  // Step 3: Switch back to member and create article
  await api.functional.auth.member.login(connection, {
    body: {
      email: memberEmail,
      password: memberPassword,
      href: "https://test.example.com/login",
      referrer: "https://test.example.com/home",
    } satisfies IDiscussionBoardMember.ILogin,
  });

  const article = await api.functional.discussionBoard.member.articles.create(
    connection,
    {
      body: {
        title: RandomGenerator.paragraph({ sentences: 3 }),
        body: RandomGenerator.content({ paragraphs: 3 }),
        discussion_board_article_category_id: category.id,
        status: "published",
      } satisfies IDiscussionBoardArticle.ICreate,
    },
  );
  typia.assert(article);

  // Step 4: Upload multiple attachments (2 images, 2 documents)
  const attachments: IDiscussionBoardArticleAttachment[] = [];

  // Upload first image
  const attachment1 =
    await api.functional.discussionBoard.member.articles.attachments.create(
      connection,
      {
        articleId: article.id,
        body: {
          type: "image",
          format: "jpeg",
          size: typia.random<
            number &
              tags.Type<"int32"> &
              tags.Minimum<1> &
              tags.Maximum<5242880>
          >(),
          original_filename: "test-image-1.jpeg",
          storage_path: `/storage/images/${typia.random<string & tags.Format<"uuid">>()}.jpeg`,
        } satisfies IDiscussionBoardArticleAttachment.ICreate,
      },
    );
  typia.assert(attachment1);
  attachments.push(attachment1);

  // Upload second image (this will be deleted)
  const attachment2 =
    await api.functional.discussionBoard.member.articles.attachments.create(
      connection,
      {
        articleId: article.id,
        body: {
          type: "image",
          format: "png",
          size: typia.random<
            number &
              tags.Type<"int32"> &
              tags.Minimum<1> &
              tags.Maximum<5242880>
          >(),
          original_filename: "test-image-2.png",
          storage_path: `/storage/images/${typia.random<string & tags.Format<"uuid">>()}.png`,
        } satisfies IDiscussionBoardArticleAttachment.ICreate,
      },
    );
  typia.assert(attachment2);
  attachments.push(attachment2);

  // Upload first document
  const attachment3 =
    await api.functional.discussionBoard.member.articles.attachments.create(
      connection,
      {
        articleId: article.id,
        body: {
          type: "file",
          format: "pdf",
          size: typia.random<
            number &
              tags.Type<"int32"> &
              tags.Minimum<1> &
              tags.Maximum<10485760>
          >(),
          original_filename: "test-document-1.pdf",
          storage_path: `/storage/files/${typia.random<string & tags.Format<"uuid">>()}.pdf`,
        } satisfies IDiscussionBoardArticleAttachment.ICreate,
      },
    );
  typia.assert(attachment3);
  attachments.push(attachment3);

  // Upload second document
  const attachment4 =
    await api.functional.discussionBoard.member.articles.attachments.create(
      connection,
      {
        articleId: article.id,
        body: {
          type: "file",
          format: "docx",
          size: typia.random<
            number &
              tags.Type<"int32"> &
              tags.Minimum<1> &
              tags.Maximum<10485760>
          >(),
          original_filename: "test-document-2.docx",
          storage_path: `/storage/files/${typia.random<string & tags.Format<"uuid">>()}.docx`,
        } satisfies IDiscussionBoardArticleAttachment.ICreate,
      },
    );
  typia.assert(attachment4);
  attachments.push(attachment4);

  // Verify we have 4 attachments
  TestValidator.equals("should have 4 attachments", attachments.length, 4);

  // Step 5: Delete the second attachment (attachment2)
  const attachmentToDelete = attachment2;

  await api.functional.discussionBoard.member.articles.attachments.erase(
    connection,
    {
      articleId: article.id,
      attachmentId: attachmentToDelete.id,
    },
  );

  // Step 6: Verify deletion succeeded
  // The deletion should complete without error (void return)

  // Step 7: Verify remaining attachments
  // Since we don't have a list endpoint, we validate that we successfully:
  // - Created 4 attachments
  // - Deleted 1 specific attachment (attachment2)
  // - The remaining 3 attachments (attachment1, attachment3, attachment4) should still exist

  TestValidator.predicate(
    "deleted attachment should be the second image",
    attachmentToDelete.id === attachment2.id,
  );

  TestValidator.predicate(
    "deleted attachment format should be png",
    attachmentToDelete.format === "png",
  );

  // Verify the IDs of remaining attachments are different from deleted one
  const remainingAttachmentIds = [
    attachment1.id,
    attachment3.id,
    attachment4.id,
  ];

  TestValidator.predicate(
    "remaining attachments should not include deleted attachment ID",
    !remainingAttachmentIds.includes(attachmentToDelete.id),
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IDiscussionBoardArticle } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardArticle";
import type { IDiscussionBoardArticleCategory } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardArticleCategory";
import type { IDiscussionBoardContentReport } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardContentReport";
import type { IDiscussionBoardMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardMember";
import type { IDiscussionBoardModerator } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardModerator";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IPageIDiscussionBoardContentReport } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIDiscussionBoardContentReport";

/**
 * Test filtering content reports by resolution status to enable efficient
 * moderation queue management.
 *
 * This test validates that moderators can filter reports by status values:
 * pending, reviewed_no_action, reviewed_edited, and reviewed_removed. The test
 * queries the reports endpoint with different status filters to verify accurate
 * filtering and validates that pagination works correctly with status
 * filtering.
 *
 * Steps:
 *
 * 1. Create and authenticate as moderator
 * 2. Query reports with status filter for "pending" (most common moderation
 *    workflow)
 * 3. Query reports with status filter for "reviewed_no_action"
 * 4. Query reports with status filter for "reviewed_edited"
 * 5. Query reports with status filter for "reviewed_removed"
 * 6. Validate pagination metadata reflects filtered result sets accurately
 * 7. Verify that returned reports match the requested status exactly
 */
export async function test_api_content_reports_filtering_by_status(
  connection: api.IConnection,
) {
  // Step 1: Create and authenticate as moderator
  const moderatorEmail = typia.random<string & tags.Format<"email">>();
  const moderator = await api.functional.auth.moderator.join(connection, {
    body: {
      email: moderatorEmail,
      password: "moderator123!",
      username: RandomGenerator.alphaNumeric(8),
      display_name: RandomGenerator.name(),
      ip: "127.0.0.1",
      href: "https://example.com/moderator/join" satisfies string &
        tags.Format<"uri">,
      referrer: "" satisfies string & tags.Format<"uri">,
    } satisfies IDiscussionBoardModerator.ICreate,
  });
  typia.assert(moderator);

  // Step 2: Query reports filtered by "pending" status (most common workflow - unresolved reports)
  const pendingReportsPage =
    await api.functional.discussionBoard.moderator.contentReports.index(
      connection,
      {
        body: {
          page: 1,
          limit: 20,
          status: "pending",
        } satisfies IDiscussionBoardContentReport.IRequest,
      },
    );
  typia.assert(pendingReportsPage);

  // Validate pagination structure
  TestValidator.predicate(
    "pending reports pagination has valid current page",
    pendingReportsPage.pagination.current >= 0,
  );
  TestValidator.predicate(
    "pending reports pagination has valid limit",
    pendingReportsPage.pagination.limit > 0,
  );
  TestValidator.predicate(
    "pending reports pagination has valid records count",
    pendingReportsPage.pagination.records >= 0,
  );
  TestValidator.predicate(
    "pending reports pagination has valid pages count",
    pendingReportsPage.pagination.pages >= 0,
  );

  // Validate all returned reports have "pending" status
  for (const report of pendingReportsPage.data) {
    TestValidator.equals(
      "pending filtered report has pending status",
      report.status,
      "pending",
    );
  }

  // Step 3: Query reports filtered by "reviewed_no_action" status
  const noActionReportsPage =
    await api.functional.discussionBoard.moderator.contentReports.index(
      connection,
      {
        body: {
          page: 1,
          limit: 20,
          status: "reviewed_no_action",
        } satisfies IDiscussionBoardContentReport.IRequest,
      },
    );
  typia.assert(noActionReportsPage);

  // Validate all returned reports have "reviewed_no_action" status
  for (const report of noActionReportsPage.data) {
    TestValidator.equals(
      "no action filtered report has reviewed_no_action status",
      report.status,
      "reviewed_no_action",
    );
    // Resolved reports should have resolution details
    TestValidator.predicate(
      "reviewed report has resolved_by_moderator_id",
      report.resolved_by_moderator_id !== null &&
        report.resolved_by_moderator_id !== undefined,
    );
    TestValidator.predicate(
      "reviewed report has resolved_at timestamp",
      report.resolved_at !== null && report.resolved_at !== undefined,
    );
  }

  // Step 4: Query reports filtered by "reviewed_edited" status
  const editedReportsPage =
    await api.functional.discussionBoard.moderator.contentReports.index(
      connection,
      {
        body: {
          page: 1,
          limit: 20,
          status: "reviewed_edited",
        } satisfies IDiscussionBoardContentReport.IRequest,
      },
    );
  typia.assert(editedReportsPage);

  // Validate all returned reports have "reviewed_edited" status
  for (const report of editedReportsPage.data) {
    TestValidator.equals(
      "edited filtered report has reviewed_edited status",
      report.status,
      "reviewed_edited",
    );
    // Resolved reports should have resolution details
    TestValidator.predicate(
      "edited report has resolved_by_moderator_id",
      report.resolved_by_moderator_id !== null &&
        report.resolved_by_moderator_id !== undefined,
    );
    TestValidator.predicate(
      "edited report has resolved_at timestamp",
      report.resolved_at !== null && report.resolved_at !== undefined,
    );
  }

  // Step 5: Query reports filtered by "reviewed_removed" status
  const removedReportsPage =
    await api.functional.discussionBoard.moderator.contentReports.index(
      connection,
      {
        body: {
          page: 1,
          limit: 20,
          status: "reviewed_removed",
        } satisfies IDiscussionBoardContentReport.IRequest,
      },
    );
  typia.assert(removedReportsPage);

  // Validate all returned reports have "reviewed_removed" status
  for (const report of removedReportsPage.data) {
    TestValidator.equals(
      "removed filtered report has reviewed_removed status",
      report.status,
      "reviewed_removed",
    );
    // Resolved reports should have resolution details
    TestValidator.predicate(
      "removed report has resolved_by_moderator_id",
      report.resolved_by_moderator_id !== null &&
        report.resolved_by_moderator_id !== undefined,
    );
    TestValidator.predicate(
      "removed report has resolved_at timestamp",
      report.resolved_at !== null && report.resolved_at !== undefined,
    );
  }

  // Step 6: Test pagination with status filtering
  const paginatedPendingPage1 =
    await api.functional.discussionBoard.moderator.contentReports.index(
      connection,
      {
        body: {
          page: 1,
          limit: 5,
          status: "pending",
        } satisfies IDiscussionBoardContentReport.IRequest,
      },
    );
  typia.assert(paginatedPendingPage1);

  // Validate pagination metadata
  TestValidator.equals(
    "pagination current page matches request",
    paginatedPendingPage1.pagination.current,
    1,
  );
  TestValidator.equals(
    "pagination limit matches request",
    paginatedPendingPage1.pagination.limit,
    5,
  );

  // If there are more records than the limit, test page 2
  if (paginatedPendingPage1.pagination.records > 5) {
    const paginatedPendingPage2 =
      await api.functional.discussionBoard.moderator.contentReports.index(
        connection,
        {
          body: {
            page: 2,
            limit: 5,
            status: "pending",
          } satisfies IDiscussionBoardContentReport.IRequest,
        },
      );
    typia.assert(paginatedPendingPage2);

    TestValidator.equals(
      "page 2 current page matches request",
      paginatedPendingPage2.pagination.current,
      2,
    );
    TestValidator.equals(
      "page 2 total records matches page 1",
      paginatedPendingPage2.pagination.records,
      paginatedPendingPage1.pagination.records,
    );

    // Validate all reports on page 2 also have pending status
    for (const report of paginatedPendingPage2.data) {
      TestValidator.equals(
        "page 2 pending filtered report has pending status",
        report.status,
        "pending",
      );
    }
  }
}

