/**
 * Test filtering content reports by article ID to validate moderation workflow.
 *
 * This validates the filtering functionality where moderators can query all
 * reports for a specific article. While the test cannot create actual reports
 * (no creation API exists), it validates that the filtering endpoint correctly
 * accepts article ID parameters and returns properly structured responses.
 *
 * Test flow:
 *
 * 1. Create moderator account for authentication
 * 2. Create member account and article
 * 3. Filter content reports by the article ID
 * 4. Validate response structure and filtering parameters
 *
 * This ensures the filtering API is working correctly for the moderation
 * workflow where moderators need to view all community reports about specific
 * content.
 */
export async function test_api_content_reports_filtering_by_article(
  connection: api.IConnection,
) {
  // Step 1: Moderator registration and authentication
  const moderatorEmail = typia.random<string & tags.Format<"email">>();
  const moderator = await api.functional.auth.moderator.join(connection, {
    body: {
      email: moderatorEmail,
      password: "ModeratorPass123!",
      username: RandomGenerator.name(1),
      display_name: RandomGenerator.name(2),
      ip: "192.168.1.100",
      href: "https://discussion.example.com/moderator/join",
      referrer: "https://discussion.example.com/",
    } satisfies IDiscussionBoardModerator.ICreate,
  });
  typia.assert(moderator);

  // Step 2: Create member account for article creation
  const memberEmail = typia.random<string & tags.Format<"email">>();
  const member = await api.functional.auth.member.join(connection, {
    body: {
      email: memberEmail,
      password: "MemberPass123!",
      username: RandomGenerator.name(1),
      display_name: RandomGenerator.name(2),
      bio: RandomGenerator.paragraph({ sentences: 2 }),
      ip: "192.168.1.101",
      href: "https://discussion.example.com/member/join",
      referrer: "https://discussion.example.com/",
    } satisfies IDiscussionBoardMember.ICreate,
  });
  typia.assert(member);

  // Step 3: Switch to moderator and create category
  await api.functional.auth.moderator.login(connection, {
    body: {
      email: moderatorEmail,
      password: "ModeratorPass123!",
      ip: "192.168.1.100",
      href: "https://discussion.example.com/moderator/dashboard",
      referrer: "https://discussion.example.com/",
    } satisfies IDiscussionBoardModerator.ILogin,
  });

  const category =
    await api.functional.discussionBoard.moderator.categories.create(
      connection,
      {
        body: {
          name: "Political Discussion",
          slug: "political-discussion",
          description: "Discuss political topics and current events",
          sort_order: 1,
        } satisfies IDiscussionBoardArticleCategory.ICreate,
      },
    );
  typia.assert(category);

  // Step 4: Switch to member and create article
  await api.functional.auth.member.login(connection, {
    body: {
      email: memberEmail,
      password: "MemberPass123!",
      ip: "192.168.1.101",
      href: "https://discussion.example.com/articles/create",
      referrer: "https://discussion.example.com/",
    } satisfies IDiscussionBoardMember.ILogin,
  });

  const article = await api.functional.discussionBoard.member.articles.create(
    connection,
    {
      body: {
        title: RandomGenerator.paragraph({
          sentences: 3,
          wordMin: 3,
          wordMax: 7,
        }),
        body: RandomGenerator.content({
          paragraphs: 3,
          sentenceMin: 10,
          sentenceMax: 20,
        }),
        discussion_board_article_category_id: category.id,
        status: "published",
      } satisfies IDiscussionBoardArticle.ICreate,
    },
  );
  typia.assert(article);

  // Step 5: Switch back to moderator to filter reports
  await api.functional.auth.moderator.login(connection, {
    body: {
      email: moderatorEmail,
      password: "ModeratorPass123!",
      ip: "192.168.1.100",
      href: "https://discussion.example.com/moderator/reports",
      referrer: "https://discussion.example.com/moderator/dashboard",
    } satisfies IDiscussionBoardModerator.ILogin,
  });

  // Step 6: Filter content reports by article ID
  const filteredReports =
    await api.functional.discussionBoard.moderator.contentReports.index(
      connection,
      {
        body: {
          discussion_board_article_id: article.id,
          page: 1,
          limit: 20,
        } satisfies IDiscussionBoardContentReport.IRequest,
      },
    );
  typia.assert(filteredReports);

  // Step 7: Validate response structure
  TestValidator.predicate(
    "filtered reports response has valid pagination",
    filteredReports.pagination !== null &&
      filteredReports.pagination !== undefined,
  );

  TestValidator.predicate(
    "filtered reports response has data array",
    Array.isArray(filteredReports.data),
  );

  TestValidator.equals(
    "pagination current page matches request",
    filteredReports.pagination.current,
    1,
  );

  TestValidator.equals(
    "pagination limit matches request",
    filteredReports.pagination.limit,
    20,
  );

  // Step 8: Validate filtering works correctly
  for (const report of filteredReports.data) {
    TestValidator.equals(
      "all reports match the filtered article ID",
      report.discussion_board_article_id,
      article.id,
    );
  }
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IDiscussionBoardArticle } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardArticle";
import type { IDiscussionBoardArticleCategory } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardArticleCategory";
import type { IDiscussionBoardContentReport } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardContentReport";
import type { IDiscussionBoardMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardMember";
import type { IDiscussionBoardModerator } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardModerator";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IPageIDiscussionBoardContentReport } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIDiscussionBoardContentReport";

/**
 * Test content reports filtering API with date range parameters.
 *
 * This test validates that the content reports filtering endpoint accepts and
 * processes date range parameters (created_at_from, created_at_to,
 * resolved_at_from, resolved_at_to) correctly. Since no report creation API is
 * available, this test focuses on API structure validation and parameter
 * handling rather than business logic validation.
 *
 * The test verifies:
 *
 * - Moderator can access the content reports filtering endpoint
 * - Date range parameters are accepted in ISO 8601 format
 * - The API returns properly structured paginated responses
 * - Different date range combinations are processed without errors
 */
export async function test_api_content_reports_filtering_by_date_range(
  connection: api.IConnection,
) {
  // Create moderator account for accessing content reports
  const moderatorEmail = typia.random<string & tags.Format<"email">>();
  const moderator = await api.functional.auth.moderator.join(connection, {
    body: {
      email: moderatorEmail,
      password: "moderator123",
      username: RandomGenerator.alphaNumeric(10),
      display_name: RandomGenerator.name(),
      href: "https://example.com/moderator/join",
      referrer: "https://example.com/home",
    } satisfies IDiscussionBoardModerator.ICreate,
  });
  typia.assert(moderator);

  // Test 1: Filter with created_at date range
  const now = new Date();
  const pastWeek = new Date(now.getTime() - 7 * 24 * 60 * 60 * 1000);
  const futureDate = new Date(now.getTime() + 24 * 60 * 60 * 1000);

  const createdAtFilterResult =
    await api.functional.discussionBoard.moderator.contentReports.index(
      connection,
      {
        body: {
          created_at_from: pastWeek.toISOString(),
          created_at_to: now.toISOString(),
          page: 1,
          limit: 20,
        } satisfies IDiscussionBoardContentReport.IRequest,
      },
    );
  typia.assert(createdAtFilterResult);
  TestValidator.predicate(
    "created_at filter returns paginated response",
    typeof createdAtFilterResult.pagination.current === "number",
  );

  // Test 2: Filter with resolved_at date range
  const resolvedAtFilterResult =
    await api.functional.discussionBoard.moderator.contentReports.index(
      connection,
      {
        body: {
          resolved_at_from: pastWeek.toISOString(),
          resolved_at_to: now.toISOString(),
          page: 1,
          limit: 20,
        } satisfies IDiscussionBoardContentReport.IRequest,
      },
    );
  typia.assert(resolvedAtFilterResult);
  TestValidator.predicate(
    "resolved_at filter returns paginated response",
    typeof resolvedAtFilterResult.pagination.pages === "number",
  );

  // Test 3: Combined date range filters
  const combinedFilterResult =
    await api.functional.discussionBoard.moderator.contentReports.index(
      connection,
      {
        body: {
          created_at_from: pastWeek.toISOString(),
          created_at_to: now.toISOString(),
          resolved_at_from: pastWeek.toISOString(),
          resolved_at_to: now.toISOString(),
          page: 1,
          limit: 50,
        } satisfies IDiscussionBoardContentReport.IRequest,
      },
    );
  typia.assert(combinedFilterResult);
  TestValidator.predicate(
    "combined date filters return valid response",
    Array.isArray(combinedFilterResult.data),
  );

  // Test 4: Filter with future date range (should return empty results)
  const futureDateEnd = new Date(futureDate.getTime() + 24 * 60 * 60 * 1000);
  const futureRangeResult =
    await api.functional.discussionBoard.moderator.contentReports.index(
      connection,
      {
        body: {
          created_at_from: futureDate.toISOString(),
          created_at_to: futureDateEnd.toISOString(),
          page: 1,
          limit: 20,
        } satisfies IDiscussionBoardContentReport.IRequest,
      },
    );
  typia.assert(futureRangeResult);
  TestValidator.equals(
    "future date range returns empty results",
    futureRangeResult.data.length,
    0,
  );

  // Test 5: Filter with status and date range combination
  const statusWithDateResult =
    await api.functional.discussionBoard.moderator.contentReports.index(
      connection,
      {
        body: {
          status: "pending",
          created_at_from: pastWeek.toISOString(),
          created_at_to: now.toISOString(),
          page: 1,
          limit: 20,
        } satisfies IDiscussionBoardContentReport.IRequest,
      },
    );
  typia.assert(statusWithDateResult);
  TestValidator.predicate(
    "status filter combined with date range works",
    typeof statusWithDateResult.pagination.records === "number",
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IDiscussionBoardArticle } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardArticle";
import type { IDiscussionBoardArticleCategory } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardArticleCategory";
import type { IDiscussionBoardContentReport } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardContentReport";
import type { IDiscussionBoardMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardMember";
import type { IDiscussionBoardModerator } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardModerator";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IPageIDiscussionBoardContentReport } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIDiscussionBoardContentReport";

/**
 * Test pagination and sorting capabilities for content reports to enable
 * efficient navigation through large report datasets.
 *
 * This test validates that moderators can customize result presentation based
 * on their workflow needs by:
 *
 * 1. Testing pagination with various page sizes (default 20, maximum 100, custom
 *    values)
 * 2. Validating page navigation with accurate metadata (current page, total
 *    records, total pages)
 * 3. Testing sorting by created_at, resolved_at, and status in both ascending and
 *    descending order
 * 4. Verifying pagination metadata accuracy
 * 5. Testing combined filtering, sorting, and pagination scenarios
 *
 * Note: This test works with existing content reports in the system since the
 * API does not provide an endpoint for creating reports programmatically.
 */
export async function test_api_content_reports_pagination_and_sorting(
  connection: api.IConnection,
) {
  // Step 1: Authenticate as moderator
  const moderatorEmail = typia.random<string & tags.Format<"email">>();
  const moderator: IDiscussionBoardModerator.IAuthorized =
    await api.functional.auth.moderator.join(connection, {
      body: {
        email: moderatorEmail,
        password: "moderator123!",
        username: typia.random<
          string & tags.MinLength<3> & tags.MaxLength<30>
        >(),
        href: typia.random<string & tags.Format<"uri">>(),
        referrer: typia.random<string & tags.Format<"uri">>(),
      } satisfies IDiscussionBoardModerator.ICreate,
    });
  typia.assert(moderator);

  // Step 2: Test basic pagination with default limit
  const defaultPage: IPageIDiscussionBoardContentReport.ISummary =
    await api.functional.discussionBoard.moderator.contentReports.index(
      connection,
      {
        body: {
          page: 1,
        } satisfies IDiscussionBoardContentReport.IRequest,
      },
    );
  typia.assert(defaultPage);

  TestValidator.predicate(
    "pagination metadata should be valid",
    defaultPage.pagination.current === 1 &&
      defaultPage.pagination.limit >= 1 &&
      defaultPage.pagination.records >= 0 &&
      defaultPage.pagination.pages >= 0,
  );

  // Step 3: Test custom limit value of 10
  const customLimitPage: IPageIDiscussionBoardContentReport.ISummary =
    await api.functional.discussionBoard.moderator.contentReports.index(
      connection,
      {
        body: {
          page: 1,
          limit: 10,
        } satisfies IDiscussionBoardContentReport.IRequest,
      },
    );
  typia.assert(customLimitPage);

  TestValidator.equals(
    "custom limit of 10 should be applied",
    customLimitPage.pagination.limit,
    10,
  );

  // Step 4: Test maximum limit (100)
  const maxLimitPage: IPageIDiscussionBoardContentReport.ISummary =
    await api.functional.discussionBoard.moderator.contentReports.index(
      connection,
      {
        body: {
          page: 1,
          limit: 100,
        } satisfies IDiscussionBoardContentReport.IRequest,
      },
    );
  typia.assert(maxLimitPage);

  TestValidator.equals(
    "maximum limit of 100 should be applied",
    maxLimitPage.pagination.limit,
    100,
  );

  // Step 5: Test sorting by created_at ascending (oldest first)
  const sortedByCreatedAsc: IPageIDiscussionBoardContentReport.ISummary =
    await api.functional.discussionBoard.moderator.contentReports.index(
      connection,
      {
        body: {
          page: 1,
          limit: 50,
          sort_by: "created_at",
          order: "asc",
        } satisfies IDiscussionBoardContentReport.IRequest,
      },
    );
  typia.assert(sortedByCreatedAsc);

  if (sortedByCreatedAsc.data.length > 1) {
    for (let i = 0; i < sortedByCreatedAsc.data.length - 1; i++) {
      const current = new Date(sortedByCreatedAsc.data[i].created_at).getTime();
      const next = new Date(
        sortedByCreatedAsc.data[i + 1].created_at,
      ).getTime();
      TestValidator.predicate(
        "reports should be sorted by created_at ascending",
        current <= next,
      );
    }
  }

  // Step 6: Test sorting by created_at descending (newest first)
  const sortedByCreatedDesc: IPageIDiscussionBoardContentReport.ISummary =
    await api.functional.discussionBoard.moderator.contentReports.index(
      connection,
      {
        body: {
          page: 1,
          limit: 50,
          sort_by: "created_at",
          order: "desc",
        } satisfies IDiscussionBoardContentReport.IRequest,
      },
    );
  typia.assert(sortedByCreatedDesc);

  if (sortedByCreatedDesc.data.length > 1) {
    for (let i = 0; i < sortedByCreatedDesc.data.length - 1; i++) {
      const current = new Date(
        sortedByCreatedDesc.data[i].created_at,
      ).getTime();
      const next = new Date(
        sortedByCreatedDesc.data[i + 1].created_at,
      ).getTime();
      TestValidator.predicate(
        "reports should be sorted by created_at descending",
        current >= next,
      );
    }
  }

  // Step 7: Test sorting by resolved_at ascending
  const sortedByResolvedAsc: IPageIDiscussionBoardContentReport.ISummary =
    await api.functional.discussionBoard.moderator.contentReports.index(
      connection,
      {
        body: {
          page: 1,
          limit: 50,
          sort_by: "resolved_at",
          order: "asc",
        } satisfies IDiscussionBoardContentReport.IRequest,
      },
    );
  typia.assert(sortedByResolvedAsc);

  // Step 8: Test sorting by resolved_at descending
  const sortedByResolvedDesc: IPageIDiscussionBoardContentReport.ISummary =
    await api.functional.discussionBoard.moderator.contentReports.index(
      connection,
      {
        body: {
          page: 1,
          limit: 50,
          sort_by: "resolved_at",
          order: "desc",
        } satisfies IDiscussionBoardContentReport.IRequest,
      },
    );
  typia.assert(sortedByResolvedDesc);

  // Step 9: Test sorting by status alphabetically
  const sortedByStatus: IPageIDiscussionBoardContentReport.ISummary =
    await api.functional.discussionBoard.moderator.contentReports.index(
      connection,
      {
        body: {
          page: 1,
          limit: 50,
          sort_by: "status",
          order: "asc",
        } satisfies IDiscussionBoardContentReport.IRequest,
      },
    );
  typia.assert(sortedByStatus);

  if (sortedByStatus.data.length > 1) {
    for (let i = 0; i < sortedByStatus.data.length - 1; i++) {
      const current = sortedByStatus.data[i].status;
      const next = sortedByStatus.data[i + 1].status;
      TestValidator.predicate(
        "reports should be sorted by status alphabetically",
        current <= next,
      );
    }
  }

  // Step 10: Test combined filtering, sorting, and pagination with pending status
  const combinedQueryPending: IPageIDiscussionBoardContentReport.ISummary =
    await api.functional.discussionBoard.moderator.contentReports.index(
      connection,
      {
        body: {
          page: 1,
          limit: 50,
          status: "pending",
          sort_by: "created_at",
          order: "asc",
        } satisfies IDiscussionBoardContentReport.IRequest,
      },
    );
  typia.assert(combinedQueryPending);

  TestValidator.predicate(
    "combined query pagination metadata should be valid",
    combinedQueryPending.pagination.current === 1 &&
      combinedQueryPending.pagination.limit === 50 &&
      combinedQueryPending.pagination.records >= 0,
  );

  for (const report of combinedQueryPending.data) {
    TestValidator.equals(
      "filtered reports should have pending status",
      report.status,
      "pending",
    );
  }

  // Step 11: Test combined filtering with Spam category
  const combinedQuerySpam: IPageIDiscussionBoardContentReport.ISummary =
    await api.functional.discussionBoard.moderator.contentReports.index(
      connection,
      {
        body: {
          page: 1,
          limit: 20,
          report_category: "Spam",
          sort_by: "created_at",
          order: "desc",
        } satisfies IDiscussionBoardContentReport.IRequest,
      },
    );
  typia.assert(combinedQuerySpam);

  for (const report of combinedQuerySpam.data) {
    TestValidator.equals(
      "filtered reports should have Spam category",
      report.report_category,
      "Spam",
    );
  }

  // Step 12: Test page navigation if multiple pages exist
  if (defaultPage.pagination.pages > 1) {
    const secondPage: IPageIDiscussionBoardContentReport.ISummary =
      await api.functional.discussionBoard.moderator.contentReports.index(
        connection,
        {
          body: {
            page: 2,
          } satisfies IDiscussionBoardContentReport.IRequest,
        },
      );
    typia.assert(secondPage);

    TestValidator.equals(
      "second page current should be 2",
      secondPage.pagination.current,
      2,
    );

    TestValidator.equals(
      "second page should have same total records",
      secondPage.pagination.records,
      defaultPage.pagination.records,
    );

    if (secondPage.data.length > 0 && defaultPage.data.length > 0) {
      TestValidator.notEquals(
        "second page should have different reports than first page",
        secondPage.data[0].id,
        defaultPage.data[0].id,
      );
    }
  }

  // Step 13: Test date range filtering with created_at
  const now = new Date();
  const thirtyDaysAgo = new Date(now.getTime() - 30 * 24 * 60 * 60 * 1000);

  const dateRangeQuery: IPageIDiscussionBoardContentReport.ISummary =
    await api.functional.discussionBoard.moderator.contentReports.index(
      connection,
      {
        body: {
          page: 1,
          limit: 50,
          created_at_from: thirtyDaysAgo.toISOString(),
          created_at_to: now.toISOString(),
        } satisfies IDiscussionBoardContentReport.IRequest,
      },
    );
  typia.assert(dateRangeQuery);

  for (const report of dateRangeQuery.data) {
    const createdAt = new Date(report.created_at).getTime();
    TestValidator.predicate(
      "reports should be within date range",
      createdAt >= thirtyDaysAgo.getTime() && createdAt <= now.getTime(),
    );
  }
}

