import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IDiscussionBoardArticle } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardArticle";
import type { IDiscussionBoardArticleCategory } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardArticleCategory";
import type { IDiscussionBoardContentReport } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardContentReport";
import type { IDiscussionBoardMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardMember";
import type { IDiscussionBoardModerator } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardModerator";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IPageIDiscussionBoardContentReport } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIDiscussionBoardContentReport";

/**
 * Test complex filtering scenarios combining multiple filter criteria to
 * validate advanced moderation queue management.
 *
 * This test validates the content report filtering API's ability to handle
 * sophisticated filter combinations that moderators use in real-world
 * workflows. Tests all available filter parameters individually and in
 * combination to ensure the query pipeline works correctly with AND logic.
 * Validates response structure, pagination behavior, sorting options, and edge
 * cases across all filter combinations.
 *
 * Since no report creation API is available, this test focuses on validating
 * the filtering mechanics, API contract compliance, and proper handling of
 * filter parameters rather than testing against specific report data. All
 * filter combinations should return valid paginated responses with correct
 * structure regardless of whether reports exist in the system.
 */
export async function test_api_content_reports_combined_filters(
  connection: api.IConnection,
) {
  // Step 1: Create moderator for authentication
  const moderatorPassword = RandomGenerator.alphaNumeric(12);
  const moderator = await api.functional.auth.moderator.join(connection, {
    body: {
      email: typia.random<string & tags.Format<"email">>(),
      password: moderatorPassword,
      username: RandomGenerator.alphaNumeric(10),
      display_name: RandomGenerator.name(),
      href: typia.random<string & tags.Format<"uri">>(),
      referrer: typia.random<string & tags.Format<"uri">>(),
    } satisfies IDiscussionBoardModerator.ICreate,
  });
  typia.assert(moderator);

  // Step 2: Create category for potential article references
  const category =
    await api.functional.discussionBoard.moderator.categories.create(
      connection,
      {
        body: {
          name: "Test Category",
          slug: "test-category",
          description: RandomGenerator.paragraph({ sentences: 3 }),
          sort_order: 1,
        } satisfies IDiscussionBoardArticleCategory.ICreate,
      },
    );
  typia.assert(category);

  // Step 3: Test basic filtering - status filter
  const statusValues = [
    "pending",
    "reviewed_no_action",
    "reviewed_edited",
    "reviewed_removed",
  ] as const;
  for (const status of statusValues) {
    const result =
      await api.functional.discussionBoard.moderator.contentReports.index(
        connection,
        {
          body: {
            status: status,
            page: 1,
            limit: 20,
          } satisfies IDiscussionBoardContentReport.IRequest,
        },
      );
    typia.assert(result);
    TestValidator.predicate(
      `status filter '${status}' returns valid pagination`,
      result.pagination.current === 1,
    );
    TestValidator.predicate(
      `status filter '${status}' respects limit`,
      result.data.length <= 20,
    );
  }

  // Step 4: Test category filtering
  const categoryValues = [
    "Spam",
    "Offensive Content",
    "Misinformation",
    "Off-Topic",
    "Other",
  ] as const;
  for (const reportCategory of categoryValues) {
    const result =
      await api.functional.discussionBoard.moderator.contentReports.index(
        connection,
        {
          body: {
            report_category: reportCategory,
            page: 1,
            limit: 10,
          } satisfies IDiscussionBoardContentReport.IRequest,
        },
      );
    typia.assert(result);
    TestValidator.predicate(
      `category filter '${reportCategory}' returns valid response`,
      result.pagination.pages >= 0,
    );
  }

  // Step 5: Test date range filtering
  const now = new Date();
  const sevenDaysAgo = new Date(now.getTime() - 7 * 24 * 60 * 60 * 1000);
  const thirtyDaysAgo = new Date(now.getTime() - 30 * 24 * 60 * 60 * 1000);

  const dateRangeResult =
    await api.functional.discussionBoard.moderator.contentReports.index(
      connection,
      {
        body: {
          created_at_from: sevenDaysAgo.toISOString(),
          created_at_to: now.toISOString(),
          page: 1,
          limit: 20,
        } satisfies IDiscussionBoardContentReport.IRequest,
      },
    );
  typia.assert(dateRangeResult);
  TestValidator.predicate(
    "date range filter returns valid pagination",
    dateRangeResult.pagination.current === 1,
  );

  // Step 6: Test combined filters - status + category
  const statusCategoryResult =
    await api.functional.discussionBoard.moderator.contentReports.index(
      connection,
      {
        body: {
          status: "pending",
          report_category: "Spam",
          page: 1,
          limit: 20,
        } satisfies IDiscussionBoardContentReport.IRequest,
      },
    );
  typia.assert(statusCategoryResult);
  TestValidator.predicate(
    "status + category filter works",
    statusCategoryResult.pagination.records >= 0,
  );

  // Step 7: Test combined filters - status + date range
  const statusDateResult =
    await api.functional.discussionBoard.moderator.contentReports.index(
      connection,
      {
        body: {
          status: "pending",
          created_at_from: thirtyDaysAgo.toISOString(),
          created_at_to: now.toISOString(),
          page: 1,
          limit: 15,
        } satisfies IDiscussionBoardContentReport.IRequest,
      },
    );
  typia.assert(statusDateResult);
  TestValidator.predicate(
    "status + date range filter respects limit",
    statusDateResult.data.length <= 15,
  );

  // Step 8: Test triple combination - status + category + date range
  const tripleFilterResult =
    await api.functional.discussionBoard.moderator.contentReports.index(
      connection,
      {
        body: {
          status: "pending",
          report_category: "Misinformation",
          created_at_from: sevenDaysAgo.toISOString(),
          created_at_to: now.toISOString(),
          page: 1,
          limit: 10,
        } satisfies IDiscussionBoardContentReport.IRequest,
      },
    );
  typia.assert(tripleFilterResult);
  TestValidator.predicate(
    "triple filter combination works",
    tripleFilterResult.pagination.pages >= 0,
  );

  // Step 9: Test sorting options
  const sortByValues = ["created_at", "resolved_at", "status"] as const;
  const orderValues = ["asc", "desc"] as const;

  for (const sortBy of sortByValues) {
    for (const order of orderValues) {
      const sortResult =
        await api.functional.discussionBoard.moderator.contentReports.index(
          connection,
          {
            body: {
              sort_by: sortBy,
              order: order,
              page: 1,
              limit: 10,
            } satisfies IDiscussionBoardContentReport.IRequest,
          },
        );
      typia.assert(sortResult);
      TestValidator.predicate(
        `sort by ${sortBy} ${order} works`,
        sortResult.pagination.current === 1,
      );
    }
  }

  // Step 10: Test pagination with filters
  const page1Result =
    await api.functional.discussionBoard.moderator.contentReports.index(
      connection,
      {
        body: {
          status: "pending",
          page: 1,
          limit: 5,
        } satisfies IDiscussionBoardContentReport.IRequest,
      },
    );
  typia.assert(page1Result);
  TestValidator.predicate(
    "page 1 respects limit",
    page1Result.data.length <= 5,
  );
  TestValidator.predicate(
    "page 1 pagination is correct",
    page1Result.pagination.limit === 5,
  );

  const page2Result =
    await api.functional.discussionBoard.moderator.contentReports.index(
      connection,
      {
        body: {
          status: "pending",
          page: 2,
          limit: 5,
        } satisfies IDiscussionBoardContentReport.IRequest,
      },
    );
  typia.assert(page2Result);
  TestValidator.predicate("page 2 works", page2Result.pagination.current === 2);

  // Step 11: Test edge case - future date range (should return empty)
  const futureDate = new Date(now.getTime() + 365 * 24 * 60 * 60 * 1000);
  const emptyResult =
    await api.functional.discussionBoard.moderator.contentReports.index(
      connection,
      {
        body: {
          created_at_from: futureDate.toISOString(),
          page: 1,
          limit: 20,
        } satisfies IDiscussionBoardContentReport.IRequest,
      },
    );
  typia.assert(emptyResult);
  TestValidator.predicate(
    "future date filter returns empty data",
    emptyResult.data.length === 0,
  );
  TestValidator.predicate(
    "future date filter shows zero records",
    emptyResult.pagination.records === 0,
  );

  // Step 12: Test resolved date filtering
  const resolvedDateResult =
    await api.functional.discussionBoard.moderator.contentReports.index(
      connection,
      {
        body: {
          resolved_at_from: thirtyDaysAgo.toISOString(),
          resolved_at_to: now.toISOString(),
          page: 1,
          limit: 20,
        } satisfies IDiscussionBoardContentReport.IRequest,
      },
    );
  typia.assert(resolvedDateResult);
  TestValidator.predicate(
    "resolved date range filter works",
    resolvedDateResult.pagination.current === 1,
  );

  // Step 13: Test comprehensive filter combination
  const comprehensiveResult =
    await api.functional.discussionBoard.moderator.contentReports.index(
      connection,
      {
        body: {
          page: 1,
          limit: 10,
          status: "reviewed_no_action",
          report_category: "Other",
          created_at_from: thirtyDaysAgo.toISOString(),
          created_at_to: now.toISOString(),
          sort_by: "created_at",
          order: "desc",
        } satisfies IDiscussionBoardContentReport.IRequest,
      },
    );
  typia.assert(comprehensiveResult);
  TestValidator.predicate(
    "comprehensive filter returns valid structure",
    comprehensiveResult.pagination.pages >= 0,
  );
  TestValidator.predicate(
    "comprehensive filter respects page",
    comprehensiveResult.pagination.current === 1,
  );
  TestValidator.predicate(
    "comprehensive filter respects limit",
    comprehensiveResult.data.length <= 10,
  );

  // Step 14: Test with random UUID references (should return empty or valid results)
  const randomArticleId = typia.random<string & tags.Format<"uuid">>();
  const randomMemberId = typia.random<string & tags.Format<"uuid">>();
  const randomModeratorId = typia.random<string & tags.Format<"uuid">>();

  const articleFilterResult =
    await api.functional.discussionBoard.moderator.contentReports.index(
      connection,
      {
        body: {
          discussion_board_article_id: randomArticleId,
          page: 1,
          limit: 20,
        } satisfies IDiscussionBoardContentReport.IRequest,
      },
    );
  typia.assert(articleFilterResult);

  const memberFilterResult =
    await api.functional.discussionBoard.moderator.contentReports.index(
      connection,
      {
        body: {
          discussion_board_member_id: randomMemberId,
          page: 1,
          limit: 20,
        } satisfies IDiscussionBoardContentReport.IRequest,
      },
    );
  typia.assert(memberFilterResult);

  const moderatorFilterResult =
    await api.functional.discussionBoard.moderator.contentReports.index(
      connection,
      {
        body: {
          resolved_by_moderator_id: randomModeratorId,
          page: 1,
          limit: 20,
        } satisfies IDiscussionBoardContentReport.IRequest,
      },
    );
  typia.assert(moderatorFilterResult);

  // Step 15: Test all filters combined
  const allFiltersResult =
    await api.functional.discussionBoard.moderator.contentReports.index(
      connection,
      {
        body: {
          page: 1,
          limit: 20,
          status: "pending",
          report_category: "Spam",
          discussion_board_article_id: randomArticleId,
          discussion_board_member_id: randomMemberId,
          resolved_by_moderator_id: randomModeratorId,
          created_at_from: thirtyDaysAgo.toISOString(),
          created_at_to: now.toISOString(),
          resolved_at_from: thirtyDaysAgo.toISOString(),
          resolved_at_to: now.toISOString(),
          sort_by: "status",
          order: "asc",
        } satisfies IDiscussionBoardContentReport.IRequest,
      },
    );
  typia.assert(allFiltersResult);
  TestValidator.predicate(
    "all filters combined returns valid response",
    allFiltersResult.pagination.records >= 0,
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IDiscussionBoardArticle } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardArticle";
import type { IDiscussionBoardArticleCategory } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardArticleCategory";
import type { IDiscussionBoardMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardMember";
import type { IDiscussionBoardModerator } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardModerator";

/**
 * Test article creation with various title lengths to validate the 5-200
 * character constraint.
 *
 * This test validates the business rule that article titles must be between 5
 * and 200 characters to ensure they are concise yet descriptive enough to
 * convey the discussion topic.
 *
 * Test flow:
 *
 * 1. Create moderator account for category management
 * 2. Create article category (prerequisite for article creation)
 * 3. Create member account for article authorship
 * 4. Test boundary values:
 *
 *    - 4 characters (below minimum) - should fail
 *    - 5 characters (exact minimum) - should succeed
 *    - 200 characters (exact maximum) - should succeed
 *    - 201 characters (above maximum) - should fail
 */
export async function test_api_article_creation_title_length_validation(
  connection: api.IConnection,
) {
  // Step 1: Create moderator account for category creation
  const moderatorEmail = typia.random<string & tags.Format<"email">>();
  const moderator = await api.functional.auth.moderator.join(connection, {
    body: {
      email: moderatorEmail,
      password: "SecurePass123!",
      username: RandomGenerator.alphaNumeric(8),
      display_name: RandomGenerator.name(),
      href: typia.random<string & tags.Format<"uri">>(),
      referrer: typia.random<string & tags.Format<"uri">>(),
    } satisfies IDiscussionBoardModerator.ICreate,
  });
  typia.assert(moderator);

  // Step 2: Create article category
  const category =
    await api.functional.discussionBoard.moderator.categories.create(
      connection,
      {
        body: {
          name: "Economic Discussion",
          slug: "economic-discussion",
          description: "Discuss economic policies and market trends",
          sort_order: 1,
        } satisfies IDiscussionBoardArticleCategory.ICreate,
      },
    );
  typia.assert(category);

  // Step 3: Create member account for article creation
  const memberEmail = typia.random<string & tags.Format<"email">>();
  const member = await api.functional.auth.member.join(connection, {
    body: {
      email: memberEmail,
      password: "MemberPass123!",
      username: RandomGenerator.alphaNumeric(10),
      display_name: RandomGenerator.name(),
      bio: RandomGenerator.paragraph({ sentences: 5 }),
      href: typia.random<string & tags.Format<"uri">>(),
      referrer: typia.random<string & tags.Format<"uri">>(),
    } satisfies IDiscussionBoardMember.ICreate,
  });
  typia.assert(member);

  // Common test data
  const validBody = RandomGenerator.content({
    paragraphs: 3,
    sentenceMin: 20,
    sentenceMax: 30,
  });

  // Test Case 1: Title with 4 characters (below minimum) - should fail
  await TestValidator.error(
    "article creation should fail with title length 4 (below minimum 5)",
    async () => {
      await api.functional.discussionBoard.member.articles.create(connection, {
        body: {
          title: "abcd",
          body: validBody,
          discussion_board_article_category_id: category.id,
          status: "published",
        } satisfies IDiscussionBoardArticle.ICreate,
      });
    },
  );

  // Test Case 2: Title with 5 characters (exact minimum) - should succeed
  const article5 = await api.functional.discussionBoard.member.articles.create(
    connection,
    {
      body: {
        title: "abcde",
        body: validBody,
        discussion_board_article_category_id: category.id,
        status: "published",
      } satisfies IDiscussionBoardArticle.ICreate,
    },
  );
  typia.assert(article5);
  TestValidator.equals(
    "title length 5 should be accepted",
    article5.title.length,
    5,
  );

  // Test Case 3: Title with 200 characters (exact maximum) - should succeed
  const title200 = "a".repeat(200);
  const article200 =
    await api.functional.discussionBoard.member.articles.create(connection, {
      body: {
        title: title200,
        body: validBody,
        discussion_board_article_category_id: category.id,
        status: "published",
      } satisfies IDiscussionBoardArticle.ICreate,
    });
  typia.assert(article200);
  TestValidator.equals(
    "title length 200 should be accepted",
    article200.title.length,
    200,
  );

  // Test Case 4: Title with 201 characters (above maximum) - should fail
  await TestValidator.error(
    "article creation should fail with title length 201 (above maximum 200)",
    async () => {
      await api.functional.discussionBoard.member.articles.create(connection, {
        body: {
          title: "a".repeat(201),
          body: validBody,
          discussion_board_article_category_id: category.id,
          status: "published",
        } satisfies IDiscussionBoardArticle.ICreate,
      });
    },
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IDiscussionBoardArticle } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardArticle";
import type { IDiscussionBoardArticleCategory } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardArticleCategory";
import type { IDiscussionBoardMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardMember";
import type { IDiscussionBoardModerator } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardModerator";

/**
 * Test article creation with various body content lengths to validate the
 * 50-50000 character constraint.
 *
 * This test validates that the system enforces minimum substantive content
 * requirements (50 characters) and prevents excessively long articles (50000
 * character maximum). Test verifies that bodies with fewer than 50 characters
 * are rejected, exactly 50 characters are accepted, 50000 characters are
 * accepted, and content exceeding 50000 characters is rejected.
 *
 * Test Flow:
 *
 * 1. Create moderator account
 * 2. Create article category
 * 3. Create member account
 * 4. Test body length below minimum (49 chars) - should fail
 * 5. Test body length at minimum boundary (50 chars) - should succeed
 * 6. Test body length at maximum boundary (50000 chars) - should succeed
 * 7. Test body length above maximum (50001 chars) - should fail
 */
export async function test_api_article_creation_body_length_validation(
  connection: api.IConnection,
) {
  // Step 1: Create moderator account for category setup
  const moderatorEmail = typia.random<string & tags.Format<"email">>();
  const moderator = await api.functional.auth.moderator.join(connection, {
    body: {
      email: moderatorEmail,
      password: "moderator123!",
      username: RandomGenerator.alphaNumeric(8),
      display_name: RandomGenerator.name(),
      ip: "127.0.0.1",
      href: "https://example.com/moderator/join",
      referrer: "https://example.com",
    } satisfies IDiscussionBoardModerator.ICreate,
  });
  typia.assert(moderator);

  // Step 2: Create article category
  const category =
    await api.functional.discussionBoard.moderator.categories.create(
      connection,
      {
        body: {
          name: "General Discussion",
          slug: "general-discussion",
          description: "General discussion category for testing",
          sort_order: 1,
        } satisfies IDiscussionBoardArticleCategory.ICreate,
      },
    );
  typia.assert(category);

  // Step 3: Create member account for article creation
  const memberEmail = typia.random<string & tags.Format<"email">>();
  const member = await api.functional.auth.member.join(connection, {
    body: {
      email: memberEmail,
      password: "member123!",
      username: RandomGenerator.alphaNumeric(8),
      display_name: RandomGenerator.name(),
      bio: RandomGenerator.paragraph({ sentences: 5 }),
      ip: "127.0.0.1",
      href: "https://example.com/member/join",
      referrer: "https://example.com",
    } satisfies IDiscussionBoardMember.ICreate,
  });
  typia.assert(member);

  // Step 4: Test body length below minimum (49 characters) - should fail
  const bodyTooShort = RandomGenerator.alphabets(49);
  await TestValidator.error(
    "body with 49 characters should fail validation",
    async () => {
      await api.functional.discussionBoard.member.articles.create(connection, {
        body: {
          title: "Test Article Title",
          body: bodyTooShort,
          discussion_board_article_category_id: category.id,
          status: "published",
        } satisfies IDiscussionBoardArticle.ICreate,
      });
    },
  );

  // Step 5: Test body length at minimum boundary (exactly 50 characters) - should succeed
  const bodyMinimum = RandomGenerator.alphabets(50);
  const articleMinimum =
    await api.functional.discussionBoard.member.articles.create(connection, {
      body: {
        title: "Article With Minimum Body Length",
        body: bodyMinimum,
        discussion_board_article_category_id: category.id,
        status: "published",
      } satisfies IDiscussionBoardArticle.ICreate,
    });
  typia.assert(articleMinimum);
  TestValidator.equals(
    "minimum body length matches",
    articleMinimum.body,
    bodyMinimum,
  );

  // Step 6: Test body length at maximum boundary (exactly 50000 characters) - should succeed
  const bodyMaximum = RandomGenerator.alphabets(50000);
  const articleMaximum =
    await api.functional.discussionBoard.member.articles.create(connection, {
      body: {
        title: "Article With Maximum Body Length",
        body: bodyMaximum,
        discussion_board_article_category_id: category.id,
        status: "published",
      } satisfies IDiscussionBoardArticle.ICreate,
    });
  typia.assert(articleMaximum);
  TestValidator.equals(
    "maximum body length matches",
    articleMaximum.body,
    bodyMaximum,
  );

  // Step 7: Test body length above maximum (50001 characters) - should fail
  const bodyTooLong = RandomGenerator.alphabets(50001);
  await TestValidator.error(
    "body with 50001 characters should fail validation",
    async () => {
      await api.functional.discussionBoard.member.articles.create(connection, {
        body: {
          title: "Test Article Exceeding Maximum",
          body: bodyTooLong,
          discussion_board_article_category_id: category.id,
          status: "published",
        } satisfies IDiscussionBoardArticle.ICreate,
      });
    },
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IDiscussionBoardArticle } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardArticle";
import type { IDiscussionBoardArticleCategory } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardArticleCategory";
import type { IDiscussionBoardMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardMember";
import type { IDiscussionBoardModerator } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardModerator";

/**
 * Test article creation workflow when multiple categories exist in the system.
 *
 * This test validates that members can correctly select from available
 * categories and that the article is properly associated with the chosen
 * category. Creates multiple categories (Economic Discussion, Political
 * Discussion, General Discussion) and verifies that articles can be created
 * under each category correctly. Validates that the category association is
 * properly stored and that the article's category field contains complete
 * category information including name, slug, and description in the response.
 *
 * Test Steps:
 *
 * 1. Create moderator account for category management
 * 2. Create three test categories with different topics
 * 3. Create member account for article authoring
 * 4. Create articles under each category
 * 5. Validate category associations and complete category data in responses
 */
export async function test_api_article_creation_multiple_categories(
  connection: api.IConnection,
) {
  // Step 1: Create moderator account
  const moderatorEmail = typia.random<string & tags.Format<"email">>();
  const moderatorPassword = "moderator123!";

  const moderator = await api.functional.auth.moderator.join(connection, {
    body: {
      email: moderatorEmail,
      password: moderatorPassword,
      username: RandomGenerator.alphaNumeric(10),
      display_name: RandomGenerator.name(2),
      ip: "127.0.0.1",
      href: "https://example.com/moderator/join",
      referrer: "https://example.com",
    } satisfies IDiscussionBoardModerator.ICreate,
  });
  typia.assert(moderator);

  // Step 2: Create multiple test categories
  const categoryData = [
    {
      name: "Economic Discussion",
      slug: "economic-discussion",
      description:
        "Discussions about economic policies, markets, and fiscal topics",
      sort_order: 1,
    },
    {
      name: "Political Discussion",
      slug: "political-discussion",
      description:
        "Discussions about governance, elections, and political systems",
      sort_order: 2,
    },
    {
      name: "General Discussion",
      slug: "general-discussion",
