    "Political Discussion",
  );

  TestValidator.equals(
    "category slug updated in response",
    updatedArticle.category.slug,
    "political-discussion",
  );

  // Verify article ID remains the same
  TestValidator.equals(
    "article ID unchanged after category reassignment",
    updatedArticle.id,
    article.id,
  );
}

