    "Offensive Content",
    "Misinformation",
    "Off-Topic",
    "Other",
  ] as const;
  const submittedReports: IDiscussionBoardContentReport[] =
    await ArrayUtil.asyncRepeat(27, async (index) => {
      const reportData = {
        discussion_board_article_id: articles[index].id,
        report_category: RandomGenerator.pick(reportCategories),
        report_details: RandomGenerator.paragraph({
          sentences: 8,
          wordMin: 5,
          wordMax: 10,
        }),
      } satisfies IDiscussionBoardContentReport.ICreate;

      const report: IDiscussionBoardContentReport =
        await api.functional.discussionBoard.member.articles.reports.create(
          connection,
          {
            articleId: articles[index].id,
            body: reportData,
          },
        );
      typia.assert(report);
      return report;
    });

  // Step 6: Switch to moderator account and retrieve first page with limit=5
  await api.functional.auth.moderator.login(connection, {
    body: {
      email: moderatorData.email,
      password: moderatorData.password,
      ip: "127.0.0.1",
      href: "https://example.com/moderator/login" satisfies string &
        tags.Format<"uri">,
      referrer: "https://example.com" satisfies string & tags.Format<"uri">,
    } satisfies IDiscussionBoardModerator.ILogin,
  });

  const firstPageRequest = {
    page: 1 satisfies number & tags.Type<"int32"> & tags.Minimum<1>,
    limit: 5 satisfies number &
      tags.Type<"int32"> &
      tags.Minimum<1> &
      tags.Maximum<100>,
  } satisfies IDiscussionBoardContentReport.IRequest;

  const firstPage: IPageIDiscussionBoardContentReport.ISummary =
    await api.functional.discussionBoard.moderator.members.reports.index(
      connection,
      {
        memberId: member.id,
        body: firstPageRequest,
      },
    );
  typia.assert(firstPage);

  // Step 7: Validate first page pagination metadata
  TestValidator.equals("first page current", firstPage.pagination.current, 1);
  TestValidator.equals("first page limit", firstPage.pagination.limit, 5);
  TestValidator.equals(
    "first page total records",
    firstPage.pagination.records,
    27,
  );
  TestValidator.equals("first page total pages", firstPage.pagination.pages, 6);
  TestValidator.equals("first page data length", firstPage.data.length, 5);

  // Step 8: Retrieve all pages and collect all reports
  const allReportsFromPages: IDiscussionBoardContentReport.ISummary[] = [
    ...firstPage.data,
  ];

  for (let pageNum = 2; pageNum <= 6; pageNum++) {
    const pageRequest = {
      page: pageNum satisfies number & tags.Type<"int32"> & tags.Minimum<1>,
      limit: 5 satisfies number &
        tags.Type<"int32"> &
        tags.Minimum<1> &
        tags.Maximum<100>,
    } satisfies IDiscussionBoardContentReport.IRequest;

    const page: IPageIDiscussionBoardContentReport.ISummary =
      await api.functional.discussionBoard.moderator.members.reports.index(
        connection,
        {
          memberId: member.id,
          body: pageRequest,
        },
      );
    typia.assert(page);

    // Validate pagination metadata for each page
    TestValidator.equals(
      `page ${pageNum} current`,
      page.pagination.current,
      pageNum,
    );
    TestValidator.equals(`page ${pageNum} limit`, page.pagination.limit, 5);
    TestValidator.equals(
      `page ${pageNum} total records`,
      page.pagination.records,
      27,
    );
    TestValidator.equals(
      `page ${pageNum} total pages`,
      page.pagination.pages,
      6,
    );

    // Last page should have 2 reports (27 % 5 = 2)
    if (pageNum === 6) {
      TestValidator.equals("last page data length", page.data.length, 2);
    } else {
      TestValidator.equals(`page ${pageNum} data length`, page.data.length, 5);
    }

    allReportsFromPages.push(...page.data);
  }

  // Step 9: Validate all reports were retrieved exactly once
  TestValidator.equals(
    "total reports collected",
    allReportsFromPages.length,
    27,
  );

  // Step 10: Verify no duplicate report IDs
  const reportIds = allReportsFromPages.map((r) => r.id);
  const uniqueIds = new Set(reportIds);
  TestValidator.equals("no duplicate reports", uniqueIds.size, 27);

  // Step 11: Verify all submitted reports are present in paginated results
  for (const submittedReport of submittedReports) {
    const found = allReportsFromPages.find((r) => r.id === submittedReport.id);
    TestValidator.predicate(
      `report ${submittedReport.id} exists in paginated results`,
      found !== undefined,
    );
  }
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IDiscussionBoardArticle } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardArticle";
import type { IDiscussionBoardArticleCategory } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardArticleCategory";
import type { IDiscussionBoardContentReport } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardContentReport";
import type { IDiscussionBoardMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardMember";
import type { IDiscussionBoardModerator } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardModerator";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IPageIDiscussionBoardContentReport } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIDiscussionBoardContentReport";

/**
 * Test sorting member report history by submission timestamp.
 *
 * This test validates that the member report history API correctly sorts
 * reports by their creation timestamp (created_at field) in both ascending and
 * descending order.
 *
 * Test Flow:
 *
 * 1. Create moderator account for report retrieval access
 * 2. Create article categories for test infrastructure
 * 3. Create member account who will submit reports
 * 4. Create multiple articles as report targets
 * 5. Submit multiple reports at different times with delays between submissions
 * 6. Retrieve reports sorted by created_at ascending (oldest first)
 * 7. Validate reports are in chronological order
 * 8. Retrieve reports sorted by created_at descending (newest first)
 * 9. Validate reports are in reverse chronological order
 */
export async function test_api_member_report_history_sorted_by_created_at(
  connection: api.IConnection,
) {
  // Step 1: Create moderator account
  const moderator = await api.functional.auth.moderator.join(connection, {
    body: {
      email: typia.random<string & tags.Format<"email">>(),
      password: "moderator123!",
      username: RandomGenerator.name(1),
      display_name: RandomGenerator.name(2),
      ip: "127.0.0.1",
      href: typia.random<string & tags.Format<"uri">>(),
      referrer: typia.random<string & tags.Format<"uri">>(),
    } satisfies IDiscussionBoardModerator.ICreate,
  });
  typia.assert(moderator);

  // Step 2: Create article category
  const category =
    await api.functional.discussionBoard.moderator.categories.create(
      connection,
      {
        body: {
          name: "Test Category",
          slug: "test-category",
          description: "Category for testing report sorting",
          sort_order: 1,
        } satisfies IDiscussionBoardArticleCategory.ICreate,
      },
    );
  typia.assert(category);

  // Step 3: Create member account who will submit reports
  const memberEmail = typia.random<string & tags.Format<"email">>();
  const memberPassword = "member123!";
  const member = await api.functional.auth.member.join(connection, {
    body: {
      email: memberEmail,
      password: memberPassword,
      username: RandomGenerator.name(1),
      display_name: RandomGenerator.name(2),
      ip: "127.0.0.1",
      href: typia.random<string & tags.Format<"uri">>(),
      referrer: typia.random<string & tags.Format<"uri">>(),
    } satisfies IDiscussionBoardMember.ICreate,
  });
  typia.assert(member);

  // Step 4: Create multiple articles as report targets
  const articles: IDiscussionBoardArticle[] = [];
  for (let i = 0; i < 3; i++) {
    const article = await api.functional.discussionBoard.member.articles.create(
      connection,
      {
        body: {
          title: RandomGenerator.paragraph({ sentences: 3 }),
          body: RandomGenerator.content({ paragraphs: 2 }),
          discussion_board_article_category_id: category.id,
          status: "published",
        } satisfies IDiscussionBoardArticle.ICreate,
      },
    );
    typia.assert(article);
    articles.push(article);
  }

  // Step 5: Submit multiple reports at different times with delays
  const reportCategories = [
    "Spam",
    "Offensive Content",
    "Misinformation",
  ] as const;
  const submittedReports: IDiscussionBoardContentReport[] = [];

  for (let i = 0; i < 3; i++) {
    const report =
      await api.functional.discussionBoard.member.articles.reports.create(
        connection,
        {
          articleId: articles[i].id,
          body: {
            discussion_board_article_id: articles[i].id,
            report_category: reportCategories[i],
            report_details: RandomGenerator.paragraph({ sentences: 5 }),
          } satisfies IDiscussionBoardContentReport.ICreate,
        },
      );
    typia.assert(report);
    submittedReports.push(report);

    // Add delay between submissions to ensure distinct created_at timestamps
    if (i < 2) {
      await new Promise((resolve) => setTimeout(resolve, 100));
    }
  }

  // Step 6: Switch back to moderator and retrieve reports sorted ascending
  await api.functional.auth.moderator.login(connection, {
    body: {
      email: moderator.email,
      password: "moderator123!",
      ip: "127.0.0.1",
      href: typia.random<string & tags.Format<"uri">>(),
      referrer: typia.random<string & tags.Format<"uri">>(),
    } satisfies IDiscussionBoardModerator.ILogin,
  });

  const ascendingResult =
    await api.functional.discussionBoard.moderator.members.reports.index(
      connection,
      {
        memberId: member.id,
        body: {
          sort_by: "created_at",
          order: "asc",
        } satisfies IDiscussionBoardContentReport.IRequest,
      },
    );
  typia.assert(ascendingResult);

  // Step 7: Validate ascending order (oldest first)
  TestValidator.equals(
    "ascending sort should return all reports",
    ascendingResult.data.length,
    3,
  );

  for (let i = 0; i < ascendingResult.data.length - 1; i++) {
    const currentTimestamp = new Date(
      ascendingResult.data[i].created_at,
    ).getTime();
    const nextTimestamp = new Date(
      ascendingResult.data[i + 1].created_at,
    ).getTime();
    TestValidator.predicate(
      "reports should be in ascending chronological order",
      currentTimestamp <= nextTimestamp,
    );
  }

  // Step 8: Retrieve reports sorted descending
  const descendingResult =
    await api.functional.discussionBoard.moderator.members.reports.index(
      connection,
      {
        memberId: member.id,
        body: {
          sort_by: "created_at",
          order: "desc",
        } satisfies IDiscussionBoardContentReport.IRequest,
      },
    );
  typia.assert(descendingResult);

  // Step 9: Validate descending order (newest first)
  TestValidator.equals(
    "descending sort should return all reports",
    descendingResult.data.length,
    3,
  );

  for (let i = 0; i < descendingResult.data.length - 1; i++) {
    const currentTimestamp = new Date(
      descendingResult.data[i].created_at,
    ).getTime();
    const nextTimestamp = new Date(
      descendingResult.data[i + 1].created_at,
    ).getTime();
    TestValidator.predicate(
      "reports should be in descending chronological order",
      currentTimestamp >= nextTimestamp,
    );
  }

  // Validate that ascending and descending results are reverse of each other
  const ascendingIds = ascendingResult.data.map((r) => r.id);
  const descendingIds = descendingResult.data.map((r) => r.id);
  TestValidator.equals(
    "ascending and descending should contain same reports in reverse order",
    [...ascendingIds].reverse(),
    descendingIds,
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IDiscussionBoardArticle } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardArticle";
import type { IDiscussionBoardArticleCategory } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardArticleCategory";
import type { IDiscussionBoardContentReport } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardContentReport";
import type { IDiscussionBoardMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardMember";
import type { IDiscussionBoardModerator } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardModerator";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IPageIDiscussionBoardContentReport } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIDiscussionBoardContentReport";

/**
 * Test filtering member reports by date range using created_at_from and
 * created_at_to parameters.
 *
 * This test validates the date range filtering functionality for member report
 * history. It creates multiple reports and uses date range filters to validate
 * that only reports within the specified time window are returned.
 *
 * Since report creation timestamps are set automatically by the server, this
 * test:
 *
 * 1. Captures the timestamp before creating the first batch of reports
 * 2. Creates an initial set of reports
 * 3. Captures a boundary timestamp
 * 4. Creates a second batch of reports
 * 5. Uses date range filtering to retrieve only the first batch
 * 6. Validates that the second batch is excluded by the date filter
 *
 * This approach tests the date filtering mechanism while working within the API
 * constraints.
 */
export async function test_api_member_report_history_date_range_filtering(
  connection: api.IConnection,
) {
  // Step 1: Create moderator account for querying reports
  const moderatorData = {
    email: typia.random<string & tags.Format<"email">>(),
    password: "moderator123!",
    username: RandomGenerator.name(1),
    display_name: RandomGenerator.name(2),
    ip: "127.0.0.1",
    href: "https://example.com/moderator/join",
    referrer: "https://example.com",
  } satisfies IDiscussionBoardModerator.ICreate;

  const moderator = await api.functional.auth.moderator.join(connection, {
    body: moderatorData,
  });
  typia.assert(moderator);

  // Step 2: Create article category
  const categoryData = {
    name: "Economic Discussion",
    slug: "economic-discussion",
    description: "Category for economic topics",
    sort_order: 1,
  } satisfies IDiscussionBoardArticleCategory.ICreate;

  const category =
    await api.functional.discussionBoard.moderator.categories.create(
      connection,
      {
        body: categoryData,
      },
    );
  typia.assert(category);

  // Step 3: Create member account for submitting reports
  const memberData = {
    email: typia.random<string & tags.Format<"email">>(),
    password: "member123!",
    username: RandomGenerator.name(1),
    display_name: RandomGenerator.name(2),
    bio: RandomGenerator.paragraph({ sentences: 2 }),
    ip: "127.0.0.1",
    href: "https://example.com/member/join",
    referrer: "https://example.com",
  } satisfies IDiscussionBoardMember.ICreate;

  const member = await api.functional.auth.member.join(connection, {
    body: memberData,
  });
  typia.assert(member);

  // Step 4: Create articles for reporting
  const articles = await ArrayUtil.asyncRepeat(6, async (index) => {
    const articleData = {
      title: `Test Article ${index + 1} - ${RandomGenerator.name(3)}`,
      body: RandomGenerator.content({ paragraphs: 3 }),
      discussion_board_article_category_id: category.id,
      status: "published" as const,
    } satisfies IDiscussionBoardArticle.ICreate;

    const article = await api.functional.discussionBoard.member.articles.create(
      connection,
      {
        body: articleData,
      },
    );
    typia.assert(article);
    return article;
  });

  const reportCategories = [
    "Spam",
    "Offensive Content",
    "Misinformation",
    "Off-Topic",
    "Other",
  ] as const;

  // Step 5: Capture start time and create first batch of reports
  const batchStartTime = new Date();

  const firstBatchReports = await ArrayUtil.asyncRepeat(3, async (index) => {
    const reportData = {
      discussion_board_article_id: articles[index].id,
      report_category: RandomGenerator.pick(reportCategories),
      report_details: RandomGenerator.paragraph({ sentences: 3 }),
    } satisfies IDiscussionBoardContentReport.ICreate;

    const report =
      await api.functional.discussionBoard.member.articles.reports.create(
        connection,
        {
          articleId: articles[index].id,
          body: reportData,
        },
      );
    typia.assert(report);
    return report;
  });

  // Step 6: Add small delay and capture boundary time
  await new Promise((resolve) => setTimeout(resolve, 1000));
  const boundaryTime = new Date();

  // Step 7: Create second batch of reports after the boundary
  await new Promise((resolve) => setTimeout(resolve, 1000));

  const secondBatchReports = await ArrayUtil.asyncRepeat(3, async (index) => {
    const reportData = {
      discussion_board_article_id: articles[index + 3].id,
      report_category: RandomGenerator.pick(reportCategories),
      report_details: RandomGenerator.paragraph({ sentences: 3 }),
    } satisfies IDiscussionBoardContentReport.ICreate;

    const report =
      await api.functional.discussionBoard.member.articles.reports.create(
        connection,
        {
          articleId: articles[index + 3].id,
          body: reportData,
        },
      );
    typia.assert(report);
    return report;
  });

  // Step 8: Switch to moderator to query reports
  await api.functional.auth.moderator.login(connection, {
    body: {
      email: moderatorData.email,
      password: moderatorData.password,
      ip: "127.0.0.1",
      href: "https://example.com/moderator/login",
      referrer: "https://example.com",
    } satisfies IDiscussionBoardModerator.ILogin,
  });

  // Step 9: Query with date range filter to get only first batch
  const filteredReportsPage =
    await api.functional.discussionBoard.moderator.members.reports.index(
      connection,
      {
        memberId: member.id,
        body: {
          created_at_from: batchStartTime.toISOString(),
          created_at_to: boundaryTime.toISOString(),
          page: 1,
          limit: 20,
        } satisfies IDiscussionBoardContentReport.IRequest,
      },
    );
  typia.assert(filteredReportsPage);

  // Step 10: Validate all returned reports are within the date range
  const filterStartTime = batchStartTime.getTime();
  const filterEndTime = boundaryTime.getTime();

  for (const report of filteredReportsPage.data) {
    const reportCreatedAt = new Date(report.created_at).getTime();

    TestValidator.predicate(
      "report created_at should be >= filter start date",
      reportCreatedAt >= filterStartTime,
    );

    TestValidator.predicate(
      "report created_at should be <= filter end date",
      reportCreatedAt <= filterEndTime,
    );
  }

  // Step 11: Validate that filtered results contain first batch reports
  TestValidator.predicate(
    "filtered results should contain first batch reports",
    filteredReportsPage.data.length >= 3,
  );

  // Step 12: Query all reports to verify second batch exists but was excluded
  const allReportsPage =
    await api.functional.discussionBoard.moderator.members.reports.index(
      connection,
      {
        memberId: member.id,
        body: {
          page: 1,
          limit: 100,
        } satisfies IDiscussionBoardContentReport.IRequest,
      },
    );
  typia.assert(allReportsPage);

  // Step 13: Validate total reports exceed filtered reports
  TestValidator.predicate(
    "total reports should exceed filtered reports",
    allReportsPage.data.length > filteredReportsPage.data.length,
  );

  // Step 14: Verify second batch reports are excluded from filtered results
  const secondBatchIds = secondBatchReports.map((r) => r.id);
  const filteredIds = filteredReportsPage.data.map((r) => r.id);

  for (const secondBatchId of secondBatchIds) {
    TestValidator.predicate(
      "second batch report should not be in filtered results",
      !filteredIds.includes(secondBatchId),
    );
  }

  // Step 15: Validate pagination info
  TestValidator.predicate(
    "pagination current page should be 1",
    filteredReportsPage.pagination.current === 1,
  );

  TestValidator.predicate(
    "pagination records should match data length",
    filteredReportsPage.pagination.records >= filteredReportsPage.data.length,
  );
}

