}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IDiscussionBoardAccountAction } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardAccountAction";
import type { IDiscussionBoardMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardMember";
import type { IDiscussionBoardModerator } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardModerator";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IPageIDiscussionBoardAccountAction } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIDiscussionBoardAccountAction";

/**
 * Test retrieving paginated history of account actions performed by a
 * moderator.
 *
 * This test validates the accountability and transparency features that enable
 * tracking moderator enforcement patterns. It verifies that moderators can
 * review their complete enforcement activity including suspensions and bans
 * they have applied.
 *
 * Test workflow:
 *
 * 1. Authenticate as the target moderator
 * 2. Create multiple member accounts as enforcement targets
 * 3. Apply diverse account actions (suspensions with various durations, bans)
 * 4. Query the moderator's action history with pagination
 * 5. Validate all actions are present with correct details
 * 6. Verify pagination metadata accuracy
 */
export async function test_api_moderator_account_actions_history_retrieval(
  connection: api.IConnection,
) {
  // Step 1: Authenticate as the moderator whose action history will be reviewed
  const moderatorEmail = typia.random<string & tags.Format<"email">>();
  const moderatorData = {
    email: moderatorEmail,
    password: typia.random<string>(),
    username: RandomGenerator.alphaNumeric(10),
    display_name: RandomGenerator.name(),
    href: typia.random<string & tags.Format<"uri">>(),
    referrer: typia.random<string & tags.Format<"uri">>(),
  } satisfies IDiscussionBoardModerator.ICreate;

  const moderator: IDiscussionBoardModerator.IAuthorized =
    await api.functional.auth.moderator.join(connection, {
      body: moderatorData,
    });
  typia.assert(moderator);

  // Step 2: Create multiple member accounts to serve as enforcement targets
  const memberCount = 5;
  const members: IDiscussionBoardMember.IAuthorized[] =
    await ArrayUtil.asyncRepeat(memberCount, async (index) => {
      const memberEmail = typia.random<string & tags.Format<"email">>();
      const memberData = {
        email: memberEmail,
        password: typia.random<string & tags.Format<"password">>(),
        username: RandomGenerator.alphaNumeric(8) + index.toString(),
        display_name: RandomGenerator.name(),
        href: typia.random<string & tags.Format<"uri">>(),
        referrer: typia.random<string & tags.Format<"uri">>(),
      } satisfies IDiscussionBoardMember.ICreate;

      const member: IDiscussionBoardMember.IAuthorized =
        await api.functional.auth.member.join(connection, {
          body: memberData,
        });
      typia.assert(member);
      return member;
    });

  // Step 3: Apply diverse account actions with various types, durations, and reasons
  const actionTypes: Array<"suspension" | "ban"> = [
    "suspension",
    "suspension",
    "suspension",
    "suspension",
    "ban",
  ];
  const durations: Array<1 | 7 | 14 | 30 | null> = [1, 7, 14, 30, null];
  const reasons = [
    "Spam violation - first offense",
    "Harassment of other members - 7 day suspension",
    "Repeated policy violations - 14 day suspension",
    "Severe misconduct - 30 day suspension",
    "Permanent ban for illegal content posting",
  ];

  const createdActions: IDiscussionBoardAccountAction[] =
    await ArrayUtil.asyncRepeat(memberCount, async (index) => {
      const actionData = {
        discussion_board_member_id: members[index].id,
        action_type: actionTypes[index],
        reason: reasons[index],
        duration_days: durations[index],
      } satisfies IDiscussionBoardAccountAction.ICreate;

      const action: IDiscussionBoardAccountAction =
        await api.functional.discussionBoard.moderator.accountActions.create(
          connection,
          {
            body: actionData,
          },
        );
      typia.assert(action);
      return action;
    });

  // Step 4: Query the moderator's account action history with pagination
  const requestBody = {
    page: 1,
    limit: 10,
  } satisfies IDiscussionBoardAccountAction.IRequest;

  const actionHistory: IPageIDiscussionBoardAccountAction.ISummary =
    await api.functional.discussionBoard.moderator.moderators.accountActions.index(
      connection,
      {
        moderatorId: moderator.id,
        body: requestBody,
      },
    );
  typia.assert(actionHistory);

  // Step 5: Validate response contains all actions performed by this moderator
  TestValidator.equals(
    "action history should contain all created actions",
    actionHistory.data.length,
    memberCount,
  );

  // Step 6: Verify pagination metadata reflects correct total count
  TestValidator.equals(
    "pagination total records should match created actions count",
    actionHistory.pagination.records,
    memberCount,
  );

  TestValidator.equals(
    "pagination current page should be 1",
    actionHistory.pagination.current,
    1,
  );

  TestValidator.equals(
    "pagination limit should be 10",
    actionHistory.pagination.limit,
    10,
  );

  // Step 7: Validate each action's details match what was created
  createdActions.forEach((createdAction, index) => {
    const foundAction = actionHistory.data.find(
      (a) => a.id === createdAction.id,
    );
    typia.assertGuard(foundAction!);

    TestValidator.equals(
      `action ${index} type should match`,
      foundAction.action_type,
      createdAction.action_type,
    );

    TestValidator.equals(
      `action ${index} reason should match`,
      foundAction.reason,
      createdAction.reason,
    );

    TestValidator.equals(
      `action ${index} status should be active`,
      foundAction.status,
      "active",
    );

    TestValidator.equals(
      `action ${index} duration_days should match`,
      foundAction.duration_days,
      createdAction.duration_days,
    );
  });
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IDiscussionBoardAccountAction } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardAccountAction";
import type { IDiscussionBoardMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardMember";
import type { IDiscussionBoardModerator } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardModerator";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IPageIDiscussionBoardAccountAction } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIDiscussionBoardAccountAction";

/**
 * Test filtering moderator account action history by action type.
 *
 * This test validates that the action_type filter parameter correctly filters
 * moderator enforcement actions to retrieve only suspensions or only bans. It
 * verifies that moderators and administrators can analyze specific enforcement
 * patterns by filtering the action history.
 *
 * Test workflow:
 *
 * 1. Authenticate as a moderator who will apply enforcement actions
 * 2. Create multiple member accounts as targets for different action types
 * 3. Apply a mix of temporary suspensions and permanent bans to members
 * 4. Query action history with action_type filter set to 'suspension' and verify
 *    only suspension records are returned
 * 5. Query action history with action_type filter set to 'ban' and verify only ban
 *    records are returned
 * 6. Query action history without filter and verify all actions are returned
 *
 * This ensures the filtering capability enables moderators and administrators
 * to analyze specific enforcement patterns such as reviewing a moderator's use
 * of permanent bans versus temporary suspensions.
 */
export async function test_api_moderator_account_actions_filter_by_action_type(
  connection: api.IConnection,
) {
  // Step 1: Authenticate as moderator who will apply enforcement actions
  const moderator: IDiscussionBoardModerator.IAuthorized =
    await api.functional.auth.moderator.join(connection, {
      body: {
        email: typia.random<string & tags.Format<"email">>(),
        password: typia.random<string>(),
        username: typia.random<string>(),
        href: typia.random<string & tags.Format<"uri">>(),
        referrer: typia.random<string & tags.Format<"uri">>(),
      } satisfies IDiscussionBoardModerator.ICreate,
    });
  typia.assert(moderator);

  // Step 2: Create multiple member accounts as targets (4 members for 2 suspensions + 2 bans)
  const members: IDiscussionBoardMember.IAuthorized[] =
    await ArrayUtil.asyncRepeat(4, async () => {
      const member = await api.functional.auth.member.join(connection, {
        body: {
          email: typia.random<string & tags.Format<"email">>(),
          password: typia.random<string & tags.Format<"password">>(),
          username: typia.random<
            string & tags.MinLength<3> & tags.MaxLength<30>
          >(),
          href: typia.random<string & tags.Format<"uri">>(),
          referrer: typia.random<string & tags.Format<"uri">>(),
        } satisfies IDiscussionBoardMember.ICreate,
      });
      typia.assert(member);
      return member;
    });

  // Step 3: Apply temporary suspensions to first 2 members
  const suspensionDurations = [1, 7] as const;
  const suspensions: IDiscussionBoardAccountAction[] = await ArrayUtil.asyncMap(
    members.slice(0, 2),
    async (member, index) => {
      const suspension =
        await api.functional.discussionBoard.moderator.accountActions.create(
          connection,
          {
            body: {
              discussion_board_member_id: member.id,
              action_type: "suspension",
              reason: RandomGenerator.paragraph({
                sentences: 5,
                wordMin: 5,
                wordMax: 10,
              }),
              duration_days: suspensionDurations[index],
            } satisfies IDiscussionBoardAccountAction.ICreate,
          },
        );
      typia.assert(suspension);
      return suspension;
    },
  );

  // Step 4: Apply permanent bans to last 2 members
  const bans: IDiscussionBoardAccountAction[] = await ArrayUtil.asyncMap(
    members.slice(2, 4),
    async (member) => {
      const ban =
        await api.functional.discussionBoard.moderator.accountActions.create(
          connection,
          {
            body: {
              discussion_board_member_id: member.id,
              action_type: "ban",
              reason: RandomGenerator.paragraph({
                sentences: 5,
                wordMin: 5,
                wordMax: 10,
              }),
              duration_days: null,
            } satisfies IDiscussionBoardAccountAction.ICreate,
          },
        );
      typia.assert(ban);
      return ban;
    },
  );

  // Step 5: Query with action_type filter set to 'suspension'
  const suspensionResults: IPageIDiscussionBoardAccountAction.ISummary =
    await api.functional.discussionBoard.moderator.moderators.accountActions.index(
      connection,
      {
        moderatorId: moderator.id,
        body: {
          action_type: "suspension",
        } satisfies IDiscussionBoardAccountAction.IRequest,
      },
    );
  typia.assert(suspensionResults);

  // Verify only suspension records are returned
  TestValidator.predicate(
    "suspension filter should return at least 2 suspension records",
    suspensionResults.data.length >= 2,
  );

  for (const action of suspensionResults.data) {
    TestValidator.equals(
      "all returned actions should be suspensions",
      action.action_type,
      "suspension",
    );
  }

  // Step 6: Query with action_type filter set to 'ban'
  const banResults: IPageIDiscussionBoardAccountAction.ISummary =
    await api.functional.discussionBoard.moderator.moderators.accountActions.index(
      connection,
      {
        moderatorId: moderator.id,
        body: {
          action_type: "ban",
        } satisfies IDiscussionBoardAccountAction.IRequest,
      },
    );
  typia.assert(banResults);

  // Verify only ban records are returned
  TestValidator.predicate(
    "ban filter should return at least 2 ban records",
    banResults.data.length >= 2,
  );

  for (const action of banResults.data) {
    TestValidator.equals(
      "all returned actions should be bans",
      action.action_type,
      "ban",
    );
  }

  // Step 7: Query without filter to verify all actions are returned
  const allResults: IPageIDiscussionBoardAccountAction.ISummary =
    await api.functional.discussionBoard.moderator.moderators.accountActions.index(
      connection,
      {
        moderatorId: moderator.id,
        body: {} satisfies IDiscussionBoardAccountAction.IRequest,
      },
    );
  typia.assert(allResults);

  // Verify total count includes all created actions (2 suspensions + 2 bans = 4)
  TestValidator.predicate(
    "unfiltered query should return all actions",
    allResults.data.length >= 4,
  );

  // Verify we have both action types in unfiltered results
  const hasSuspensions = allResults.data.some(
    (action) => action.action_type === "suspension",
  );
  const hasBans = allResults.data.some(
    (action) => action.action_type === "ban",
  );

  TestValidator.predicate(
    "unfiltered results should contain suspension actions",
    hasSuspensions,
  );

  TestValidator.predicate(
    "unfiltered results should contain ban actions",
    hasBans,
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IDiscussionBoardAccountAction } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardAccountAction";
import type { IDiscussionBoardMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardMember";
import type { IDiscussionBoardModerator } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardModerator";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IPageIDiscussionBoardAccountAction } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIDiscussionBoardAccountAction";

/**
 * Test filtering moderator account action history by enforcement status to
 * retrieve active or reversed actions.
 *
 * This scenario validates the status filter parameter for reviewing action
 * lifecycle states.
 *
 * Process:
 *
 * 1. Authenticate as a moderator who will manage various enforcement states
 * 2. Create multiple member accounts as targets for different action states
 * 3. Apply several account actions with different characteristics:
 *
 *    - Create active suspensions that remain in effect
 *    - Create actions that will be reversed
 * 4. Reverse some actions to create reversed status records
 * 5. Query with status='active' to verify only currently enforced actions are
 *    returned
 * 6. Query with status='reversed' to retrieve manually lifted actions
 * 7. Query without status filter to retrieve all actions regardless of state
 */
export async function test_api_moderator_account_actions_filter_by_status(
  connection: api.IConnection,
) {
  // Step 1: Authenticate as moderator
  const moderatorEmail = typia.random<string & tags.Format<"email">>();
  const moderatorPassword = RandomGenerator.alphaNumeric(12);
  const moderatorUsername = RandomGenerator.alphaNumeric(10);

  const moderator = await api.functional.auth.moderator.join(connection, {
    body: {
      email: moderatorEmail,
      password: moderatorPassword,
      username: moderatorUsername,
      display_name: RandomGenerator.name(),
      href: typia.random<string & tags.Format<"uri">>(),
      referrer: typia.random<string & tags.Format<"uri">>(),
    } satisfies IDiscussionBoardModerator.ICreate,
  });
  typia.assert(moderator);

  // Step 2: Create multiple member accounts as targets
  const members = await ArrayUtil.asyncRepeat(5, async () => {
    const memberConnection: api.IConnection = { ...connection, headers: {} };
    const memberEmail = typia.random<string & tags.Format<"email">>();
    const memberPassword = RandomGenerator.alphaNumeric(12);
    const memberUsername = RandomGenerator.alphaNumeric(10);

    const member = await api.functional.auth.member.join(memberConnection, {
      body: {
        email: memberEmail,
        password: memberPassword,
        username: memberUsername,
        display_name: RandomGenerator.name(),
        href: typia.random<string & tags.Format<"uri">>(),
        referrer: typia.random<string & tags.Format<"uri">>(),
      } satisfies IDiscussionBoardMember.ICreate,
    });
    typia.assert(member);
    return member;
  });

  // Step 3: Apply various account actions
  // Create active suspensions (30 days - long duration)
  const activeSuspension1 =
    await api.functional.discussionBoard.moderator.accountActions.create(
      connection,
      {
        body: {
          discussion_board_member_id: members[0].id,
          action_type: "suspension",
          reason: "Active suspension test - policy violation",
          duration_days: 30,
        } satisfies IDiscussionBoardAccountAction.ICreate,
      },
    );
  typia.assert(activeSuspension1);

  const activeSuspension2 =
    await api.functional.discussionBoard.moderator.accountActions.create(
      connection,
      {
        body: {
          discussion_board_member_id: members[1].id,
          action_type: "suspension",
          reason: "Active suspension test - repeated violations",
          duration_days: 14,
        } satisfies IDiscussionBoardAccountAction.ICreate,
      },
    );
  typia.assert(activeSuspension2);

  // Create permanent ban (also active)
  const activeBan =
    await api.functional.discussionBoard.moderator.accountActions.create(
      connection,
      {
        body: {
          discussion_board_member_id: members[2].id,
          action_type: "ban",
          reason: "Permanent ban test - severe violation",
        } satisfies IDiscussionBoardAccountAction.ICreate,
      },
    );
  typia.assert(activeBan);

  // Create actions that will be reversed
  const toBeReversed1 =
    await api.functional.discussionBoard.moderator.accountActions.create(
      connection,
      {
        body: {
          discussion_board_member_id: members[3].id,
          action_type: "suspension",
          reason: "Suspension to be reversed - applied in error",
          duration_days: 7,
        } satisfies IDiscussionBoardAccountAction.ICreate,
      },
    );
  typia.assert(toBeReversed1);

  const toBeReversed2 =
    await api.functional.discussionBoard.moderator.accountActions.create(
      connection,
      {
        body: {
          discussion_board_member_id: members[4].id,
          action_type: "ban",
          reason: "Ban to be reversed - user appealed successfully",
        } satisfies IDiscussionBoardAccountAction.ICreate,
      },
    );
  typia.assert(toBeReversed2);

  // Step 4: Reverse some actions to create reversed status records
  const reversed1 =
    await api.functional.discussionBoard.moderator.accountActions.update(
      connection,
      {
        actionId: toBeReversed1.id,
        body: {
          status: "reversed",
          reversal_reason: "Applied in error - member did not violate policy",
        } satisfies IDiscussionBoardAccountAction.IUpdate,
      },
    );
  typia.assert(reversed1);
  TestValidator.equals("reversed action status", reversed1.status, "reversed");

  const reversed2 =
    await api.functional.discussionBoard.moderator.accountActions.update(
      connection,
      {
        actionId: toBeReversed2.id,
        body: {
          status: "reversed",
          reversal_reason: "User appeal successful - evidence provided",
        } satisfies IDiscussionBoardAccountAction.IUpdate,
      },
    );
  typia.assert(reversed2);
  TestValidator.equals("reversed ban status", reversed2.status, "reversed");

  // Step 5: Query with status='active' filter
  const activeResults =
    await api.functional.discussionBoard.moderator.moderators.accountActions.index(
      connection,
      {
        moderatorId: moderator.id,
        body: {
          status: "active",
          page: 1,
          limit: 100,
        } satisfies IDiscussionBoardAccountAction.IRequest,
      },
    );
  typia.assert(activeResults);

  // Verify only active actions are returned (3 active: 2 suspensions + 1 ban)
  TestValidator.equals("active filter count", activeResults.data.length, 3);
  TestValidator.predicate(
    "all results have active status",
    activeResults.data.every((action) => action.status === "active"),
  );

  // Step 6: Query with status='reversed' filter
  const reversedResults =
    await api.functional.discussionBoard.moderator.moderators.accountActions.index(
      connection,
      {
        moderatorId: moderator.id,
        body: {
          status: "reversed",
          page: 1,
          limit: 100,
        } satisfies IDiscussionBoardAccountAction.IRequest,
      },
    );
  typia.assert(reversedResults);

  // Verify only reversed actions are returned (2 reversed actions)
  TestValidator.equals("reversed filter count", reversedResults.data.length, 2);
  TestValidator.predicate(
    "all results have reversed status",
    reversedResults.data.every((action) => action.status === "reversed"),
  );

  // Step 7: Query without status filter to retrieve all actions
  const allResults =
    await api.functional.discussionBoard.moderator.moderators.accountActions.index(
      connection,
      {
        moderatorId: moderator.id,
        body: {
          page: 1,
          limit: 100,
        } satisfies IDiscussionBoardAccountAction.IRequest,
      },
    );
  typia.assert(allResults);

  // Verify all actions are returned (5 total: 3 active + 2 reversed)
  TestValidator.equals("all actions count", allResults.data.length, 5);

  // Verify the total includes both active and reversed actions
  const activeCount = allResults.data.filter(
    (a) => a.status === "active",
  ).length;
  const reversedCount = allResults.data.filter(
    (a) => a.status === "reversed",
  ).length;
  TestValidator.equals("active count in all results", activeCount, 3);
  TestValidator.equals("reversed count in all results", reversedCount, 2);
}

