import type { IDiscussionBoardAccountAction } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardAccountAction";
import type { IDiscussionBoardMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardMember";
import type { IDiscussionBoardModerator } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardModerator";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IPageIDiscussionBoardAccountAction } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIDiscussionBoardAccountAction";

/**
 * Test filtering moderator account action history by date range using
 * created_after and created_before parameters.
 *
 * This test validates temporal filtering for reviewing enforcement activity
 * within specific time periods. It creates account actions at different
 * timestamps and verifies that the date range filters correctly return only
 * actions within the specified time boundaries.
 *
 * Test workflow:
 *
 * 1. Create and authenticate as moderator
 * 2. Create member accounts as enforcement targets
 * 3. Create account actions at different timestamps
 * 4. Test created_after filter
 * 5. Test created_before filter
 * 6. Test combined date range filter (created_after + created_before)
 * 7. Validate that all returned actions fall within specified time ranges
 */
export async function test_api_moderator_account_actions_filter_by_date_range(
  connection: api.IConnection,
) {
  // Step 1: Create and authenticate moderator
  const moderator = await api.functional.auth.moderator.join(connection, {
    body: {
      email: typia.random<string & tags.Format<"email">>(),
      password: typia.random<string>(),
      username: typia.random<string>(),
      display_name: RandomGenerator.name(),
      href: typia.random<string & tags.Format<"uri">>(),
      referrer: typia.random<string & tags.Format<"uri">>(),
    } satisfies IDiscussionBoardModerator.ICreate,
  });
  typia.assert(moderator);

  // Step 2: Create member accounts as enforcement targets
  const memberCount = 5;
  const members = await ArrayUtil.asyncRepeat(memberCount, async () => {
    const unauthConn: api.IConnection = { ...connection, headers: {} };
    const member = await api.functional.auth.member.join(unauthConn, {
      body: {
        email: typia.random<string & tags.Format<"email">>(),
        password: typia.random<string & tags.Format<"password">>(),
        username: typia.random<
          string & tags.MinLength<3> & tags.MaxLength<30>
        >(),
        display_name: RandomGenerator.name(),
        href: typia.random<string & tags.Format<"uri">>(),
        referrer: typia.random<string & tags.Format<"uri">>(),
      } satisfies IDiscussionBoardMember.ICreate,
    });
    typia.assert(member);
    return member;
  });

  // Step 3: Create account actions at different timestamps
  const actionTypes = ["suspension", "ban"] as const;
  const allActions: IDiscussionBoardAccountAction[] = [];

  // Create first batch of actions
  for (let i = 0; i < 2; i++) {
    const actionType = RandomGenerator.pick(actionTypes);
    const action =
      await api.functional.discussionBoard.moderator.accountActions.create(
        connection,
        {
          body: {
            discussion_board_member_id: members[i].id,
            action_type: actionType,
            reason: RandomGenerator.paragraph({ sentences: 2 }),
            duration_days:
              actionType === "suspension"
                ? RandomGenerator.pick([1, 7, 14, 30] as const)
                : null,
          } satisfies IDiscussionBoardAccountAction.ICreate,
        },
      );
    typia.assert(action);
    allActions.push(action);
  }

  // Use the last action's timestamp as the midpoint reference
  const midTimestamp = allActions[allActions.length - 1].created_at;

  // Wait a moment to ensure timestamp difference
  await new Promise((resolve) => setTimeout(resolve, 100));

  // Create second batch of actions after the mid timestamp
  for (let i = 2; i < memberCount; i++) {
    const actionType = RandomGenerator.pick(actionTypes);
    const action =
      await api.functional.discussionBoard.moderator.accountActions.create(
        connection,
        {
          body: {
            discussion_board_member_id: members[i].id,
            action_type: actionType,
            reason: RandomGenerator.paragraph({ sentences: 2 }),
            duration_days:
              actionType === "suspension"
                ? RandomGenerator.pick([1, 7, 14, 30] as const)
                : null,
          } satisfies IDiscussionBoardAccountAction.ICreate,
        },
      );
    typia.assert(action);
    allActions.push(action);
  }

  // Step 4: Test created_after filter - should return only actions after midTimestamp
  const afterResult =
    await api.functional.discussionBoard.moderator.moderators.accountActions.index(
      connection,
      {
        moderatorId: moderator.id,
        body: {
          created_after: midTimestamp,
          page: 1,
          limit: 10,
        } satisfies IDiscussionBoardAccountAction.IRequest,
      },
    );
  typia.assert(afterResult);

  // Validate that result is a subset of total actions
  TestValidator.predicate(
    "after filter should return subset of total actions",
    afterResult.data.length <= allActions.length,
  );

  // Validate that all returned actions were created after the midTimestamp
  for (const action of afterResult.data) {
    const actionDate = new Date(action.created_at);
    const midDate = new Date(midTimestamp);
    TestValidator.predicate(
      "action created_at should be after or equal to created_after filter",
      actionDate >= midDate,
    );
  }

  // Step 5: Test created_before filter - should return only actions before a cutoff
  const beforeTimestamp = new Date().toISOString();
  const beforeResult =
    await api.functional.discussionBoard.moderator.moderators.accountActions.index(
      connection,
      {
        moderatorId: moderator.id,
        body: {
          created_before: beforeTimestamp,
          page: 1,
          limit: 10,
        } satisfies IDiscussionBoardAccountAction.IRequest,
      },
    );
  typia.assert(beforeResult);

  // Validate that all returned actions were created before the beforeTimestamp
  for (const action of beforeResult.data) {
    const actionDate = new Date(action.created_at);
    const beforeDate = new Date(beforeTimestamp);
    TestValidator.predicate(
      "action created_at should be before or equal to created_before filter",
      actionDate <= beforeDate,
    );
  }

  // Step 6: Test combined date range filter (created_after + created_before)
  const rangeResult =
    await api.functional.discussionBoard.moderator.moderators.accountActions.index(
      connection,
      {
        moderatorId: moderator.id,
        body: {
          created_after: midTimestamp,
          created_before: beforeTimestamp,
          page: 1,
          limit: 10,
        } satisfies IDiscussionBoardAccountAction.IRequest,
      },
    );
  typia.assert(rangeResult);

  // Validate that all returned actions fall within the date range
  for (const action of rangeResult.data) {
    const actionDate = new Date(action.created_at);
    const midDate = new Date(midTimestamp);
    const beforeDate = new Date(beforeTimestamp);

    TestValidator.predicate(
      "action created_at should be within date range (after created_after)",
      actionDate >= midDate,
    );

    TestValidator.predicate(
      "action created_at should be within date range (before created_before)",
      actionDate <= beforeDate,
    );
  }

  // Step 7: Validate pagination metadata
  TestValidator.predicate(
    "pagination should have valid structure",
    rangeResult.pagination.current >= 1 &&
      rangeResult.pagination.limit > 0 &&
      rangeResult.pagination.records >= 0,
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IDiscussionBoardAccountAction } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardAccountAction";
import type { IDiscussionBoardModerator } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardModerator";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IPageIDiscussionBoardAccountAction } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIDiscussionBoardAccountAction";

/**
 * Test retrieving account action history for a moderator with no enforcement
 * actions.
 *
 * This test validates the edge case of a newly created moderator who has never
 * performed any account-level moderation actions (suspensions or bans). The
 * test creates a fresh moderator account, authenticates, and immediately
 * queries their enforcement history without creating any actions.
 *
 * Expected behavior:
 *
 * 1. Create and authenticate a new moderator
 * 2. Query their account action history
 * 3. Receive empty data array with zero total records
 * 4. Pagination metadata shows 0 records and 0 pages
 *
 * This ensures the endpoint handles empty result sets gracefully for moderators
 * who focus on other moderation activities or are newly onboarded.
 */
export async function test_api_moderator_account_actions_empty_history(
  connection: api.IConnection,
) {
  // Create a new moderator account who has never performed any enforcement actions
  const moderatorData = {
    email: typia.random<string & tags.Format<"email">>(),
    password: "SecureModPass123!",
    username: RandomGenerator.alphaNumeric(12),
    display_name: RandomGenerator.name(2),
    href: typia.random<string & tags.Format<"uri">>(),
    referrer: typia.random<string & tags.Format<"uri">>(),
  } satisfies IDiscussionBoardModerator.ICreate;

  const moderator: IDiscussionBoardModerator.IAuthorized =
    await api.functional.auth.moderator.join(connection, {
      body: moderatorData,
    });
  typia.assert(moderator);

  // Verify moderator was created successfully
  TestValidator.predicate(
    "moderator email matches",
    moderator.email === moderatorData.email,
  );
  TestValidator.predicate(
    "moderator username matches",
    moderator.username === moderatorData.username,
  );

  // Query the account action history for this brand new moderator (should be empty)
  const emptyHistoryRequest = {
    page: 1,
    limit: 20,
  } satisfies IDiscussionBoardAccountAction.IRequest;

  const accountActionsPage: IPageIDiscussionBoardAccountAction.ISummary =
    await api.functional.discussionBoard.moderator.moderators.accountActions.index(
      connection,
      {
        moderatorId: moderator.id,
        body: emptyHistoryRequest,
      },
    );
  typia.assert(accountActionsPage);

  // Validate that the response is an empty result set with proper pagination
  TestValidator.equals(
    "data array should be empty",
    accountActionsPage.data,
    [],
  );
  TestValidator.equals(
    "total records should be zero",
    accountActionsPage.pagination.records satisfies number as number,
    0,
  );
  TestValidator.equals(
    "total pages should be zero",
    accountActionsPage.pagination.pages satisfies number as number,
    0,
  );
  TestValidator.equals(
    "current page should be 1",
    accountActionsPage.pagination.current satisfies number as number,
    1,
  );
  TestValidator.equals(
    "page limit should match request",
    accountActionsPage.pagination.limit satisfies number as number,
    20,
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IDiscussionBoardAccountAction } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardAccountAction";
import type { IDiscussionBoardMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardMember";
import type { IDiscussionBoardModerator } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardModerator";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IPageIDiscussionBoardAccountAction } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIDiscussionBoardAccountAction";

/**
 * Test complex filtering scenarios combining multiple filter parameters to
 * create precise queries of moderator enforcement history.
 *
 * This test validates that multiple filters work correctly together for
 * advanced analysis workflows, enabling sophisticated enforcement pattern
 * analysis and accountability reviews.
 *
 * Workflow:
 *
 * 1. Authenticate as moderator
 * 2. Create multiple member accounts as targets
 * 3. Create diverse account actions with different types, statuses, and timestamps
 * 4. Reverse some actions to create status variety
 * 5. Query with combined filters and validate results match all criteria
 */
export async function test_api_moderator_account_actions_combined_filters(
  connection: api.IConnection,
) {
  // Step 1: Authenticate as moderator
  const moderator = await api.functional.auth.moderator.join(connection, {
    body: {
      email: typia.random<string & tags.Format<"email">>(),
      password: typia.random<string>(),
      username: typia.random<string>(),
      href: typia.random<string & tags.Format<"uri">>(),
      referrer: typia.random<string & tags.Format<"uri">>(),
    } satisfies IDiscussionBoardModerator.ICreate,
  });
  typia.assert(moderator);

  // Step 2: Create multiple member accounts as targets
  const members = await ArrayUtil.asyncRepeat(5, async () => {
    const member = await api.functional.auth.member.join(connection, {
      body: {
        email: typia.random<string & tags.Format<"email">>(),
        password: typia.random<string & tags.Format<"password">>(),
        username: typia.random<
          string & tags.MinLength<3> & tags.MaxLength<30>
        >(),
        href: typia.random<string & tags.Format<"uri">>(),
        referrer: typia.random<string & tags.Format<"uri">>(),
      } satisfies IDiscussionBoardMember.ICreate,
    });
    typia.assert(member);
    return member;
  });

  // Step 3: Create diverse account actions with different combinations
  const now = new Date();
  const oneDayAgo = new Date(now.getTime() - 24 * 60 * 60 * 1000);
  const twoDaysAgo = new Date(now.getTime() - 2 * 24 * 60 * 60 * 1000);

  // Create active suspensions
  const activeSuspension1 =
    await api.functional.discussionBoard.moderator.accountActions.create(
      connection,
      {
        body: {
          discussion_board_member_id: members[0].id,
          action_type: "suspension",
          reason: "Spam violation - active suspension 1",
          duration_days: 7,
        } satisfies IDiscussionBoardAccountAction.ICreate,
      },
    );
  typia.assert(activeSuspension1);

  const activeSuspension2 =
    await api.functional.discussionBoard.moderator.accountActions.create(
      connection,
      {
        body: {
          discussion_board_member_id: members[1].id,
          action_type: "suspension",
          reason: "Harassment - active suspension 2",
          duration_days: 14,
        } satisfies IDiscussionBoardAccountAction.ICreate,
      },
    );
  typia.assert(activeSuspension2);

  // Create active ban
  const activeBan =
    await api.functional.discussionBoard.moderator.accountActions.create(
      connection,
      {
        body: {
          discussion_board_member_id: members[2].id,
          action_type: "ban",
          reason: "Severe policy violation - permanent ban",
        } satisfies IDiscussionBoardAccountAction.ICreate,
      },
    );
  typia.assert(activeBan);

  // Create another suspension and then reverse it
  const suspensionToReverse =
    await api.functional.discussionBoard.moderator.accountActions.create(
      connection,
      {
        body: {
          discussion_board_member_id: members[3].id,
          action_type: "suspension",
          reason: "Initial suspension - will be reversed",
          duration_days: 30,
        } satisfies IDiscussionBoardAccountAction.ICreate,
      },
    );
  typia.assert(suspensionToReverse);

  // Step 4: Reverse the suspension to create status variety
  const reversedAction =
    await api.functional.discussionBoard.moderator.accountActions.update(
      connection,
      {
        actionId: suspensionToReverse.id,
        body: {
          status: "reversed",
          reversal_reason: "Applied in error - user successfully appealed",
        } satisfies IDiscussionBoardAccountAction.IUpdate,
      },
    );
  typia.assert(reversedAction);

  // Create another ban
  const recentBan =
    await api.functional.discussionBoard.moderator.accountActions.create(
      connection,
      {
        body: {
          discussion_board_member_id: members[4].id,
          action_type: "ban",
          reason: "Repeated violations after warnings",
        } satisfies IDiscussionBoardAccountAction.ICreate,
      },
    );
  typia.assert(recentBan);

  // Step 5: Query with combined filters and validate results

  // Test 1: Filter by action_type 'suspension' AND status 'active'
  const activeSuspensionsResult =
    await api.functional.discussionBoard.moderator.moderators.accountActions.index(
      connection,
      {
        moderatorId: moderator.id,
        body: {
          action_type: "suspension",
          status: "active",
        } satisfies IDiscussionBoardAccountAction.IRequest,
      },
    );
  typia.assert(activeSuspensionsResult);

  TestValidator.predicate(
    "active suspensions filter returns results",
    activeSuspensionsResult.data.length > 0,
  );

  activeSuspensionsResult.data.forEach((action) => {
    TestValidator.equals(
      "action is suspension type",
      action.action_type,
      "suspension",
    );
    TestValidator.equals("action is active status", action.status, "active");
  });

  // Test 2: Filter by action_type 'ban' AND created_after
  const recentBansResult =
    await api.functional.discussionBoard.moderator.moderators.accountActions.index(
      connection,
      {
        moderatorId: moderator.id,
        body: {
          action_type: "ban",
          created_after: twoDaysAgo.toISOString(),
        } satisfies IDiscussionBoardAccountAction.IRequest,
      },
    );
  typia.assert(recentBansResult);

  TestValidator.predicate(
    "recent bans filter returns results",
    recentBansResult.data.length > 0,
  );

  recentBansResult.data.forEach((action) => {
    TestValidator.equals("action is ban type", action.action_type, "ban");
    const createdAt = new Date(action.created_at);
    TestValidator.predicate(
      "action created after filter date",
      createdAt >= twoDaysAgo,
    );
  });

  // Test 3: Filter by status 'reversed' AND date range
  const reversedActionsResult =
    await api.functional.discussionBoard.moderator.moderators.accountActions.index(
      connection,
      {
        moderatorId: moderator.id,
        body: {
          status: "reversed",
          created_after: twoDaysAgo.toISOString(),
          created_before: new Date(
            now.getTime() + 60 * 60 * 1000,
          ).toISOString(),
        } satisfies IDiscussionBoardAccountAction.IRequest,
      },
    );
  typia.assert(reversedActionsResult);

  TestValidator.predicate(
    "reversed actions filter returns results",
    reversedActionsResult.data.length > 0,
  );

  reversedActionsResult.data.forEach((action) => {
    TestValidator.equals(
      "action is reversed status",
      action.status,
      "reversed",
    );
    const createdAt = new Date(action.created_at);
    TestValidator.predicate(
      "action within date range",
      createdAt >= twoDaysAgo &&
        createdAt <= new Date(now.getTime() + 60 * 60 * 1000),
    );
  });

  // Test 4: Verify combined filters exclude non-matching records
  const allActionsResult =
    await api.functional.discussionBoard.moderator.moderators.accountActions.index(
      connection,
      {
        moderatorId: moderator.id,
        body: {} satisfies IDiscussionBoardAccountAction.IRequest,
      },
    );
  typia.assert(allActionsResult);

  TestValidator.predicate(
    "total actions count is greater than filtered results",
    allActionsResult.data.length >= activeSuspensionsResult.data.length,
  );

  TestValidator.predicate(
    "filtered results are subset of total",
    activeSuspensionsResult.data.length < allActionsResult.data.length,
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IDiscussionBoardArticle } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardArticle";
import type { IDiscussionBoardArticleCategory } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardArticleCategory";
import type { IDiscussionBoardContentReport } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardContentReport";
import type { IDiscussionBoardMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardMember";
import type { IDiscussionBoardModerator } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardModerator";

export async function test_api_content_report_deletion_by_moderator(
  connection: api.IConnection,
) {
  // Step 1: Create member account for article authorship and content report submission
  const memberEmail = typia.random<string & tags.Format<"email">>();
  const memberPassword = typia.random<string & tags.Format<"password">>();
  const memberUsername = typia.random<
    string & tags.MinLength<3> & tags.MaxLength<30>
  >();

  const member = await api.functional.auth.member.join(connection, {
    body: {
      email: memberEmail,
      password: memberPassword,
      username: memberUsername,
      display_name: RandomGenerator.name(),
      bio: RandomGenerator.paragraph({ sentences: 2 }),
      href: typia.random<string & tags.Format<"uri">>(),
      referrer: typia.random<string & tags.Format<"uri">>(),
    } satisfies IDiscussionBoardMember.ICreate,
  });
  typia.assert(member);

  // Step 2: Create moderator account with privileges to manage and delete content reports
  const moderatorEmail = typia.random<string & tags.Format<"email">>();
  const moderatorPassword = typia.random<string & tags.Format<"password">>();
  const moderatorUsername = typia.random<
    string & tags.MinLength<3> & tags.MaxLength<30>
  >();

  const moderator = await api.functional.auth.moderator.join(connection, {
    body: {
      email: moderatorEmail,
      password: moderatorPassword,
      username: moderatorUsername,
      display_name: RandomGenerator.name(),
      href: typia.random<string & tags.Format<"uri">>(),
      referrer: typia.random<string & tags.Format<"uri">>(),
    } satisfies IDiscussionBoardModerator.ICreate,
  });
  typia.assert(moderator);

  // Step 3: Switch to moderator context and create article category
  await api.functional.auth.moderator.login(connection, {
    body: {
      email: moderatorEmail,
      password: moderatorPassword,
      href: typia.random<string & tags.Format<"uri">>(),
      referrer: typia.random<string & tags.Format<"uri">>(),
    } satisfies IDiscussionBoardModerator.ILogin,
  });

  const categoryName = RandomGenerator.name(2);
  const categorySlug = categoryName.toLowerCase().replace(/\s+/g, "-");

  const category =
    await api.functional.discussionBoard.moderator.categories.create(
      connection,
      {
        body: {
          name: categoryName,
          slug: categorySlug,
          description: RandomGenerator.paragraph({ sentences: 3 }),
          sort_order: typia.random<
            number & tags.Type<"int32"> & tags.Minimum<0>
          >(),
        } satisfies IDiscussionBoardArticleCategory.ICreate,
      },
    );
  typia.assert(category);

  // Step 4: Switch to member context and create article
  await api.functional.auth.member.login(connection, {
    body: {
      email: memberEmail,
      password: memberPassword,
      href: typia.random<string & tags.Format<"uri">>(),
      referrer: typia.random<string & tags.Format<"uri">>(),
    } satisfies IDiscussionBoardMember.ILogin,
  });

  const articleTitle = RandomGenerator.paragraph({
    sentences: 1,
    wordMin: 5,
    wordMax: 10,
  });
  const articleBody = RandomGenerator.content({
    paragraphs: 3,
    sentenceMin: 10,
    sentenceMax: 20,
  });

  const article = await api.functional.discussionBoard.member.articles.create(
    connection,
    {
      body: {
        title: articleTitle,
        body: articleBody,
        discussion_board_article_category_id: category.id,
        status: "published" as const,
      } satisfies IDiscussionBoardArticle.ICreate,
    },
  );
  typia.assert(article);

  // Step 5: Member submits content report against the article
  const reportCategories = [
    "Spam",
    "Offensive Content",
    "Misinformation",
    "Off-Topic",
    "Other",
  ] as const;
  const reportCategory = RandomGenerator.pick(reportCategories);

  const contentReport =
    await api.functional.discussionBoard.member.contentReports.create(
      connection,
      {
        body: {
          discussion_board_article_id: article.id,
          report_category: reportCategory,
          report_details: RandomGenerator.paragraph({ sentences: 5 }),
        } satisfies IDiscussionBoardContentReport.ICreate,
      },
    );
  typia.assert(contentReport);

  // Step 6: Switch to moderator context
  await api.functional.auth.moderator.login(connection, {
    body: {
      email: moderatorEmail,
      password: moderatorPassword,
      href: typia.random<string & tags.Format<"uri">>(),
      referrer: typia.random<string & tags.Format<"uri">>(),
    } satisfies IDiscussionBoardModerator.ILogin,
  });

  // Step 7: Delete the content report permanently from the database
  await api.functional.discussionBoard.moderator.contentReports.erase(
    connection,
    {
      reportId: contentReport.id,
    },
  );

  // Step 8: Verify deletion is successful (void return means operation completed)
  // The report has been permanently removed from the moderation system
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IDiscussionBoardArticle } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardArticle";
import type { IDiscussionBoardArticleCategory } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardArticleCategory";
