  const originalTitle = RandomGenerator.paragraph({
    sentences: 1,
    wordMin: 5,
    wordMax: 10,
  });
  const originalBody = RandomGenerator.content({
    paragraphs: 3,
    sentenceMin: 10,
    sentenceMax: 15,
  });

  const createdArticle =
    await api.functional.discussionBoard.member.articles.create(connection, {
      body: {
        title: originalTitle,
        body: originalBody,
        discussion_board_article_category_id: category.id,
        status: "published",
      } satisfies IDiscussionBoardArticle.ICreate,
    });
  typia.assert(createdArticle);

  // Step 5: Retrieve article and verify is_edited is false for newly published content
  const initialArticle = await api.functional.discussionBoard.articles.at(
    connection,
    {
      articleId: createdArticle.id,
    },
  );
  typia.assert(initialArticle);

  TestValidator.equals(
    "article ID matches",
    initialArticle.id,
    createdArticle.id,
  );
  TestValidator.equals(
    "is_edited should be false for new article",
    initialArticle.is_edited,
    false,
  );

  // Store original updated_at timestamp
  const originalUpdatedAt = initialArticle.updated_at;

  // Step 6: Update the article content to trigger is_edited flag
  const updatedTitle = RandomGenerator.paragraph({
    sentences: 1,
    wordMin: 5,
    wordMax: 10,
  });
  const updatedBody = RandomGenerator.content({
    paragraphs: 4,
    sentenceMin: 12,
    sentenceMax: 20,
  });

  const updatedArticle =
    await api.functional.discussionBoard.member.articles.update(connection, {
      articleId: createdArticle.id,
      body: {
        title: updatedTitle,
        body: updatedBody,
      } satisfies IDiscussionBoardArticle.IUpdate,
    });
  typia.assert(updatedArticle);

  // Step 7: Validate is_edited flag is now true after update
  TestValidator.equals(
    "is_edited should be true after update",
    updatedArticle.is_edited,
    true,
  );

  // Step 8: Verify updated_at timestamp changed
  TestValidator.notEquals(
    "updated_at should change after edit",
    updatedArticle.updated_at,
    originalUpdatedAt,
  );

  // Step 9: Retrieve the article again to confirm is_edited remains true
  const retrievedAgain = await api.functional.discussionBoard.articles.at(
    connection,
    {
      articleId: createdArticle.id,
    },
  );
  typia.assert(retrievedAgain);

  TestValidator.equals(
    "is_edited remains true on subsequent retrieval",
    retrievedAgain.is_edited,
    true,
  );
  TestValidator.equals(
    "updated content title matches",
    retrievedAgain.title,
    updatedTitle,
  );
  TestValidator.equals(
    "updated content body matches",
    retrievedAgain.body,
    updatedBody,
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IDiscussionBoardArticle } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardArticle";
import type { IDiscussionBoardArticleCategory } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardArticleCategory";
import type { IDiscussionBoardMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardMember";
import type { IDiscussionBoardModerator } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardModerator";

/**
 * Test that all article metadata fields are correctly returned with accurate
 * values and proper formatting.
 *
 * This test validates the complete metadata structure returned by the article
 * retrieval endpoint, ensuring all required fields are present, properly typed,
 * and correctly formatted according to the API specification. It verifies
 * nested objects (author, category), timestamp formats, UUID formats, string
 * length constraints, and data integrity.
 *
 * Test Flow:
 *
 * 1. Create moderator account for category management
 * 2. Create member account with complete profile (including display_name)
 * 3. Create article category with full metadata
 * 4. Create article with rich content ensuring excerpt generation
 * 5. Retrieve the created article
 * 6. Validate all required fields and their types
 * 7. Validate format constraints (UUIDs, ISO dates, string lengths)
 * 8. Validate nested object structures (author, category)
 * 9. Verify data integrity and completeness
 */
export async function test_api_article_retrieval_complete_metadata(
  connection: api.IConnection,
) {
  // Step 1: Create moderator account to manage categories
  const moderatorEmail = typia.random<string & tags.Format<"email">>();
  const moderatorPassword = typia.random<string>();

  const moderator = await api.functional.auth.moderator.join(connection, {
    body: {
      email: moderatorEmail,
      password: moderatorPassword,
      username: typia.random<string>(),
      display_name: RandomGenerator.name(),
      href: typia.random<string & tags.Format<"uri">>(),
      referrer: typia.random<string & tags.Format<"uri">>(),
    } satisfies IDiscussionBoardModerator.ICreate,
  });
  typia.assert(moderator);

  // Step 2: Create member account with display_name for author metadata
  const memberEmail = typia.random<string & tags.Format<"email">>();
  const memberPassword = typia.random<string>();

  const member = await api.functional.auth.member.join(connection, {
    body: {
      email: memberEmail,
      password: memberPassword,
      username: typia.random<string & tags.MinLength<3> & tags.MaxLength<30>>(),
      display_name: RandomGenerator.name(),
      bio: RandomGenerator.paragraph({ sentences: 3, wordMin: 5, wordMax: 10 }),
      href: typia.random<string & tags.Format<"uri">>(),
      referrer: typia.random<string & tags.Format<"uri">>(),
    } satisfies IDiscussionBoardMember.ICreate,
  });
  typia.assert(member);

  // Step 3: Switch to moderator to create category
  await api.functional.auth.moderator.login(connection, {
    body: {
      email: moderatorEmail,
      password: moderatorPassword,
      href: typia.random<string & tags.Format<"uri">>(),
      referrer: typia.random<string & tags.Format<"uri">>(),
    } satisfies IDiscussionBoardModerator.ILogin,
  });

  // Create category with complete description
  const categoryName = RandomGenerator.name(2);
  const categorySlug = categoryName.toLowerCase().replace(/\s+/g, "-");

  const category =
    await api.functional.discussionBoard.moderator.categories.create(
      connection,
      {
        body: {
          name: categoryName,
          slug: categorySlug,
          description: RandomGenerator.paragraph({
            sentences: 5,
            wordMin: 4,
            wordMax: 8,
          }),
          sort_order: typia.random<
            number & tags.Type<"int32"> & tags.Minimum<0>
          >(),
        } satisfies IDiscussionBoardArticleCategory.ICreate,
      },
    );
  typia.assert(category);

  // Step 4: Switch to member to create article
  await api.functional.auth.member.login(connection, {
    body: {
      email: memberEmail,
      password: memberPassword,
      href: typia.random<string & tags.Format<"uri">>(),
      referrer: typia.random<string & tags.Format<"uri">>(),
    } satisfies IDiscussionBoardMember.ILogin,
  });

  // Create article with rich content (minimum 50 chars for excerpt generation)
  const articleTitle = RandomGenerator.paragraph({
    sentences: 3,
    wordMin: 3,
    wordMax: 7,
  });
  const articleBody = RandomGenerator.content({
    paragraphs: 3,
    sentenceMin: 10,
    sentenceMax: 20,
    wordMin: 4,
    wordMax: 8,
  });

  const createdArticle =
    await api.functional.discussionBoard.member.articles.create(connection, {
      body: {
        title: articleTitle,
        body: articleBody,
        discussion_board_article_category_id: category.id,
        status: "published",
      } satisfies IDiscussionBoardArticle.ICreate,
    });
  typia.assert(createdArticle);

  // Step 5: Retrieve the article
  const retrievedArticle = await api.functional.discussionBoard.articles.at(
    connection,
    {
      articleId: createdArticle.id,
    },
  );
  typia.assert(retrievedArticle);

  // Step 6: Validate string length constraints
  TestValidator.predicate(
    "title length is 5-200 chars",
    retrievedArticle.title.length >= 5 && retrievedArticle.title.length <= 200,
  );
  TestValidator.predicate(
    "body length is 50-50000 chars",
    retrievedArticle.body.length >= 50 && retrievedArticle.body.length <= 50000,
  );

  // Step 7: Validate title matches created title
  TestValidator.equals(
    "title matches created article",
    retrievedArticle.title,
    articleTitle,
  );

  // Step 8: Validate body matches created body
  TestValidator.equals(
    "body matches created article",
    retrievedArticle.body,
    articleBody,
  );

  // Step 9: Validate slug is URL-friendly
  TestValidator.predicate(
    "slug is URL-friendly",
    /^[a-z0-9-]+$/.test(retrievedArticle.slug),
  );

  // Step 10: Validate status equals 'published'
  TestValidator.equals(
    "status is published",
    retrievedArticle.status,
    "published",
  );

  // Step 11: Validate view_count is non-negative integer
  TestValidator.predicate(
    "view_count is non-negative",
    retrievedArticle.view_count >= 0,
  );
  TestValidator.predicate(
    "view_count is integer",
    Number.isInteger(retrievedArticle.view_count),
  );

  // Step 12: Validate is_edited is false for new article
  TestValidator.equals(
    "is_edited is false for new article",
    retrievedArticle.is_edited,
    false,
  );

  // Step 13: Validate deleted_at is null for active article
  TestValidator.equals(
    "deleted_at is null for active article",
    retrievedArticle.deleted_at,
    null,
  );

  // Step 14: Validate author metadata
  TestValidator.equals(
    "author id matches member",
    retrievedArticle.author.id,
    member.id,
  );
  TestValidator.equals(
    "author username matches member",
    retrievedArticle.author.username,
    member.username,
  );

  if (member.display_name !== null && member.display_name !== undefined) {
    TestValidator.equals(
      "author display_name matches member",
      retrievedArticle.author.display_name,
      member.display_name,
    );
  }

  // Step 15: Validate category metadata
  TestValidator.equals(
    "category id matches created category",
    retrievedArticle.category.id,
    category.id,
  );
  TestValidator.equals(
    "category name matches created category",
    retrievedArticle.category.name,
    categoryName,
  );
  TestValidator.equals(
    "category slug matches created category",
    retrievedArticle.category.slug,
    categorySlug,
  );

  // Step 16: Verify excerpt exists or is null (auto-generated from body)
  if (
    retrievedArticle.excerpt !== null &&
    retrievedArticle.excerpt !== undefined
  ) {
    TestValidator.predicate(
      "excerpt is string when present",
      typeof retrievedArticle.excerpt === "string",
    );
    TestValidator.predicate(
      "excerpt length is reasonable",
      retrievedArticle.excerpt.length <= 200,
    );
  }

  // Step 17: Verify all data integrity
  TestValidator.equals(
    "article id matches created article",
    retrievedArticle.id,
    createdArticle.id,
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IDiscussionBoardArticle } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardArticle";
import type { IDiscussionBoardArticleCategory } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardArticleCategory";
import type { IDiscussionBoardMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardMember";
import type { IDiscussionBoardModerator } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardModerator";

/**
 * Test that article category information is correctly embedded in article
 * retrieval responses.
 *
 * This test validates that when retrieving an article, the category information
 * is complete and accurate, enabling proper topic organization and content
 * discovery. The test creates multiple categories across different topic areas
 * (Economic, Political, General) and verifies that articles maintain correct
 * category associations throughout their lifecycle.
 *
 * Process:
 *
 * 1. Create moderator account for category management
 * 2. Create multiple categories with different topics (Economic, Political,
 *    General)
 * 3. Create member account for article authoring
 * 4. Create articles assigned to different categories
 * 5. Retrieve each article and validate comprehensive category information
 * 6. Verify category.id, name, slug, description, sort_order, and timestamps
 * 7. Confirm articles maintain single category assignment
 * 8. Test category consistency across article lifecycle
 */
export async function test_api_article_retrieval_category_classification(
  connection: api.IConnection,
) {
  // Step 1: Create moderator account
  const moderator = await api.functional.auth.moderator.join(connection, {
    body: {
      email: typia.random<string & tags.Format<"email">>(),
      password: RandomGenerator.alphaNumeric(12),
      username: typia.random<string & tags.MinLength<3> & tags.MaxLength<30>>(),
      display_name: RandomGenerator.name(),
      href: typia.random<string & tags.Format<"uri">>(),
      referrer: typia.random<string & tags.Format<"uri">>(),
    } satisfies IDiscussionBoardModerator.ICreate,
  });
  typia.assert(moderator);

  // Step 2: Create multiple categories with different topics
  const categoryTopics = [
    {
      name: "Economic Discussion",
      slug: "economic-discussion",
      description: "Topics related to economics, markets, and fiscal policy",
      sortOrder: 1,
    },
    {
      name: "Political Discussion",
      slug: "political-discussion",
      description: "Topics related to politics, governance, and elections",
      sortOrder: 2,
    },
    {
      name: "General Discussion",
      slug: "general-discussion",
      description: "General topics and miscellaneous discussions",
      sortOrder: 3,
    },
  ];

  const categories = await ArrayUtil.asyncMap(categoryTopics, async (topic) => {
    const category =
      await api.functional.discussionBoard.moderator.categories.create(
        connection,
        {
          body: {
            name: topic.name,
            slug: topic.slug,
            description: topic.description,
            sort_order: topic.sortOrder,
          } satisfies IDiscussionBoardArticleCategory.ICreate,
        },
      );
    typia.assert(category);
    return category;
  });

  // Step 3: Switch to member authentication
  const member = await api.functional.auth.member.join(connection, {
    body: {
      email: typia.random<string & tags.Format<"email">>(),
      password: RandomGenerator.alphaNumeric(12),
      username: typia.random<string & tags.MinLength<3> & tags.MaxLength<30>>(),
      display_name: RandomGenerator.name(),
      href: typia.random<string & tags.Format<"uri">>(),
      referrer: typia.random<string & tags.Format<"uri">>(),
    } satisfies IDiscussionBoardMember.ICreate,
  });
  typia.assert(member);

  // Step 4: Create articles in different categories
  const articles = await ArrayUtil.asyncMap(categories, async (category) => {
    const article = await api.functional.discussionBoard.member.articles.create(
      connection,
      {
        body: {
          title: RandomGenerator.paragraph({ sentences: 3 }),
          body: RandomGenerator.content({ paragraphs: 3 }),
          discussion_board_article_category_id: category.id,
          status: "published" as const,
        } satisfies IDiscussionBoardArticle.ICreate,
      },
    );
    typia.assert(article);
    return { article, expectedCategory: category };
  });

  // Step 5: Retrieve each article and validate category information
  for (const { article, expectedCategory } of articles) {
    const retrievedArticle = await api.functional.discussionBoard.articles.at(
      connection,
      {
        articleId: article.id,
      },
    );
    typia.assert(retrievedArticle);

    // Validate category.id matches assigned category
    TestValidator.equals(
      "category ID matches assigned category",
      retrievedArticle.category.id,
      expectedCategory.id,
    );

    // Validate category.name reflects topic area correctly
    TestValidator.equals(
      "category name reflects topic area",
      retrievedArticle.category.name,
      expectedCategory.name,
    );

    // Validate category.slug is URL-friendly identifier
    TestValidator.equals(
      "category slug is URL-friendly",
      retrievedArticle.category.slug,
      expectedCategory.slug,
    );

    // Validate category.description provides topic guidance
    TestValidator.equals(
      "category description provides topic guidance",
      retrievedArticle.category.description,
      expectedCategory.description,
    );

    // Validate category.sort_order indicates display priority
    TestValidator.equals(
      "category sort_order indicates display priority",
      retrievedArticle.category.sort_order,
      expectedCategory.sort_order,
    );

    // Validate category timestamps match expected category
    TestValidator.equals(
      "category created_at matches expected",
      retrievedArticle.category.created_at,
      expectedCategory.created_at,
    );

    TestValidator.equals(
      "category updated_at matches expected",
      retrievedArticle.category.updated_at,
      expectedCategory.updated_at,
    );
  }

  // Step 6: Verify category consistency - retrieve articles again
  for (const { article, expectedCategory } of articles) {
    const secondRetrieval = await api.functional.discussionBoard.articles.at(
      connection,
      {
        articleId: article.id,
      },
    );
    typia.assert(secondRetrieval);

    TestValidator.equals(
      "category ID remains consistent across retrievals",
      secondRetrieval.category.id,
      expectedCategory.id,
    );

    TestValidator.equals(
      "category data remains consistent",
      secondRetrieval.category.name,
      expectedCategory.name,
    );
  }

  // Step 7: Confirm articles maintain single category assignment
  TestValidator.equals(
    "created correct number of articles",
    articles.length,
    categories.length,
  );

  TestValidator.predicate(
    "each article has exactly one category",
    articles.every(
      ({ article }) =>
        article.category !== null && article.category !== undefined,
    ),
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IDiscussionBoardAccountAction } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardAccountAction";
import type { IDiscussionBoardMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardMember";
import type { IDiscussionBoardModerator } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardModerator";

export async function test_api_account_action_update_reversal(
  connection: api.IConnection,
) {
  // Step 1: Create moderator account for performing moderation operations
  const moderatorEmail = typia.random<string & tags.Format<"email">>();
  const moderator: IDiscussionBoardModerator.IAuthorized =
    await api.functional.auth.moderator.join(connection, {
      body: {
        email: moderatorEmail,
        password: "ModeratorPass123!",
        username: RandomGenerator.alphaNumeric(8),
        display_name: RandomGenerator.name(2),
        href: typia.random<string & tags.Format<"uri">>(),
        referrer: typia.random<string & tags.Format<"uri">>(),
      } satisfies IDiscussionBoardModerator.ICreate,
    });
  typia.assert(moderator);

  // Step 2: Create member account using fresh connection to avoid token pollution
  const memberConnection: api.IConnection = {
    ...connection,
    headers: {},
  };
  const memberEmail = typia.random<string & tags.Format<"email">>();
  const member: IDiscussionBoardMember.IAuthorized =
    await api.functional.auth.member.join(memberConnection, {
      body: {
        email: memberEmail,
        password: "MemberPass123!",
        username: RandomGenerator.alphaNumeric(8),
        display_name: RandomGenerator.name(2),
        href: typia.random<string & tags.Format<"uri">>(),
        referrer: typia.random<string & tags.Format<"uri">>(),
      } satisfies IDiscussionBoardMember.ICreate,
    });
  typia.assert(member);

  // Step 3: Apply a permanent ban to the member account (using moderator-authenticated connection)
  const banReason =
    "Repeated violations of community guidelines - spam and harassment";
  const banAction: IDiscussionBoardAccountAction =
    await api.functional.discussionBoard.moderator.accountActions.create(
      connection,
      {
        body: {
          discussion_board_member_id: member.id,
          action_type: "ban",
          reason: banReason,
          duration_days: null,
        } satisfies IDiscussionBoardAccountAction.ICreate,
      },
    );
  typia.assert(banAction);

  // Validate ban was created with active status
  TestValidator.equals("ban status is active", banAction.status, "active");
  TestValidator.equals("ban action type is ban", banAction.action_type, "ban");
  TestValidator.equals("ban reason matches", banAction.reason, banReason);
  TestValidator.equals(
    "ban duration is null for permanent ban",
    banAction.duration_days,
    null,
  );

  // Step 4: Reverse the ban by updating the action with status='reversed' and reversal_reason
  const reversalReason =
    "Ban applied in error - user was impersonated by malicious actor";
  const reversedAction: IDiscussionBoardAccountAction =
    await api.functional.discussionBoard.moderator.accountActions.update(
      connection,
      {
        actionId: banAction.id,
        body: {
          status: "reversed",
          reversal_reason: reversalReason,
        } satisfies IDiscussionBoardAccountAction.IUpdate,
      },
    );
  typia.assert(reversedAction);

  // Step 5: Validate the reversal was successful
  TestValidator.equals(
    "status changed to reversed",
    reversedAction.status,
    "reversed",
  );
  TestValidator.equals(
    "reversal reason is recorded",
    reversedAction.reversal_reason,
    reversalReason,
  );
  TestValidator.equals(
    "reversed by moderator ID is set",
    reversedAction.reversed_by_moderator_id,
    moderator.id,
  );
  TestValidator.predicate(
    "reversed at timestamp is set",
    reversedAction.reversed_at !== null &&
      reversedAction.reversed_at !== undefined,
  );

  // Validate that original action data is preserved
  TestValidator.equals(
    "original action ID preserved",
    reversedAction.id,
    banAction.id,
  );
  TestValidator.equals(
    "original member ID preserved",
    reversedAction.discussion_board_member_id,
    member.id,
  );
  TestValidator.equals(
    "original moderator ID preserved",
    reversedAction.discussion_board_moderator_id,
    moderator.id,
  );
  TestValidator.equals(
    "original action type preserved",
    reversedAction.action_type,
    "ban",
  );
  TestValidator.equals(
    "original reason preserved",
    reversedAction.reason,
    banReason,
  );
  TestValidator.equals(
    "created at timestamp preserved",
    reversedAction.created_at,
    banAction.created_at,
  );
}

