  TestValidator.equals(
    "created timestamp unchanged",
    updatedAction.created_at,
    accountAction.created_at,
  );
  TestValidator.equals(
    "expires_at timestamp unchanged",
    updatedAction.expires_at,
    accountAction.expires_at,
