    ] as const;
    const categorySlugs = [
      "economic-discussion",
      "political-discussion",
      "general-discussion",
    ] as const;

    const category =
      await api.functional.discussionBoard.moderator.categories.create(
        connection,
        {
          body: {
            name: categoryNames[index],
            slug: categorySlugs[index],
            description: `Category for ${categoryNames[index].toLowerCase()}`,
            sort_order: (index + 1) satisfies number as number,
          } satisfies IDiscussionBoardArticleCategory.ICreate,
        },
      );
    typia.assert(category);
    return category;
  });

  // Step 3: Create multiple member accounts
  const members = await ArrayUtil.asyncRepeat(3, async () => {
    const memberEmail = typia.random<string & tags.Format<"email">>();
    const member = await api.functional.auth.member.join(connection, {
      body: {
        email: memberEmail,
        password: "member1234",
        username: RandomGenerator.name(1),
        display_name: RandomGenerator.name(2),
        bio: RandomGenerator.paragraph({ sentences: 2 }),
        href: typia.random<string & tags.Format<"uri">>(),
        referrer: typia.random<string & tags.Format<"uri">>(),
      } satisfies IDiscussionBoardMember.ICreate,
    });
    typia.assert(member);
    return member;
  });

  // Step 4: Each member creates multiple articles
  const memberArticleCounts = new Map<string, number>();

  for (const member of members) {
    // Login as this member
    await api.functional.auth.member.login(connection, {
      body: {
        email: member.email,
        password: "member1234",
        href: typia.random<string & tags.Format<"uri">>(),
        referrer: typia.random<string & tags.Format<"uri">>(),
      } satisfies IDiscussionBoardMember.ILogin,
    });

    // Create 4-5 articles for this member
    const articleCount = typia.random<
      number & tags.Type<"uint32"> & tags.Minimum<4> & tags.Maximum<5>
    >() satisfies number as number;
    const memberArticles = await ArrayUtil.asyncRepeat(
      articleCount,
      async () => {
        const randomCategory = RandomGenerator.pick(categories);
        const statuses = ["draft", "published"] as const;
        const randomStatus = RandomGenerator.pick(statuses);

        const article =
          await api.functional.discussionBoard.member.articles.create(
            connection,
            {
              body: {
                title: RandomGenerator.paragraph({ sentences: 3 }),
                body: RandomGenerator.content({ paragraphs: 3 }),
                discussion_board_article_category_id: randomCategory.id,
                status: randomStatus,
              } satisfies IDiscussionBoardArticle.ICreate,
            },
          );
        typia.assert(article);
        return article;
      },
    );

    memberArticleCounts.set(member.id, memberArticles.length);
  }

  // Step 5: Select target member (first member) for filtering
  const targetMember = members[0];
  const expectedArticleCount = memberArticleCounts.get(targetMember.id) ?? 0;

  // Step 6: Search articles by target member ID
  const page = 1 satisfies number as number;
  const limit = 100 satisfies number as number;

  const searchResult = await api.functional.discussionBoard.articles.index(
    connection,
    {
      body: {
        discussion_board_member_id: targetMember.id,
        page: page,
        limit: limit,
      } satisfies IDiscussionBoardArticle.IRequest,
    },
  );
  typia.assert(searchResult);

  // Step 7: Verify all returned articles are authored by target member
  TestValidator.predicate(
    "search result should contain articles",
    searchResult.data.length > 0,
  );

  for (const article of searchResult.data) {
    TestValidator.equals(
      "article author ID matches target member ID",
      article.author.id,
      targetMember.id,
    );

    TestValidator.equals(
      "article author username matches target member username",
      article.author.username,
      targetMember.username,
    );

    TestValidator.equals(
      "foreign key matches target member ID",
      article.discussion_board_member_id,
      targetMember.id,
    );
  }

  // Step 8: Verify author summary information is correctly populated
  if (searchResult.data.length > 0) {
    const firstArticle = searchResult.data[0];

    TestValidator.equals(
      "author summary contains correct username",
      firstArticle.author.username,
      targetMember.username,
    );

    if (
      targetMember.display_name !== null &&
      targetMember.display_name !== undefined &&
      firstArticle.author.display_name !== null &&
      firstArticle.author.display_name !== undefined
    ) {
      TestValidator.equals(
        "author summary contains correct display name",
        firstArticle.author.display_name,
        targetMember.display_name,
      );
    }
  }

  // Step 9: Test pagination with smaller page size
  const paginatedPage = 1 satisfies number as number;
  const paginatedLimit = 2 satisfies number as number;

  const paginatedResult = await api.functional.discussionBoard.articles.index(
    connection,
    {
      body: {
        discussion_board_member_id: targetMember.id,
        page: paginatedPage,
        limit: paginatedLimit,
      } satisfies IDiscussionBoardArticle.IRequest,
    },
  );
  typia.assert(paginatedResult);

  TestValidator.predicate(
    "paginated result should have at most 2 items per page",
    paginatedResult.data.length <= 2,
  );

  for (const article of paginatedResult.data) {
    TestValidator.equals(
      "paginated articles also authored by target member",
      article.author.id,
      targetMember.id,
    );
  }

  // Step 10: Verify that articles from other members are excluded
  const otherMemberIds = members
    .filter((m) => m.id !== targetMember.id)
    .map((m) => m.id);

  for (const article of searchResult.data) {
    TestValidator.predicate(
      "no articles from other members should appear",
      !otherMemberIds.includes(article.author.id),
    );
  }
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IDiscussionBoardArticle } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardArticle";
import type { IDiscussionBoardArticleCategory } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardArticleCategory";
import type { IDiscussionBoardMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardMember";
import type { IDiscussionBoardModerator } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardModerator";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IPageIDiscussionBoardArticle } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIDiscussionBoardArticle";

/**
 * Test article visibility filtering with proper authorization rules based on
 * publication status.
 *
 * This test validates that the article search API correctly enforces visibility
 * rules:
 *
 * - Published articles are visible to all users (guests, members, moderators)
 * - Draft articles are visible only to their authors and moderators
 *
 * The test creates articles in different states and verifies search results for
 * different user contexts to ensure proper content access control.
 *
 * Note: Archived status testing is not included as the article creation API
 * only supports "draft" and "published" status values during creation.
 *
 * Test Steps:
 *
 * 1. Create moderator account and article category
 * 2. Create member account (article author)
 * 3. Create articles in different states (published, draft)
 * 4. Test visibility as unauthenticated user (guest)
 * 5. Test visibility as author (should see own drafts)
 * 6. Test visibility as different member (should not see other's drafts)
 * 7. Test visibility as moderator (should see all)
 */
export async function test_api_article_search_status_visibility(
  connection: api.IConnection,
) {
  // Step 1: Create moderator account
  const moderatorEmail = typia.random<string & tags.Format<"email">>();
  const moderator = await api.functional.auth.moderator.join(connection, {
    body: {
      email: moderatorEmail,
      password: "moderator123",
      username: RandomGenerator.alphaNumeric(10),
      display_name: RandomGenerator.name(2),
      href: "https://test.example.com/moderator/join",
      referrer: "https://test.example.com/home",
    } satisfies IDiscussionBoardModerator.ICreate,
  });
  typia.assert(moderator);

  // Step 2: Create article category
  const category =
    await api.functional.discussionBoard.moderator.categories.create(
      connection,
      {
        body: {
          name: "Test Category",
          slug: "test-category",
          description: "Category for testing article visibility",
          sort_order: 1,
        } satisfies IDiscussionBoardArticleCategory.ICreate,
      },
    );
  typia.assert(category);

  // Step 3: Create member account (article author)
  const memberEmail = typia.random<string & tags.Format<"email">>();
  const member = await api.functional.auth.member.join(connection, {
    body: {
      email: memberEmail,
      password: "member123",
      username: RandomGenerator.alphaNumeric(10),
      display_name: RandomGenerator.name(2),
      href: "https://test.example.com/member/join",
      referrer: "https://test.example.com/home",
    } satisfies IDiscussionBoardMember.ICreate,
  });
  typia.assert(member);

  // Step 4: Create articles in different states
  const publishedArticle =
    await api.functional.discussionBoard.member.articles.create(connection, {
      body: {
        title: "Published Article - Visible to All",
        body: RandomGenerator.content({
          paragraphs: 2,
          sentenceMin: 10,
          sentenceMax: 15,
        }),
        discussion_board_article_category_id: category.id,
        status: "published",
      } satisfies IDiscussionBoardArticle.ICreate,
    });
  typia.assert(publishedArticle);

  const draftArticle =
    await api.functional.discussionBoard.member.articles.create(connection, {
      body: {
        title: "Draft Article - Author and Moderator Only",
        body: RandomGenerator.content({
          paragraphs: 2,
          sentenceMin: 10,
          sentenceMax: 15,
        }),
        discussion_board_article_category_id: category.id,
        status: "draft",
      } satisfies IDiscussionBoardArticle.ICreate,
    });
  typia.assert(draftArticle);

  // Step 5: Test as unauthenticated connection (guest user)
  const guestConnection: api.IConnection = { ...connection, headers: {} };

  const guestResults = await api.functional.discussionBoard.articles.index(
    guestConnection,
    {
      body: {
        page: 1,
        limit: 100,
      } satisfies IDiscussionBoardArticle.IRequest,
    },
  );
  typia.assert(guestResults);

  // Guest should only see published articles
  const guestArticleIds = guestResults.data.map((a) => a.id);
  TestValidator.predicate(
    "guest can see published article",
    guestArticleIds.includes(publishedArticle.id),
  );
  TestValidator.predicate(
    "guest cannot see draft article",
    !guestArticleIds.includes(draftArticle.id),
  );

  // Step 6: Test as author (should see own drafts and published)
  await api.functional.auth.member.login(connection, {
    body: {
      email: memberEmail,
      password: "member123",
      href: "https://test.example.com/member/login",
      referrer: "https://test.example.com/home",
    } satisfies IDiscussionBoardMember.ILogin,
  });

  const authorResults = await api.functional.discussionBoard.articles.index(
    connection,
    {
      body: {
        page: 1,
        limit: 100,
      } satisfies IDiscussionBoardArticle.IRequest,
    },
  );
  typia.assert(authorResults);

  const authorArticleIds = authorResults.data.map((a) => a.id);
  TestValidator.predicate(
    "author can see published article",
    authorArticleIds.includes(publishedArticle.id),
  );
  TestValidator.predicate(
    "author can see own draft article",
    authorArticleIds.includes(draftArticle.id),
  );

  // Step 7: Test as different member (should not see other's drafts)
  const otherMemberEmail = typia.random<string & tags.Format<"email">>();
  const otherMember = await api.functional.auth.member.join(connection, {
    body: {
      email: otherMemberEmail,
      password: "member456",
      username: RandomGenerator.alphaNumeric(10),
      display_name: RandomGenerator.name(2),
      href: "https://test.example.com/member/join",
      referrer: "https://test.example.com/home",
    } satisfies IDiscussionBoardMember.ICreate,
  });
  typia.assert(otherMember);

  const otherMemberResults =
    await api.functional.discussionBoard.articles.index(connection, {
      body: {
        page: 1,
        limit: 100,
      } satisfies IDiscussionBoardArticle.IRequest,
    });
  typia.assert(otherMemberResults);

  const otherMemberArticleIds = otherMemberResults.data.map((a) => a.id);
  TestValidator.predicate(
    "other member can see published article",
    otherMemberArticleIds.includes(publishedArticle.id),
  );
  TestValidator.predicate(
    "other member cannot see draft article from different author",
    !otherMemberArticleIds.includes(draftArticle.id),
  );

  // Step 8: Test as moderator (should see all articles)
  await api.functional.auth.moderator.login(connection, {
    body: {
      email: moderatorEmail,
      password: "moderator123",
      href: "https://test.example.com/moderator/login",
      referrer: "https://test.example.com/home",
    } satisfies IDiscussionBoardModerator.ILogin,
  });

  const moderatorResults = await api.functional.discussionBoard.articles.index(
    connection,
    {
      body: {
        page: 1,
        limit: 100,
      } satisfies IDiscussionBoardArticle.IRequest,
    },
  );
  typia.assert(moderatorResults);

  const moderatorArticleIds = moderatorResults.data.map((a) => a.id);
  TestValidator.predicate(
    "moderator can see published article",
    moderatorArticleIds.includes(publishedArticle.id),
  );
  TestValidator.predicate(
    "moderator can see draft article",
    moderatorArticleIds.includes(draftArticle.id),
  );

  // Step 9: Test status filtering with explicit status parameter
  const publishedOnlyResults =
    await api.functional.discussionBoard.articles.index(guestConnection, {
      body: {
        page: 1,
        limit: 100,
        status: "published",
      } satisfies IDiscussionBoardArticle.IRequest,
    });
  typia.assert(publishedOnlyResults);

  const publishedOnlyIds = publishedOnlyResults.data.map((a) => a.id);
  TestValidator.predicate(
    "status filter for published returns published article",
    publishedOnlyIds.includes(publishedArticle.id),
  );
  TestValidator.predicate(
    "status filter for published excludes draft article",
    !publishedOnlyIds.includes(draftArticle.id),
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IDiscussionBoardArticle } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardArticle";
import type { IDiscussionBoardArticleCategory } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardArticleCategory";
import type { IDiscussionBoardMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardMember";
import type { IDiscussionBoardModerator } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardModerator";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IPageIDiscussionBoardArticle } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIDiscussionBoardArticle";

/**
 * Test filtering articles by publication date range using published_after and
 * published_before parameters.
 *
 * This test validates temporal filtering for content discovery by:
 *
 * 1. Creating a moderator and setting up article categories
 * 2. Creating a member and publishing multiple articles
 * 3. Testing published_after filter to find articles after a specific date
 * 4. Testing published_before filter to find articles before a specific date
 * 5. Testing combined date range filtering with both parameters
 * 6. Verifying that only articles within specified time ranges are returned
 */
export async function test_api_article_search_date_range(
  connection: api.IConnection,
) {
  // Step 1: Create moderator account
  const moderatorEmail = typia.random<string & tags.Format<"email">>();
  const moderator = await api.functional.auth.moderator.join(connection, {
    body: {
      email: moderatorEmail,
      password: "moderator123",
      username: RandomGenerator.alphaNumeric(10),
      href: "https://example.com/moderator/join",
      referrer: "https://example.com",
    } satisfies IDiscussionBoardModerator.ICreate,
  });
  typia.assert(moderator);

  // Step 2: Create article category
  const category =
    await api.functional.discussionBoard.moderator.categories.create(
      connection,
      {
        body: {
          name: "Test Category",
          slug: "test-category",
          description: "Category for date range testing",
          sort_order: 1,
        } satisfies IDiscussionBoardArticleCategory.ICreate,
      },
    );
  typia.assert(category);

  // Step 3: Create member account
  const memberEmail = typia.random<string & tags.Format<"email">>();
  await api.functional.auth.member.join(connection, {
    body: {
      email: memberEmail,
      password: "member123",
      username: RandomGenerator.alphaNumeric(10),
      href: "https://example.com/member/join",
      referrer: "https://example.com",
    } satisfies IDiscussionBoardMember.ICreate,
  });

  // Step 4: Create 5 published articles
  const articles: IDiscussionBoardArticle[] = [];

  for (let i = 0; i < 5; i++) {
    const article = await api.functional.discussionBoard.member.articles.create(
      connection,
      {
        body: {
          title: `Article ${i + 1} - ${RandomGenerator.paragraph({ sentences: 3 })}`,
          body: RandomGenerator.content({ paragraphs: 2 }),
          discussion_board_article_category_id: category.id,
          status: "published",
        } satisfies IDiscussionBoardArticle.ICreate,
      },
    );
    typia.assert(article);
    articles.push(article);
  }

  // Sort articles by published_at to ensure predictable ordering
  articles.sort((a, b) => {
    const dateA = a.published_at ? new Date(a.published_at).getTime() : 0;
    const dateB = b.published_at ? new Date(b.published_at).getTime() : 0;
    return dateA - dateB;
  });

  // Step 5: Test published_after filter using actual article timestamps
  const secondArticleDate = articles[1].published_at;
  if (secondArticleDate) {
    const afterResults = await api.functional.discussionBoard.articles.index(
      connection,
      {
        body: {
          published_after: secondArticleDate,
          discussion_board_article_category_id: category.id,
        } satisfies IDiscussionBoardArticle.IRequest,
      },
    );
    typia.assert(afterResults);

    // Validate that all returned articles are published after or at the specified date
    for (const articleSummary of afterResults.data) {
      const articleDate = articleSummary.published_at;
      if (articleDate) {
        TestValidator.predicate(
          "article published_at should be >= published_after filter",
          new Date(articleDate) >= new Date(secondArticleDate),
        );
      }
    }
  }

  // Step 6: Test published_before filter using actual article timestamps
  const fourthArticleDate = articles[3].published_at;
  if (fourthArticleDate) {
    const beforeResults = await api.functional.discussionBoard.articles.index(
      connection,
      {
        body: {
          published_before: fourthArticleDate,
          discussion_board_article_category_id: category.id,
        } satisfies IDiscussionBoardArticle.IRequest,
      },
    );
    typia.assert(beforeResults);

    // Validate that all returned articles are published before or at the specified date
    for (const articleSummary of beforeResults.data) {
      const articleDate = articleSummary.published_at;
      if (articleDate) {
        TestValidator.predicate(
          "article published_at should be <= published_before filter",
          new Date(articleDate) <= new Date(fourthArticleDate),
        );
      }
    }
  }

  // Step 7: Test combined date range using actual article timestamps
  const startDate = articles[1].published_at;
  const endDate = articles[3].published_at;
  if (startDate && endDate) {
    const rangeResults = await api.functional.discussionBoard.articles.index(
      connection,
      {
        body: {
          published_after: startDate,
          published_before: endDate,
          discussion_board_article_category_id: category.id,
        } satisfies IDiscussionBoardArticle.IRequest,
      },
    );
    typia.assert(rangeResults);

    // Validate that all returned articles are within the date range
    for (const articleSummary of rangeResults.data) {
      const articleDate = articleSummary.published_at;
      if (articleDate) {
        const pubDate = new Date(articleDate);
        TestValidator.predicate(
          "article published_at should be >= published_after",
          pubDate >= new Date(startDate),
        );
        TestValidator.predicate(
          "article published_at should be <= published_before",
          pubDate <= new Date(endDate),
        );
      }
    }
  }
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
