import type { IDiscussionBoardMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardMember";
import type { IDiscussionBoardModerator } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardModerator";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IPageIDiscussionBoardArticle } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIDiscussionBoardArticle";

/**
 * Test filtering articles by popularity using min_view_count parameter to
 * surface trending discussions.
 *
 * This test validates the engagement-based content discovery feature that
 * enables users to identify popular and trending discussions by filtering
 * articles based on minimum view count thresholds.
 *
 * Test Process:
 *
 * 1. Create moderator account and establish article category
 * 2. Create member account to author test articles
 * 3. Create multiple published articles with varying engagement levels
 * 4. Search articles without view count filter to establish baseline
 * 5. Search with min_view_count parameter to test popularity filtering
 * 6. Verify articles can be sorted by view_count to show most popular first
 * 7. Validate that only articles meeting the view threshold are returned
 * 8. Confirm proper pagination and article summary structure
 */
export async function test_api_article_search_popularity_filtering(
  connection: api.IConnection,
) {
  // Step 1: Create moderator account for category management
  const moderatorEmail = typia.random<string & tags.Format<"email">>();
  const moderator: IDiscussionBoardModerator.IAuthorized =
    await api.functional.auth.moderator.join(connection, {
      body: {
        email: moderatorEmail,
        password: typia.random<string & tags.Format<"password">>(),
        username: RandomGenerator.alphaNumeric(10),
        display_name: RandomGenerator.name(2),
        ip: "127.0.0.1",
        href: "https://test.example.com/moderator/join",
        referrer: "https://test.example.com/home",
      } satisfies IDiscussionBoardModerator.ICreate,
    });
  typia.assert(moderator);

  // Step 2: Create article category for organizing test articles
  const category: IDiscussionBoardArticleCategory =
    await api.functional.discussionBoard.moderator.categories.create(
      connection,
      {
        body: {
          name: "Economic Discussion",
          slug: "economic-discussion",
          description: "Discussions about economic policies and market trends",
          sort_order: 1,
        } satisfies IDiscussionBoardArticleCategory.ICreate,
      },
    );
  typia.assert(category);

  // Step 3: Create member account to author articles
  const memberEmail = typia.random<string & tags.Format<"email">>();
  const member: IDiscussionBoardMember.IAuthorized =
    await api.functional.auth.member.join(connection, {
      body: {
        email: memberEmail,
        password: typia.random<string & tags.Format<"password">>(),
        username: RandomGenerator.alphaNumeric(10),
        display_name: RandomGenerator.name(2),
        bio: RandomGenerator.paragraph({ sentences: 5 }),
        ip: "127.0.0.1",
        href: "https://test.example.com/member/join",
        referrer: "https://test.example.com/home",
      } satisfies IDiscussionBoardMember.ICreate,
    });
  typia.assert(member);

  // Step 4: Create multiple published articles for popularity testing
  const articleCount = 5;
  const articles: IDiscussionBoardArticle[] = await ArrayUtil.asyncRepeat(
    articleCount,
    async (index) => {
      const article: IDiscussionBoardArticle =
        await api.functional.discussionBoard.member.articles.create(
          connection,
          {
            body: {
              title: `Article ${index + 1}: ${RandomGenerator.paragraph({ sentences: 3 })}`,
              body: RandomGenerator.content({
                paragraphs: 3,
                sentenceMin: 10,
                sentenceMax: 20,
              }),
              discussion_board_article_category_id: category.id,
              status: "published",
            } satisfies IDiscussionBoardArticle.ICreate,
          },
        );
      typia.assert(article);
      return article;
    },
  );

  // Step 5: Search articles without view count filter (baseline)
  const baselineSearch: IPageIDiscussionBoardArticle.ISummary =
    await api.functional.discussionBoard.articles.index(connection, {
      body: {
        page: 1,
        limit: 20,
        status: "published",
        discussion_board_article_category_id: category.id,
      } satisfies IDiscussionBoardArticle.IRequest,
    });
  typia.assert(baselineSearch);

  TestValidator.equals(
    "baseline search returns all created articles",
    baselineSearch.data.length,
    articleCount,
  );

  // Step 6: Search with min_view_count filter set to 0 (should return all articles)
  const zeroViewFilter: IPageIDiscussionBoardArticle.ISummary =
    await api.functional.discussionBoard.articles.index(connection, {
      body: {
        page: 1,
        limit: 20,
        status: "published",
        discussion_board_article_category_id: category.id,
        min_view_count: 0,
      } satisfies IDiscussionBoardArticle.IRequest,
    });
  typia.assert(zeroViewFilter);

  TestValidator.equals(
    "min_view_count of 0 returns all articles",
    zeroViewFilter.data.length,
    articleCount,
  );

  // Step 7: Verify all articles have view_count field and it's non-negative
  await ArrayUtil.asyncForEach(zeroViewFilter.data, async (article) => {
    TestValidator.predicate(
      "article has non-negative view_count",
      article.view_count >= 0,
    );
  });

  // Step 8: Search with sorting by view_count descending
  const sortedByViews: IPageIDiscussionBoardArticle.ISummary =
    await api.functional.discussionBoard.articles.index(connection, {
      body: {
        page: 1,
        limit: 20,
        status: "published",
        discussion_board_article_category_id: category.id,
        sort_by: "view_count",
        sort_order: "desc",
      } satisfies IDiscussionBoardArticle.IRequest,
    });
  typia.assert(sortedByViews);

  TestValidator.equals(
    "sorted search returns all articles",
    sortedByViews.data.length,
    articleCount,
  );

  // Step 9: Verify descending sort order by view_count
  for (let i = 0; i < sortedByViews.data.length - 1; i++) {
    TestValidator.predicate(
      `article ${i} view_count >= article ${i + 1} view_count`,
      sortedByViews.data[i].view_count >= sortedByViews.data[i + 1].view_count,
    );
  }

  // Step 10: Test filtering with higher min_view_count threshold
  const highThreshold = 1000;
  const highViewFilter: IPageIDiscussionBoardArticle.ISummary =
    await api.functional.discussionBoard.articles.index(connection, {
      body: {
        page: 1,
        limit: 20,
        status: "published",
        discussion_board_article_category_id: category.id,
        min_view_count: highThreshold,
      } satisfies IDiscussionBoardArticle.IRequest,
    });
  typia.assert(highViewFilter);

  // Verify all returned articles meet the minimum view count threshold
  await ArrayUtil.asyncForEach(highViewFilter.data, async (article) => {
    TestValidator.predicate(
      `article view_count >= ${highThreshold}`,
      article.view_count >= highThreshold,
    );
  });

  // Step 11: Verify pagination structure
  TestValidator.predicate(
    "pagination current page is valid",
    baselineSearch.pagination.current >= 1,
  );
  TestValidator.predicate(
    "pagination limit matches request",
    baselineSearch.pagination.limit === 20,
  );
  TestValidator.predicate(
    "pagination records count is non-negative",
    baselineSearch.pagination.records >= 0,
  );
  TestValidator.predicate(
    "pagination pages count is valid",
    baselineSearch.pagination.pages >= 0,
  );

  // Step 12: Validate article summary structure - business logic validation
  const sampleArticle = baselineSearch.data[0];
  typia.assert(sampleArticle);
  TestValidator.predicate(
    "article has category reference",
    sampleArticle.discussion_board_article_category_id === category.id,
  );
  TestValidator.predicate(
    "article has author reference",
    sampleArticle.discussion_board_member_id === member.id,
  );
  TestValidator.equals(
    "article status is published",
    sampleArticle.status,
    "published",
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IDiscussionBoardArticle } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardArticle";
import type { IDiscussionBoardArticleCategory } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardArticleCategory";
import type { IDiscussionBoardMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardMember";
import type { IDiscussionBoardModerator } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardModerator";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IPageIDiscussionBoardArticle } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIDiscussionBoardArticle";

/**
 * Test various sorting options for article search functionality.
 *
 * This test validates that the article search API correctly handles different
 * sorting criteria including published_at, created_at, updated_at, and
 * view_count with both ascending and descending order. Creates multiple
 * articles with varied timestamps and engagement metrics to verify proper
 * ordering.
 *
 * Steps:
 *
 * 1. Create moderator account and article category
 * 2. Create member account to author test articles
 * 3. Create 5 published articles
 * 4. Test sort_by published_at DESC (newest first)
 * 5. Test sort_by view_count DESC (most popular first)
 * 6. Test sort_by updated_at DESC (recently modified)
 * 7. Test sort_by created_at ASC and DESC (chronological ordering)
 * 8. Verify results are correctly ordered for each sorting option
 */
export async function test_api_article_search_sorting_options(
  connection: api.IConnection,
) {
  // Step 1: Create moderator account
  const moderatorEmail = typia.random<string & tags.Format<"email">>();
  const moderator = await api.functional.auth.moderator.join(connection, {
    body: {
      email: moderatorEmail,
      password: "moderator123!",
      username: RandomGenerator.alphaNumeric(8),
      display_name: RandomGenerator.name(),
      ip: "127.0.0.1",
      href: "https://test.example.com/moderator/join" satisfies string &
        tags.Format<"uri">,
      referrer: "https://test.example.com" satisfies string &
        tags.Format<"uri">,
    } satisfies IDiscussionBoardModerator.ICreate,
  });
  typia.assert(moderator);

  // Step 2: Create article category
  const category =
    await api.functional.discussionBoard.moderator.categories.create(
      connection,
      {
        body: {
          name: "Test Category for Sorting",
          slug: "test-sorting-category",
          description: "Category for testing article sorting functionality",
          sort_order: 1 satisfies number & tags.Type<"int32"> & tags.Minimum<0>,
        } satisfies IDiscussionBoardArticleCategory.ICreate,
      },
    );
  typia.assert(category);

  // Step 3: Create member account
  const memberEmail = typia.random<string & tags.Format<"email">>();
  const member = await api.functional.auth.member.join(connection, {
    body: {
      email: memberEmail,
      password: "member123!",
      username: RandomGenerator.alphaNumeric(8),
      display_name: RandomGenerator.name(),
      bio: RandomGenerator.paragraph({ sentences: 2 }),
      ip: "127.0.0.1",
      href: "https://test.example.com/member/join" satisfies string &
        tags.Format<"uri">,
      referrer: "https://test.example.com" satisfies string &
        tags.Format<"uri">,
    } satisfies IDiscussionBoardMember.ICreate,
  });
  typia.assert(member);

  // Step 4: Create multiple articles
  const articles: IDiscussionBoardArticle[] = [];

  const articleData = [
    { title: "First Article - Old", bodyPrefix: "This is the oldest article" },
    {
      title: "Second Article - Medium Old",
      bodyPrefix: "This is a medium-old article",
    },
    { title: "Third Article - Recent", bodyPrefix: "This is a recent article" },
    {
      title: "Fourth Article - Medium",
      bodyPrefix: "This is a medium article",
    },
    {
      title: "Fifth Article - Newest",
      bodyPrefix: "This is the newest article",
    },
  ];

  for (const data of articleData) {
    const article = await api.functional.discussionBoard.member.articles.create(
      connection,
      {
        body: {
          title: data.title,
          body: `${data.bodyPrefix}. ${RandomGenerator.content({ paragraphs: 1, sentenceMin: 10, sentenceMax: 15 })}`,
          discussion_board_article_category_id: category.id,
          status: "published" as const,
        } satisfies IDiscussionBoardArticle.ICreate,
      },
    );
    typia.assert(article);
    articles.push(article);
  }

  // Step 5: Test sorting by published_at DESC (newest first)
  const sortByPublishedDesc =
    await api.functional.discussionBoard.articles.index(connection, {
      body: {
        page: 1 satisfies number & tags.Type<"int32"> & tags.Minimum<1>,
        limit: 10 satisfies number &
          tags.Type<"int32"> &
          tags.Minimum<1> &
          tags.Maximum<100>,
        discussion_board_article_category_id: category.id,
        status: "published" as const,
        sort_by: "published_at" as const,
        sort_order: "desc" as const,
      } satisfies IDiscussionBoardArticle.IRequest,
    });
  typia.assert(sortByPublishedDesc);

  TestValidator.predicate(
    "published_at DESC returns articles",
    sortByPublishedDesc.data.length === 5,
  );

  // Verify descending order by published_at
  for (let i = 0; i < sortByPublishedDesc.data.length - 1; i++) {
    const currentPublished = sortByPublishedDesc.data[i].published_at;
    const nextPublished = sortByPublishedDesc.data[i + 1].published_at;
    typia.assertGuard(currentPublished!);
    typia.assertGuard(nextPublished!);

    const current = new Date(currentPublished).getTime();
    const next = new Date(nextPublished).getTime();
    TestValidator.predicate(
      `published_at DESC order check: article ${i} >= article ${i + 1}`,
      current >= next,
    );
  }

  // Step 6: Test sorting by view_count DESC (most popular first)
  const sortByViewCountDesc =
    await api.functional.discussionBoard.articles.index(connection, {
      body: {
        page: 1 satisfies number & tags.Type<"int32"> & tags.Minimum<1>,
        limit: 10 satisfies number &
          tags.Type<"int32"> &
          tags.Minimum<1> &
          tags.Maximum<100>,
        discussion_board_article_category_id: category.id,
        status: "published" as const,
        sort_by: "view_count" as const,
        sort_order: "desc" as const,
      } satisfies IDiscussionBoardArticle.IRequest,
    });
  typia.assert(sortByViewCountDesc);

  TestValidator.predicate(
    "view_count DESC returns articles",
    sortByViewCountDesc.data.length === 5,
  );

  // Verify descending order by view_count
  for (let i = 0; i < sortByViewCountDesc.data.length - 1; i++) {
    const current = sortByViewCountDesc.data[i].view_count;
    const next = sortByViewCountDesc.data[i + 1].view_count;
    TestValidator.predicate(
      `view_count DESC order check: article ${i} (${current}) >= article ${i + 1} (${next})`,
      current >= next,
    );
  }

  // Step 7: Test sorting by updated_at DESC (recently modified first)
  const sortByUpdatedDesc = await api.functional.discussionBoard.articles.index(
    connection,
    {
      body: {
        page: 1 satisfies number & tags.Type<"int32"> & tags.Minimum<1>,
        limit: 10 satisfies number &
          tags.Type<"int32"> &
          tags.Minimum<1> &
          tags.Maximum<100>,
        discussion_board_article_category_id: category.id,
        status: "published" as const,
        sort_by: "updated_at" as const,
        sort_order: "desc" as const,
      } satisfies IDiscussionBoardArticle.IRequest,
    },
  );
  typia.assert(sortByUpdatedDesc);

  TestValidator.predicate(
    "updated_at DESC returns articles",
    sortByUpdatedDesc.data.length === 5,
  );

  // Verify descending order by updated_at
  for (let i = 0; i < sortByUpdatedDesc.data.length - 1; i++) {
    const current = new Date(sortByUpdatedDesc.data[i].updated_at).getTime();
    const next = new Date(sortByUpdatedDesc.data[i + 1].updated_at).getTime();
    TestValidator.predicate(
      `updated_at DESC order check: article ${i} >= article ${i + 1}`,
      current >= next,
    );
  }

  // Step 8: Test sorting by created_at ASC (oldest first)
  const sortByCreatedAsc = await api.functional.discussionBoard.articles.index(
    connection,
    {
      body: {
        page: 1 satisfies number & tags.Type<"int32"> & tags.Minimum<1>,
        limit: 10 satisfies number &
          tags.Type<"int32"> &
          tags.Minimum<1> &
          tags.Maximum<100>,
        discussion_board_article_category_id: category.id,
        status: "published" as const,
        sort_by: "created_at" as const,
        sort_order: "asc" as const,
      } satisfies IDiscussionBoardArticle.IRequest,
    },
  );
  typia.assert(sortByCreatedAsc);

  TestValidator.predicate(
    "created_at ASC returns articles",
    sortByCreatedAsc.data.length === 5,
  );

  // Verify ascending order by created_at
  for (let i = 0; i < sortByCreatedAsc.data.length - 1; i++) {
    const current = new Date(sortByCreatedAsc.data[i].created_at).getTime();
    const next = new Date(sortByCreatedAsc.data[i + 1].created_at).getTime();
    TestValidator.predicate(
      `created_at ASC order check: article ${i} <= article ${i + 1}`,
      current <= next,
    );
  }

  // Step 9: Test sorting by created_at DESC (newest first)
  const sortByCreatedDesc = await api.functional.discussionBoard.articles.index(
    connection,
    {
      body: {
        page: 1 satisfies number & tags.Type<"int32"> & tags.Minimum<1>,
        limit: 10 satisfies number &
          tags.Type<"int32"> &
          tags.Minimum<1> &
          tags.Maximum<100>,
        discussion_board_article_category_id: category.id,
        status: "published" as const,
        sort_by: "created_at" as const,
        sort_order: "desc" as const,
      } satisfies IDiscussionBoardArticle.IRequest,
    },
  );
  typia.assert(sortByCreatedDesc);

  TestValidator.predicate(
    "created_at DESC returns articles",
    sortByCreatedDesc.data.length === 5,
  );

  // Verify descending order by created_at
  for (let i = 0; i < sortByCreatedDesc.data.length - 1; i++) {
    const current = new Date(sortByCreatedDesc.data[i].created_at).getTime();
    const next = new Date(sortByCreatedDesc.data[i + 1].created_at).getTime();
    TestValidator.predicate(
      `created_at DESC order check: article ${i} >= article ${i + 1}`,
      current >= next,
    );
  }

  // Step 10: Verify that ASC and DESC produce reversed orderings
  TestValidator.predicate(
    "ASC and DESC orderings are reversed",
    sortByCreatedAsc.data[0].id ===
      sortByCreatedDesc.data[sortByCreatedDesc.data.length - 1].id,
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IDiscussionBoardArticle } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardArticle";
import type { IDiscussionBoardArticleCategory } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardArticleCategory";
import type { IDiscussionBoardMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardMember";
import type { IDiscussionBoardModerator } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardModerator";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IPageIDiscussionBoardArticle } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIDiscussionBoardArticle";

/**
 * Test pagination functionality with page and limit parameters to navigate
 * through large article result sets.
 *
 * This test validates that the article search API properly handles pagination
 * by:
 *
 * 1. Creating sufficient test data (30 published articles)
 * 2. Testing navigation across multiple pages with consistent page size
 * 3. Verifying pagination metadata (current page, total records, total pages,
 *    limit)
 * 4. Ensuring different pages return different result sets
 * 5. Validating that the limit parameter controls page size up to maximum of 100
 *
 * The test creates a complete test environment with moderator, category,
 * member, and multiple articles, then performs comprehensive pagination
 * validation to ensure efficient navigation through large result sets.
 */
export async function test_api_article_search_pagination(
  connection: api.IConnection,
) {
  // Step 1: Create moderator account for category management
  const moderatorEmail = typia.random<string & tags.Format<"email">>();
  const moderator = await api.functional.auth.moderator.join(connection, {
    body: {
      email: moderatorEmail,
      password: typia.random<string & tags.Format<"password">>(),
      username: RandomGenerator.name(1),
      display_name: RandomGenerator.name(2),
      href: typia.random<string & tags.Format<"uri">>(),
      referrer: typia.random<string & tags.Format<"uri">>(),
    } satisfies IDiscussionBoardModerator.ICreate,
  });
  typia.assert(moderator);

  // Step 2: Create article category for test articles
  const category =
    await api.functional.discussionBoard.moderator.categories.create(
      connection,
      {
        body: {
          name: "Test Category " + RandomGenerator.name(1),
          slug: "test-category-" + RandomGenerator.alphabets(8),
          description: RandomGenerator.paragraph({ sentences: 3 }),
          sort_order: 1,
        } satisfies IDiscussionBoardArticleCategory.ICreate,
      },
    );
  typia.assert(category);

  // Step 3: Create member account for authoring articles
  const memberEmail = typia.random<string & tags.Format<"email">>();
  const member = await api.functional.auth.member.join(connection, {
    body: {
      email: memberEmail,
      password: typia.random<string & tags.Format<"password">>(),
      username: RandomGenerator.name(1),
      display_name: RandomGenerator.name(2),
      href: typia.random<string & tags.Format<"uri">>(),
      referrer: typia.random<string & tags.Format<"uri">>(),
    } satisfies IDiscussionBoardMember.ICreate,
  });
  typia.assert(member);

  // Step 4: Create 30 published articles for pagination testing
  const articleCount = 30;
  const createdArticles = await ArrayUtil.asyncRepeat(
    articleCount,
    async (index) => {
      const article =
        await api.functional.discussionBoard.member.articles.create(
          connection,
          {
            body: {
              title: `Test Article ${index + 1} - ${RandomGenerator.name(3)}`,
              body: RandomGenerator.content({
                paragraphs: 3,
                sentenceMin: 10,
                sentenceMax: 20,
              }),
              discussion_board_article_category_id: category.id,
              status: "published",
            } satisfies IDiscussionBoardArticle.ICreate,
          },
        );
      typia.assert(article);
      return article;
    },
  );

  // Step 5: Test pagination with limit=10 across multiple pages
  const limit = 10;

  // Test page 1
  const page1Result = await api.functional.discussionBoard.articles.index(
    connection,
    {
      body: {
        page: 1,
        limit: limit,
        discussion_board_article_category_id: category.id,
      } satisfies IDiscussionBoardArticle.IRequest,
    },
  );
  typia.assert(page1Result);

  // Verify page 1 pagination metadata
  TestValidator.equals(
    "page 1 current page",
    page1Result.pagination.current,
    1,
  );
  TestValidator.equals("page 1 limit", page1Result.pagination.limit, limit);
  TestValidator.equals(
    "page 1 total records",
    page1Result.pagination.records,
    articleCount,
  );
  TestValidator.equals(
    "page 1 total pages",
    page1Result.pagination.pages,
    Math.ceil(articleCount / limit),
  );
  TestValidator.equals("page 1 data length", page1Result.data.length, limit);

  // Test page 2
  const page2Result = await api.functional.discussionBoard.articles.index(
    connection,
    {
      body: {
        page: 2,
        limit: limit,
        discussion_board_article_category_id: category.id,
      } satisfies IDiscussionBoardArticle.IRequest,
    },
  );
  typia.assert(page2Result);

  // Verify page 2 pagination metadata
  TestValidator.equals(
    "page 2 current page",
    page2Result.pagination.current,
    2,
  );
  TestValidator.equals("page 2 limit", page2Result.pagination.limit, limit);
  TestValidator.equals(
    "page 2 total records",
    page2Result.pagination.records,
    articleCount,
  );
  TestValidator.equals("page 2 data length", page2Result.data.length, limit);

  // Test page 3
  const page3Result = await api.functional.discussionBoard.articles.index(
    connection,
    {
      body: {
        page: 3,
        limit: limit,
        discussion_board_article_category_id: category.id,
      } satisfies IDiscussionBoardArticle.IRequest,
    },
  );
  typia.assert(page3Result);

  // Verify page 3 pagination metadata
  TestValidator.equals(
    "page 3 current page",
    page3Result.pagination.current,
    3,
  );
  TestValidator.equals("page 3 limit", page3Result.pagination.limit, limit);
  TestValidator.equals(
    "page 3 total records",
    page3Result.pagination.records,
    articleCount,
  );
  TestValidator.equals("page 3 data length", page3Result.data.length, limit);

  // Step 6: Verify different pages return different result sets
  const page1Ids = page1Result.data.map((article) => article.id);
  const page2Ids = page2Result.data.map((article) => article.id);
  const page3Ids = page3Result.data.map((article) => article.id);

  // Check no overlap between page 1 and page 2
  const page1And2Overlap = page1Ids.filter((id) => page2Ids.includes(id));
  TestValidator.equals(
    "no overlap between page 1 and 2",
    page1And2Overlap.length,
    0,
  );

  // Check no overlap between page 2 and page 3
  const page2And3Overlap = page2Ids.filter((id) => page3Ids.includes(id));
  TestValidator.equals(
    "no overlap between page 2 and 3",
    page2And3Overlap.length,
    0,
  );

  // Check no overlap between page 1 and page 3
  const page1And3Overlap = page1Ids.filter((id) => page3Ids.includes(id));
  TestValidator.equals(
    "no overlap between page 1 and 3",
    page1And3Overlap.length,
    0,
  );

  // Step 7: Test different limit values
  const limit5Result = await api.functional.discussionBoard.articles.index(
    connection,
    {
      body: {
        page: 1,
        limit: 5,
        discussion_board_article_category_id: category.id,
      } satisfies IDiscussionBoardArticle.IRequest,
    },
  );
  typia.assert(limit5Result);
  TestValidator.equals("limit 5 data length", limit5Result.data.length, 5);
  TestValidator.equals(
    "limit 5 pagination limit",
    limit5Result.pagination.limit,
    5,
  );

  const limit20Result = await api.functional.discussionBoard.articles.index(
    connection,
    {
      body: {
        page: 1,
        limit: 20,
        discussion_board_article_category_id: category.id,
      } satisfies IDiscussionBoardArticle.IRequest,
    },
  );
  typia.assert(limit20Result);
  TestValidator.equals("limit 20 data length", limit20Result.data.length, 20);
  TestValidator.equals(
    "limit 20 pagination limit",
    limit20Result.pagination.limit,
    20,
  );

  const limit50Result = await api.functional.discussionBoard.articles.index(
    connection,
    {
      body: {
        page: 1,
        limit: 50,
        discussion_board_article_category_id: category.id,
      } satisfies IDiscussionBoardArticle.IRequest,
    },
  );
  typia.assert(limit50Result);
  TestValidator.equals(
    "limit 50 data length",
    limit50Result.data.length,
    articleCount,
  );
  TestValidator.equals(
    "limit 50 pagination limit",
    limit50Result.pagination.limit,
    50,
  );

  // Step 8: Test maximum limit constraint (100 items)
  const limit100Result = await api.functional.discussionBoard.articles.index(
    connection,
    {
      body: {
        page: 1,
        limit: 100,
        discussion_board_article_category_id: category.id,
      } satisfies IDiscussionBoardArticle.IRequest,
    },
  );
  typia.assert(limit100Result);
  TestValidator.equals(
    "limit 100 pagination limit",
    limit100Result.pagination.limit,
    100,
  );
  TestValidator.equals(
    "limit 100 data length",
    limit100Result.data.length,
    articleCount,
  );

  // Step 9: Verify last page has correct number of items
  const totalPages = Math.ceil(articleCount / limit);
  const lastPageResult = await api.functional.discussionBoard.articles.index(
    connection,
    {
      body: {
        page: totalPages,
        limit: limit,
        discussion_board_article_category_id: category.id,
      } satisfies IDiscussionBoardArticle.IRequest,
    },
  );
  typia.assert(lastPageResult);

  const expectedLastPageItems = articleCount - limit * (totalPages - 1);
  TestValidator.equals(
    "last page data length",
    lastPageResult.data.length,
    expectedLastPageItems,
  );
  TestValidator.equals(
    "last page current",
    lastPageResult.pagination.current,
    totalPages,
  );
}

