    deleted_at: article.deleted_at
      ? toISOStringSafe(article.deleted_at)
      : undefined,
    author: {
      id: article.author.id,
      username: article.author.username,
      display_name:
        article.author.display_name === null
          ? undefined
          : article.author.display_name,
    },
    category: {
