import { HttpException } from "@nestjs/common";
import { Prisma } from "@prisma/client";
import jwt from "jsonwebtoken";
import typia, { tags } from "typia";
import { v4 } from "uuid";
import { MyGlobal } from "../MyGlobal";
import { PasswordUtil } from "../utils/PasswordUtil";
import { toISOStringSafe } from "../utils/toISOStringSafe";

import { IDiscussionBoardGuest } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardGuest";
import { IPageIDiscussionBoardGuest } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIDiscussionBoardGuest";
import { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import { ModeratorPayload } from "../decorators/payload/ModeratorPayload";

export async function patchDiscussionBoardModeratorGuests(props: {
  moderator: ModeratorPayload;
  body: IDiscussionBoardGuest.IRequest;
}): Promise<IPageIDiscussionBoardGuest.ISummary> {
  const page = props.body.page ?? 1;
  const limit = props.body.limit ?? 100;
  const skip = (page - 1) * limit;

  const buildWhereCondition = () => {
    const conditions: Record<string, unknown> = {};

    if (props.body.search) {
      conditions.OR = [
        { session_identifier: { contains: props.body.search } },
        { ip_address: { contains: props.body.search } },
        { user_agent: { contains: props.body.search } },
      ];
    }

    if (props.body.ip_address) {
      conditions.ip_address = { contains: props.body.ip_address };
    }

    if (props.body.user_agent_contains) {
      conditions.user_agent = { contains: props.body.user_agent_contains };
    }

    if (props.body.first_visit_from || props.body.first_visit_to) {
      const first_visit_at: Record<string, Date> = {};
      if (props.body.first_visit_from) {
        first_visit_at.gte = new Date(props.body.first_visit_from);
      }
      if (props.body.first_visit_to) {
        first_visit_at.lte = new Date(props.body.first_visit_to);
      }
      conditions.first_visit_at = first_visit_at;
    }

    if (props.body.last_visit_from || props.body.last_visit_to) {
      const last_visit_at: Record<string, Date> = {};
      if (props.body.last_visit_from) {
        last_visit_at.gte = new Date(props.body.last_visit_from);
      }
      if (props.body.last_visit_to) {
        last_visit_at.lte = new Date(props.body.last_visit_to);
      }
      conditions.last_visit_at = last_visit_at;
    }

    if (
      props.body.min_page_views !== undefined ||
      props.body.max_page_views !== undefined
    ) {
      const page_views: Record<string, number> = {};
      if (props.body.min_page_views !== undefined) {
        page_views.gte = props.body.min_page_views;
      }
      if (props.body.max_page_views !== undefined) {
        page_views.lte = props.body.max_page_views;
      }
      conditions.page_views = page_views;
    }

    return conditions;
  };

  const whereCondition = buildWhereCondition();
  const orderByField = props.body.sort_by ?? "last_visit_at";
  const orderDirection = props.body.order ?? "desc";

  const [data, total] = await Promise.all([
    MyGlobal.prisma.discussion_board_guests.findMany({
      where: whereCondition,
      skip,
      take: limit,
      orderBy: { [orderByField]: orderDirection },
    }),
    MyGlobal.prisma.discussion_board_guests.count({ where: whereCondition }),
  ]);

  return {
    pagination: {
      current: page,
      limit: limit,
      records: total,
      pages: Math.ceil(total / limit),
    },
    data: data.map((guest) => ({
      id: guest.id,
      session_identifier: guest.session_identifier,
      first_visit_at: toISOStringSafe(guest.first_visit_at),
      last_visit_at: toISOStringSafe(guest.last_visit_at),
      page_views: guest.page_views,
      created_at: toISOStringSafe(guest.created_at),
      updated_at: toISOStringSafe(guest.updated_at),
    })),
  };
}

import { HttpException } from "@nestjs/common";
import { Prisma } from "@prisma/client";
import jwt from "jsonwebtoken";
import typia, { tags } from "typia";
import { v4 } from "uuid";
import { MyGlobal } from "../MyGlobal";
import { PasswordUtil } from "../utils/PasswordUtil";
import { toISOStringSafe } from "../utils/toISOStringSafe";

import { IDiscussionBoardPasswordReset } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardPasswordReset";

export async function patchDiscussionBoardPasswordResets(props: {
  body: IDiscussionBoardPasswordReset.ICreate;
}): Promise<IDiscussionBoardPasswordReset> {
  const { actor_type, email } = props.body;

  // Verify the email exists in the appropriate table
  let accountId: string | null = null;

  if (actor_type === "member") {
    const member = await MyGlobal.prisma.discussion_board_members.findUnique({
      where: { email },
      select: { id: true },
    });
    if (member) {
      accountId = member.id;
    }
  } else if (actor_type === "moderator") {
    const moderator =
      await MyGlobal.prisma.discussion_board_moderators.findUnique({
        where: { email },
        select: { id: true },
      });
    if (moderator) {
      accountId = moderator.id;
    }
  }

  // Security: Don't reveal whether email exists to prevent account enumeration
  if (!accountId) {
    throw new HttpException(
      "If the email exists, a password reset link will be sent.",
      200,
    );
  }

  // Generate cryptographically secure token
  const resetId = v4();
  const token = require("crypto").randomBytes(32).toString("hex");
  const nowTimestamp = Date.now();
  const expiresAtTimestamp = nowTimestamp + 60 * 60 * 1000; // 1 hour from now
  const nowISO = toISOStringSafe(new Date(nowTimestamp));
  const expiresAtISO = toISOStringSafe(new Date(expiresAtTimestamp));

  // Invalidate previous active reset tokens for this account
  if (actor_type === "member") {
    const previousResets =
      await MyGlobal.prisma.discussion_board_password_reset_of_members.findMany(
        {
          where: { discussion_board_member_id: accountId },
          select: {
            discussion_board_password_reset_id: true,
          },
        },
      );

    if (previousResets.length > 0) {
      await MyGlobal.prisma.discussion_board_password_resets.updateMany({
        where: {
          id: {
            in: previousResets.map((r) => r.discussion_board_password_reset_id),
          },
          used_at: null,
          expires_at: { gt: nowISO },
        },
        data: { used_at: nowISO },
      });
    }
  } else {
    const previousResets =
      await MyGlobal.prisma.discussion_board_password_reset_of_moderators.findMany(
        {
          where: { discussion_board_moderator_id: accountId },
          select: {
            discussion_board_password_reset_id: true,
          },
        },
      );

    if (previousResets.length > 0) {
      await MyGlobal.prisma.discussion_board_password_resets.updateMany({
        where: {
          id: {
            in: previousResets.map((r) => r.discussion_board_password_reset_id),
          },
          used_at: null,
          expires_at: { gt: nowISO },
        },
        data: { used_at: nowISO },
      });
    }
  }

  // Create password reset record and subtype record in transaction
  const resetRecord = await MyGlobal.prisma.$transaction(async (tx) => {
    const reset = await tx.discussion_board_password_resets.create({
      data: {
        id: resetId,
        actor_type,
        token,
        email,
        expires_at: expiresAtISO,
        used_at: null,
        created_at: nowISO,
      },
    });

    if (actor_type === "member") {
      await tx.discussion_board_password_reset_of_members.create({
        data: {
          id: v4(),
          discussion_board_password_reset_id: resetId,
          discussion_board_member_id: accountId,
          created_at: nowISO,
        },
      });
    } else {
      await tx.discussion_board_password_reset_of_moderators.create({
        data: {
          id: v4(),
          discussion_board_password_reset_id: resetId,
          discussion_board_moderator_id: accountId,
          created_at: nowISO,
        },
      });
    }

    return reset;
  });

  return {
    id: resetRecord.id,
    actor_type: typia.assert<"member" | "moderator">(resetRecord.actor_type),
    token: resetRecord.token,
    email: resetRecord.email,
    expires_at: toISOStringSafe(resetRecord.expires_at),
    used_at: resetRecord.used_at ? toISOStringSafe(resetRecord.used_at) : null,
    created_at: toISOStringSafe(resetRecord.created_at),
  };
}

import { HttpException } from "@nestjs/common";
import { Prisma } from "@prisma/client";
import jwt from "jsonwebtoken";
import typia, { tags } from "typia";
import { v4 } from "uuid";
import { MyGlobal } from "../MyGlobal";
import { PasswordUtil } from "../utils/PasswordUtil";
import { toISOStringSafe } from "../utils/toISOStringSafe";

import { IDiscussionBoardGuest } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardGuest";
import { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";

export async function postAuthGuestJoin(props: {
  body: IDiscussionBoardGuest.ICreate;
}): Promise<IDiscussionBoardGuest.IAuthorized> {
  const existing = await MyGlobal.prisma.discussion_board_guests.findUnique({
    where: { session_identifier: props.body.session_identifier },
  });

  if (existing) {
    throw new HttpException("Session identifier already exists", 409);
  }

  const now = toISOStringSafe(new Date());
  const guestId = v4();

  const guest = await MyGlobal.prisma.discussion_board_guests.create({
    data: {
      id: guestId,
      session_identifier: props.body.session_identifier,
      ip_address: props.body.ip_address ?? "",
      user_agent: props.body.user_agent,
      first_visit_at: now,
      last_visit_at: now,
      page_views: 0,
      created_at: now,
      updated_at: now,
    },
  });

  const accessExpires = new Date(Date.now() + 60 * 60 * 1000);
  const refreshExpires = new Date(Date.now() + 7 * 24 * 60 * 60 * 1000);

  const token = {
    access: jwt.sign(
      {
        type: "guest",
        id: guest.id,
        session_id: guest.id,
        created_at: now,
      },
      MyGlobal.env.JWT_SECRET_KEY,
      {
        expiresIn: "1h",
        issuer: "autobe",
      },
    ),
    refresh: jwt.sign(
      {
        type: "guest",
        id: guest.id,
        session_id: guest.id,
        tokenType: "refresh",
        created_at: now,
      },
      MyGlobal.env.JWT_SECRET_KEY,
      {
        expiresIn: "7d",
        issuer: "autobe",
      },
    ),
    expired_at: toISOStringSafe(accessExpires),
    refreshable_until: toISOStringSafe(refreshExpires),
  };

  return {
    id: guest.id,
    session_identifier: guest.session_identifier,
    ip_address: guest.ip_address,
    user_agent: guest.user_agent,
    first_visit_at: toISOStringSafe(guest.first_visit_at),
    last_visit_at: toISOStringSafe(guest.last_visit_at),
    page_views: guest.page_views,
    created_at: toISOStringSafe(guest.created_at),
    updated_at: toISOStringSafe(guest.updated_at),
    token,
  };
}

