export async function patchDiscussionBoardModeratorModerationLogs(props: {
  moderator: ModeratorPayload;
  body: IDiscussionBoardModerationLog.IRequest;
}): Promise<IPageIDiscussionBoardModerationLog.ISummary> {
  const page = props.body.page ?? 1;
  const limit = props.body.limit ?? 20;
  const skip = (page - 1) * limit;

  const sortBy = props.body.sort_by ?? "created_at";
  const order = props.body.order ?? "desc";

  const whereCondition: Record<string, unknown> = {};

  if (props.body.action_types && props.body.action_types.length > 0) {
    whereCondition.action_type = { in: props.body.action_types };
  }

  if (props.body.moderator_id) {
    whereCondition.discussion_board_moderator_id = props.body.moderator_id;
  }

  if (props.body.article_id) {
    whereCondition.discussion_board_article_id = props.body.article_id;
  }

  if (props.body.member_id) {
    whereCondition.discussion_board_member_id = props.body.member_id;
  }

  if (props.body.from_date || props.body.to_date) {
    const dateRange: Record<string, unknown> = {};
    if (props.body.from_date) {
      dateRange.gte = new Date(props.body.from_date);
    }
    if (props.body.to_date) {
      dateRange.lte = new Date(props.body.to_date);
    }
    whereCondition.created_at = dateRange;
  }

  const [logs, total] = await Promise.all([
    MyGlobal.prisma.discussion_board_moderation_logs.findMany({
      where: whereCondition,
      skip,
      take: limit,
      orderBy:
        sortBy === "created_at"
          ? { created_at: order }
          : { action_type: order },
    }),
    MyGlobal.prisma.discussion_board_moderation_logs.count({
      where: whereCondition,
    }),
  ]);

  const logSummaries = logs.map((log) => ({
    id: log.id,
    discussion_board_moderator_id: log.discussion_board_moderator_id,
    discussion_board_article_id: log.discussion_board_article_id,
    discussion_board_member_id: log.discussion_board_member_id,
    action_type: log.action_type,
    reason: log.reason,
    action_details: log.action_details,
    created_at: toISOStringSafe(log.created_at),
  }));

  return {
    pagination: {
      current: page,
      limit: limit,
      records: total,
      pages: Math.ceil(total / limit),
    },
    data: logSummaries as any,
  };
}

import { HttpException } from "@nestjs/common";
import { Prisma } from "@prisma/client";
import jwt from "jsonwebtoken";
import typia, { tags } from "typia";
import { v4 } from "uuid";
import { MyGlobal } from "../MyGlobal";
import { PasswordUtil } from "../utils/PasswordUtil";
import { toISOStringSafe } from "../utils/toISOStringSafe";

import { IDiscussionBoardMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardMember";
import { MemberPayload } from "../decorators/payload/MemberPayload";

export async function postAuthMemberPasswordChange(props: {
  member: MemberPayload;
  body: IDiscussionBoardMember.IChangePassword;
}): Promise<IDiscussionBoardMember.IPasswordChanged> {
  const member = await MyGlobal.prisma.discussion_board_members.findUnique({
    where: { id: props.member.id },
  });

  if (!member) {
    throw new HttpException("Member not found", 404);
  }

  const isCurrentPasswordValid = await PasswordUtil.verify(
    props.body.currentPassword,
    member.password,
  );

  if (!isCurrentPasswordValid) {
    throw new HttpException("Current password is incorrect", 401);
  }

  const newPasswordHash = await PasswordUtil.hash(props.body.newPassword);

  await MyGlobal.prisma.discussion_board_members.update({
    where: { id: props.member.id },
    data: {
      password: newPasswordHash,
      updated_at: new Date(),
    },
  });

  await MyGlobal.prisma.discussion_board_member_sessions.updateMany({
    where: {
      discussion_board_member_id: props.member.id,
      id: { not: props.member.session_id },
      expired_at: null,
    },
    data: {
      expired_at: new Date(),
    },
  });

  return {
    message:
      "Password has been changed successfully. All other sessions have been invalidated.",
  };
}

import { HttpException } from "@nestjs/common";
import { Prisma } from "@prisma/client";
import jwt from "jsonwebtoken";
import typia, { tags } from "typia";
import { v4 } from "uuid";
import { MyGlobal } from "../MyGlobal";
import { PasswordUtil } from "../utils/PasswordUtil";
import { toISOStringSafe } from "../utils/toISOStringSafe";

import { IDiscussionBoardMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardMember";

export async function postAuthMemberPasswordResetComplete(props: {
  body: IDiscussionBoardMember.IResetPassword;
}): Promise<IDiscussionBoardMember.IPasswordResetCompleted> {
  const resetRecord =
    await MyGlobal.prisma.discussion_board_password_resets.findUnique({
      where: { token: props.body.token },
      include: {
        discussion_board_password_reset_of_members: true,
      },
    });

  if (!resetRecord) {
    throw new HttpException("Invalid or expired password reset token.", 400);
  }

  if (resetRecord.actor_type !== "member") {
    throw new HttpException("Invalid password reset token.", 400);
  }

  const currentTime = new Date();
  if (currentTime >= resetRecord.expires_at) {
    throw new HttpException("Password reset token has expired.", 400);
  }

  if (resetRecord.used_at !== null) {
    throw new HttpException("Password reset token has already been used.", 400);
  }

  if (!resetRecord.discussion_board_password_reset_of_members) {
    throw new HttpException(
      "Password reset token is not associated with a member account.",
      404,
    );
  }

  const memberContext = resetRecord.discussion_board_password_reset_of_members;
  const memberId = memberContext.discussion_board_member_id;

  const hashedPassword = await PasswordUtil.hash(props.body.password);

  await MyGlobal.prisma.discussion_board_members.update({
    where: { id: memberId },
    data: {
      password: hashedPassword,
      updated_at: currentTime,
    },
  });

  await MyGlobal.prisma.discussion_board_password_resets.update({
    where: { id: resetRecord.id },
    data: {
      used_at: currentTime,
    },
  });

  await MyGlobal.prisma.discussion_board_member_sessions.updateMany({
    where: {
      discussion_board_member_id: memberId,
      expired_at: null,
    },
    data: {
      expired_at: currentTime,
    },
  });

  return {
    success: true,
    message:
      "Password has been successfully reset. Please login with your new password.",
  };
}

import { HttpException } from "@nestjs/common";
