import { HttpException } from "@nestjs/common";
import { Prisma } from "@prisma/client";
import jwt from "jsonwebtoken";
import typia, { tags } from "typia";
import { v4 } from "uuid";
import { MyGlobal } from "../MyGlobal";
import { PasswordUtil } from "../utils/PasswordUtil";
import { toISOStringSafe } from "../utils/toISOStringSafe";

import { IDiscussionBoardGuest } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardGuest";
import { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import { GuestPayload } from "../decorators/payload/GuestPayload";

export async function postAuthGuestRefresh(props: {
  guest: GuestPayload;
  body: IDiscussionBoardGuest.IRefresh;
}): Promise<IDiscussionBoardGuest.IAuthorized> {
  let decoded: {
    id: string;
    session_id: string;
    type: "guest";
  };

  try {
    decoded = jwt.verify(
      props.body.refresh_token,
      MyGlobal.env.JWT_SECRET_KEY,
      { issuer: "autobe" },
    ) as {
      id: string;
      session_id: string;
      type: "guest";
    };
  } catch (error) {
    throw new HttpException("Invalid or expired refresh token", 401);
  }

  if (decoded.type !== "guest") {
    throw new HttpException("Invalid token type", 403);
  }

  const guest = await MyGlobal.prisma.discussion_board_guests.findUnique({
    where: {
      id: decoded.id,
    },
  });

  if (!guest) {
    throw new HttpException("Session expired or revoked", 401);
  }

  const nowTimestamp = Date.now();
  const nowISO = new Date(nowTimestamp).toISOString();
  const accessExpiresISO = new Date(
    nowTimestamp + 60 * 60 * 1000,
  ).toISOString();
  const refreshExpiresISO = new Date(
    nowTimestamp + 7 * 24 * 60 * 60 * 1000,
  ).toISOString();

  const accessToken = jwt.sign(
    {
      type: decoded.type,
      id: decoded.id,
      session_id: decoded.session_id,
      created_at: nowISO,
    },
    MyGlobal.env.JWT_SECRET_KEY,
    {
      expiresIn: "1h",
      issuer: "autobe",
    },
  );

  const refreshToken = jwt.sign(
    {
      type: decoded.type,
      id: decoded.id,
      session_id: decoded.session_id,
      tokenType: "refresh",
      created_at: nowISO,
    },
    MyGlobal.env.JWT_SECRET_KEY,
    {
      expiresIn: "7d",
      issuer: "autobe",
    },
  );

  const updated = await MyGlobal.prisma.discussion_board_guests.update({
    where: {
      id: guest.id,
    },
    data: {
      last_visit_at: new Date(nowTimestamp),
    },
  });

  return {
    id: updated.id,
    session_identifier: updated.session_identifier,
    ip_address: updated.ip_address,
    user_agent: updated.user_agent,
    first_visit_at: toISOStringSafe(updated.first_visit_at),
    last_visit_at: toISOStringSafe(updated.last_visit_at),
    page_views: updated.page_views,
    created_at: toISOStringSafe(updated.created_at),
    updated_at: toISOStringSafe(updated.updated_at),
    token: {
      access: accessToken,
      refresh: refreshToken,
      expired_at: accessExpiresISO as string & tags.Format<"date-time">,
      refreshable_until: refreshExpiresISO as string & tags.Format<"date-time">,
    },
  };
}

import { HttpException } from "@nestjs/common";
import { Prisma } from "@prisma/client";
import jwt from "jsonwebtoken";
import typia, { tags } from "typia";
import { v4 } from "uuid";
import { MyGlobal } from "../MyGlobal";
import { PasswordUtil } from "../utils/PasswordUtil";
import { toISOStringSafe } from "../utils/toISOStringSafe";

import { IDiscussionBoardMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardMember";
import { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";

export async function postAuthMemberJoin(props: {
  body: IDiscussionBoardMember.ICreate;
}): Promise<IDiscussionBoardMember.IAuthorized> {
  const existingEmail =
    await MyGlobal.prisma.discussion_board_members.findFirst({
      where: { email: props.body.email },
    });
  if (existingEmail) {
    throw new HttpException("Email address is already registered", 409);
  }

  const existingUsername =
    await MyGlobal.prisma.discussion_board_members.findFirst({
      where: { username: props.body.username },
    });
  if (existingUsername) {
    throw new HttpException("Username is already taken", 409);
  }

  const hashedPassword: string = await PasswordUtil.hash(props.body.password);

  const now = new Date();
  const member = await MyGlobal.prisma.discussion_board_members.create({
    data: {
      id: v4(),
      email: props.body.email,
      password: hashedPassword,
      username: props.body.username,
      display_name: props.body.display_name ?? null,
      bio: props.body.bio ?? null,
      avatar_url: null,
      email_verified: false,
      email_verified_at: null,
      is_suspended: false,
      suspension_reason: null,
      suspended_until: null,
      last_login_at: null,
      created_at: now,
      updated_at: now,
      deleted_at: null,
    },
  });

  const verificationExpiresAt = new Date(Date.now() + 24 * 60 * 60 * 1000);
  await MyGlobal.prisma.discussion_board_email_verifications.create({
    data: {
      id: v4(),
      discussion_board_member_id: member.id,
      token: v4(),
      email: props.body.email,
      expires_at: verificationExpiresAt,
      verified_at: null,
      created_at: now,
    },
  });

  const accessExpires = new Date(Date.now() + 30 * 60 * 1000);
  const refreshExpires = new Date(Date.now() + 7 * 24 * 60 * 60 * 1000);
  const session = await MyGlobal.prisma.discussion_board_member_sessions.create(
    {
      data: {
        id: v4(),
        discussion_board_member_id: member.id,
        ip: props.body.ip ?? "0.0.0.0",
        href: props.body.href,
        referrer: props.body.referrer,
        created_at: now,
        expired_at: null,
      },
    },
  );

  const token = {
    access: jwt.sign(
      {
        type: "member",
        id: member.id,
        session_id: session.id,
        created_at: toISOStringSafe(now),
      },
      MyGlobal.env.JWT_SECRET_KEY,
      {
        expiresIn: "30m",
        issuer: "autobe",
      },
    ),
    refresh: jwt.sign(
      {
        type: "member",
        id: member.id,
        session_id: session.id,
        tokenType: "refresh",
        created_at: toISOStringSafe(now),
      },
      MyGlobal.env.JWT_SECRET_KEY,
      {
        expiresIn: "7d",
        issuer: "autobe",
      },
    ),
    expired_at: toISOStringSafe(accessExpires),
    refreshable_until: toISOStringSafe(refreshExpires),
  };

  return {
    id: member.id,
    email: member.email,
    username: member.username,
    display_name: member.display_name ?? null,
    bio: member.bio ?? null,
    avatar_url: member.avatar_url ?? null,
    email_verified: member.email_verified,
    email_verified_at: member.email_verified_at
      ? toISOStringSafe(member.email_verified_at)
      : null,
    is_suspended: member.is_suspended,
    suspension_reason: member.suspension_reason ?? null,
    suspended_until: member.suspended_until
      ? toISOStringSafe(member.suspended_until)
      : null,
    last_login_at: member.last_login_at
      ? toISOStringSafe(member.last_login_at)
      : null,
    created_at: toISOStringSafe(member.created_at),
    updated_at: toISOStringSafe(member.updated_at),
    deleted_at: member.deleted_at ? toISOStringSafe(member.deleted_at) : null,
    token,
  };
}

import { HttpException } from "@nestjs/common";
import { Prisma } from "@prisma/client";
import jwt from "jsonwebtoken";
import typia, { tags } from "typia";
import { v4 } from "uuid";
import { MyGlobal } from "../MyGlobal";
import { PasswordUtil } from "../utils/PasswordUtil";
import { toISOStringSafe } from "../utils/toISOStringSafe";

import { IDiscussionBoardMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardMember";
import { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";

export async function postAuthMemberLogin(props: {
  body: IDiscussionBoardMember.ILogin;
}): Promise<IDiscussionBoardMember.IAuthorized> {
  // Phase 1: Find member by email (case-insensitive)
  const member = await MyGlobal.prisma.discussion_board_members.findFirst({
    where: {
      email: props.body.email.toLowerCase(),
    },
  });

  if (!member) {
    throw new HttpException("Invalid email or password", 401);
  }

  // Check if account is deleted
  if (member.deleted_at !== null) {
    throw new HttpException("Account has been deleted", 403);
  }

  // Check if account is suspended
  if (member.is_suspended) {
    const suspensionMessage = member.suspension_reason
      ? `Account is suspended: ${member.suspension_reason}`
      : "Account is suspended";
    throw new HttpException(suspensionMessage, 403);
  }

  // Phase 2: Verify password
  const isPasswordValid = await PasswordUtil.verify(
    props.body.password,
    member.password,
  );

  if (!isPasswordValid) {
    throw new HttpException("Invalid email or password", 401);
  }

  // Phase 3: Update last login timestamp
  const now = new Date();
  await MyGlobal.prisma.discussion_board_members.update({
    where: { id: member.id },
    data: {
      last_login_at: now,
      updated_at: now,
    },
  });

  // Phase 4: Create new session
  const accessExpiresAt = new Date(Date.now() + 60 * 60 * 1000); // 1 hour
  const refreshExpiresAt = new Date(Date.now() + 7 * 24 * 60 * 60 * 1000); // 7 days

  const session = await MyGlobal.prisma.discussion_board_member_sessions.create(
    {
      data: {
        id: v4(),
        discussion_board_member_id: member.id,
        ip: props.body.ip ?? "unknown",
        href: props.body.href,
        referrer: props.body.referrer,
        created_at: now,
        expired_at: null,
      },
    },
  );

  // Phase 5: Generate JWT tokens
  const tokenCreatedAt = toISOStringSafe(now);

  const token: IAuthorizationToken = {
    access: jwt.sign(
      {
        type: "member",
        id: member.id,
        session_id: session.id,
        created_at: tokenCreatedAt,
      },
      MyGlobal.env.JWT_SECRET_KEY,
      {
        expiresIn: "1h",
        issuer: "autobe",
      },
    ),
    refresh: jwt.sign(
      {
        type: "member",
        id: member.id,
        session_id: session.id,
        tokenType: "refresh",
        created_at: tokenCreatedAt,
      },
      MyGlobal.env.JWT_SECRET_KEY,
      {
        expiresIn: "7d",
        issuer: "autobe",
      },
    ),
    expired_at: toISOStringSafe(accessExpiresAt),
    refreshable_until: toISOStringSafe(refreshExpiresAt),
  };

  // Phase 6: Return authorized member with token
  return {
    id: member.id,
    email: member.email,
    username: member.username,
    display_name:
      member.display_name === null ? undefined : member.display_name,
    bio: member.bio === null ? undefined : member.bio,
    avatar_url: member.avatar_url === null ? undefined : member.avatar_url,
    email_verified: member.email_verified,
    email_verified_at:
      member.email_verified_at === null
        ? undefined
        : toISOStringSafe(member.email_verified_at),
    is_suspended: member.is_suspended,
    suspension_reason:
      member.suspension_reason === null ? undefined : member.suspension_reason,
    suspended_until:
      member.suspended_until === null
        ? undefined
        : toISOStringSafe(member.suspended_until),
    last_login_at: toISOStringSafe(now),
    created_at: toISOStringSafe(member.created_at),
    updated_at: toISOStringSafe(now),
    deleted_at:
      member.deleted_at === null
        ? undefined
        : toISOStringSafe(member.deleted_at),
    token,
  };
}

import { HttpException } from "@nestjs/common";
import { Prisma } from "@prisma/client";
import jwt from "jsonwebtoken";
import typia, { tags } from "typia";
import { v4 } from "uuid";
import { MyGlobal } from "../MyGlobal";
import { PasswordUtil } from "../utils/PasswordUtil";
import { toISOStringSafe } from "../utils/toISOStringSafe";

import { IDiscussionBoardMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardMember";
import { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";

export async function postAuthMemberRefresh(props: {
  body: IDiscussionBoardMember.IRefresh;
}): Promise<IDiscussionBoardMember.IAuthorized> {
  let decoded: {
    id: string;
    session_id: string;
    type: "member";
  };

  try {
    decoded = jwt.verify(
      props.body.refresh_token,
      MyGlobal.env.JWT_SECRET_KEY,
      { issuer: "autobe" },
    ) as {
      id: string;
      session_id: string;
      type: "member";
    };
  } catch (error) {
    throw new HttpException("Invalid or expired refresh token", 401);
  }

  if (decoded.type !== "member") {
    throw new HttpException("Invalid token type", 403);
  }

  const session =
    await MyGlobal.prisma.discussion_board_member_sessions.findFirst({
      where: {
        id: decoded.session_id,
        discussion_board_member_id: decoded.id,
        expired_at: null,
      },
      include: {
        member: true,
      },
    });

  if (!session) {
    throw new HttpException("Session expired or revoked", 401);
  }

  if (session.member.deleted_at !== null) {
    throw new HttpException("Account has been deleted", 403);
  }

  if (session.member.is_suspended) {
    throw new HttpException(
      session.member.suspension_reason ?? "Account is suspended",
      403,
    );
  }

  const now: string & tags.Format<"date-time"> = toISOStringSafe(new Date());
  const accessExpiresMs: number = Date.now() + 30 * 60 * 1000;
  const refreshExpiresMs: number = Date.now() + 7 * 24 * 60 * 60 * 1000;
  const accessExpires: string & tags.Format<"date-time"> = toISOStringSafe(
    new Date(accessExpiresMs),
  );
  const refreshExpires: string & tags.Format<"date-time"> = toISOStringSafe(
    new Date(refreshExpiresMs),
  );

  const accessToken: string = jwt.sign(
    {
      type: "member",
      id: decoded.id,
      session_id: decoded.session_id,
      created_at: now,
    },
    MyGlobal.env.JWT_SECRET_KEY,
    {
      expiresIn: "30m",
      issuer: "autobe",
    },
  );

  const refreshToken: string = jwt.sign(
    {
      type: "member",
      id: decoded.id,
      session_id: decoded.session_id,
      tokenType: "refresh",
      created_at: now,
    },
    MyGlobal.env.JWT_SECRET_KEY,
    {
      expiresIn: "7d",
      issuer: "autobe",
    },
  );

  await MyGlobal.prisma.discussion_board_member_sessions.update({
    where: {
      id: decoded.session_id,
    },
    data: {
      expired_at: new Date(refreshExpiresMs),
    },
  });

  const token: IAuthorizationToken = {
    access: accessToken,
    refresh: refreshToken,
    expired_at: accessExpires,
    refreshable_until: refreshExpires,
  };

  return {
    id: session.member.id,
    email: session.member.email,
    username: session.member.username,
    display_name: session.member.display_name ?? undefined,
    bio: session.member.bio ?? undefined,
    avatar_url: session.member.avatar_url ?? undefined,
    email_verified: session.member.email_verified,
    email_verified_at: session.member.email_verified_at
      ? toISOStringSafe(session.member.email_verified_at)
      : undefined,
    is_suspended: session.member.is_suspended,
    suspension_reason: session.member.suspension_reason ?? undefined,
    suspended_until: session.member.suspended_until
      ? toISOStringSafe(session.member.suspended_until)
      : undefined,
    last_login_at: session.member.last_login_at
      ? toISOStringSafe(session.member.last_login_at)
      : undefined,
    created_at: toISOStringSafe(session.member.created_at),
    updated_at: toISOStringSafe(session.member.updated_at),
    deleted_at: session.member.deleted_at
      ? toISOStringSafe(session.member.deleted_at)
      : undefined,
    token,
  };
}

import { HttpException } from "@nestjs/common";
import { Prisma } from "@prisma/client";
import jwt from "jsonwebtoken";
import typia, { tags } from "typia";
import { v4 } from "uuid";
import { MyGlobal } from "../MyGlobal";
import { PasswordUtil } from "../utils/PasswordUtil";
import { toISOStringSafe } from "../utils/toISOStringSafe";

import { IDiscussionBoardMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardMember";

export async function postAuthMemberEmailVerify(props: {
  body: IDiscussionBoardMember.IVerifyEmail;
}): Promise<IDiscussionBoardMember> {
  const verification =
    await MyGlobal.prisma.discussion_board_email_verifications.findUnique({
      where: { token: props.body.token },
    });

  if (!verification) {
    throw new HttpException("Invalid or expired verification token", 404);
  }

  if (verification.verified_at !== null) {
    throw new HttpException(
      "This verification token has already been used",
      400,
    );
  }

  const now = new Date();
  if (now > verification.expires_at) {
    throw new HttpException("Verification token has expired", 400);
  }

  const [updatedMember] = await Promise.all([
    MyGlobal.prisma.discussion_board_members.update({
      where: { id: verification.discussion_board_member_id },
